--
-- Name: grant_pg_cron_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_cron_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
  END IF;
END;
$$;


--
-- Name: FUNCTION grant_pg_cron_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_cron_access() IS 'Grants access to pg_cron';


--
-- Name: grant_pg_graphql_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_graphql_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    func_is_graphql_resolve bool;
BEGIN
    func_is_graphql_resolve = (
        SELECT n.proname = 'resolve'
        FROM pg_event_trigger_ddl_commands() AS ev
        LEFT JOIN pg_catalog.pg_proc AS n
        ON ev.objid = n.oid
    );

    IF func_is_graphql_resolve
    THEN
        -- Update public wrapper to pass all arguments through to the pg_graphql resolve func
        DROP FUNCTION IF EXISTS graphql_public.graphql;
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language sql
        as $$
            select graphql.resolve(
                query := query,
                variables := coalesce(variables, '{}'),
                "operationName" := "operationName",
                extensions := extensions
            );
        $$;

        -- This hook executes when `graphql.resolve` is created. That is not necessarily the last
        -- function in the extension so we need to grant permissions on existing entities AND
        -- update default permissions to any others that are created after `graphql.resolve`
        grant usage on schema graphql to postgres, anon, authenticated, service_role;
        grant select on all tables in schema graphql to postgres, anon, authenticated, service_role;
        grant execute on all functions in schema graphql to postgres, anon, authenticated, service_role;
        grant all on all sequences in schema graphql to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on tables to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on functions to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on sequences to postgres, anon, authenticated, service_role;

        -- Allow postgres role to allow granting usage on graphql and graphql_public schemas to custom roles
        grant usage on schema graphql_public to postgres with grant option;
        grant usage on schema graphql to postgres with grant option;
    END IF;

END;
$_$;


--
-- Name: FUNCTION grant_pg_graphql_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_graphql_access() IS 'Grants access to pg_graphql';


--
-- Name: grant_pg_net_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_net_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
    ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

    ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
    ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

    REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
    REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

    GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
  END IF;
END;
$$;


--
-- Name: FUNCTION grant_pg_net_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_net_access() IS 'Grants access to pg_net';


--
-- Name: pgrst_ddl_watch(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.pgrst_ddl_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.command_tag IN (
      'CREATE SCHEMA', 'ALTER SCHEMA'
    , 'CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO', 'ALTER TABLE'
    , 'CREATE FOREIGN TABLE', 'ALTER FOREIGN TABLE'
    , 'CREATE VIEW', 'ALTER VIEW'
    , 'CREATE MATERIALIZED VIEW', 'ALTER MATERIALIZED VIEW'
    , 'CREATE FUNCTION', 'ALTER FUNCTION'
    , 'CREATE TRIGGER'
    , 'CREATE TYPE', 'ALTER TYPE'
    , 'CREATE RULE'
    , 'COMMENT'
    )
    -- don't notify in case of CREATE TEMP table or other objects created on pg_temp
    AND cmd.schema_name is distinct from 'pg_temp'
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


--
-- Name: pgrst_drop_watch(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.pgrst_drop_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
  LOOP
    IF obj.object_type IN (
      'schema'
    , 'table'
    , 'foreign table'
    , 'view'
    , 'materialized view'
    , 'function'
    , 'trigger'
    , 'type'
    , 'rule'
    )
    AND obj.is_temporary IS false -- no pg_temp objects
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


--
-- Name: set_graphql_placeholder(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.set_graphql_placeholder() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$_$;


--
-- Name: FUNCTION set_graphql_placeholder(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.set_graphql_placeholder() IS 'Reintroduces placeholder function for graphql_public.graphql';


--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: -
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $_$
begin
    raise debug 'PgBouncer auth request: %', p_usename;

    return query
    select 
        rolname::text, 
        case when rolvaliduntil < now() 
            then null 
            else rolpassword::text 
        end 
    from pg_authid 
    where rolname=$1 and rolcanlogin;
end;
$_$;


--
-- Name: calculate_segment_performance_score(double precision, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_segment_performance_score(p_retention_rate double precision, p_likes integer, p_comments integer, p_shares integer, p_views integer) RETURNS double precision
    LANGUAGE plpgsql
    AS $$
DECLARE
    engagement_rate FLOAT;
    performance_score FLOAT;
BEGIN
    -- Calculate engagement rate
    IF p_views > 0 THEN
        engagement_rate := (p_likes + p_comments + p_shares)::FLOAT / p_views;
    ELSE
        engagement_rate := 0;
    END IF;
    
    -- Weighted score formula
    -- Retention: 40%, Engagement: 30%, Shares: 20%, Comments: 10%
    performance_score := 
        (COALESCE(p_retention_rate, 0) * 0.4) +
        (LEAST(engagement_rate, 0.2) / 0.2 * 0.3) +  -- Cap at 20% engagement
        (LEAST(p_shares::FLOAT / GREATEST(p_views, 1), 0.05) / 0.05 * 0.2) +  -- Cap at 5% share rate
        (LEAST(p_comments::FLOAT / GREATEST(p_views, 1), 0.1) / 0.1 * 0.1);  -- Cap at 10% comment rate
    
    RETURN LEAST(performance_score, 1.0);  -- Cap at 1.0
END;
$$;


--
-- Name: claim_queue_job(character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_queue_job(p_agent_type character varying, p_worker_id character varying) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    job_id UUID;
BEGIN
    UPDATE agent_queue
    SET status = 'running',
        claimed_by = p_worker_id,
        claimed_at = NOW(),
        started_at = NOW()
    WHERE id = (
        SELECT id FROM agent_queue
        WHERE agent_type = p_agent_type
        AND status = 'queued'
        ORDER BY priority DESC, created_at ASC
        LIMIT 1
        FOR UPDATE SKIP LOCKED
    )
    RETURNING id INTO job_id;
    
    RETURN job_id;
END;
$$;


--
-- Name: cleanup_old_agent_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_agent_events() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    DELETE FROM agent_events WHERE created_at < NOW() - INTERVAL '7 days';
END;
$$;


--
-- Name: cleanup_old_event_history(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_old_event_history(days_to_keep integer DEFAULT 30) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    deleted_count INTEGER;
BEGIN
    DELETE FROM event_history 
    WHERE timestamp < NOW() - (days_to_keep || ' days')::INTERVAL;
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$;


--
-- Name: complete_queue_job(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_queue_job(p_job_id uuid, p_success boolean DEFAULT true, p_error_message text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE agent_queue
    SET status = CASE WHEN p_success THEN 'completed' ELSE 'failed' END,
        completed_at = NOW(),
        error_message = p_error_message,
        updated_at = NOW()
    WHERE id = p_job_id;
END;
$$;


--
-- Name: find_segment_gaps(uuid, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_segment_gaps(p_video_id uuid, p_min_gap_seconds double precision DEFAULT 1.0) RETURNS TABLE(gap_start double precision, gap_end double precision, gap_duration double precision)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    WITH ordered_segments AS (
        SELECT 
            start_time,
            end_time,
            LEAD(start_time) OVER (ORDER BY start_time) as next_start
        FROM video_segments
        WHERE video_id = p_video_id
        ORDER BY start_time
    )
    SELECT 
        end_time as gap_start,
        next_start as gap_end,
        next_start - end_time as gap_duration
    FROM ordered_segments
    WHERE next_start IS NOT NULL
        AND (next_start - end_time) >= p_min_gap_seconds;
END;
$$;


--
-- Name: get_clip_performance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_clip_performance(p_clip_id uuid) RETURNS TABLE(total_views bigint, total_likes bigint, total_shares bigint, total_comments bigint, avg_engagement_rate double precision, platform_breakdown jsonb)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        SUM(pc.total_views)::BIGINT as total_views,
        SUM(pc.total_likes)::BIGINT as total_likes,
        SUM(pc.total_shares)::BIGINT as total_shares,
        SUM(pc.total_comments)::BIGINT as total_comments,
        AVG(
            CASE 
                WHEN pc.total_views > 0 
                THEN ((pc.total_likes + pc.total_shares + pc.total_comments)::FLOAT / pc.total_views)
                ELSE 0
            END
        )::FLOAT as avg_engagement_rate,
        jsonb_object_agg(
            cp.platform,
            jsonb_build_object(
                'views', pc.total_views,
                'likes', pc.total_likes,
                'shares', pc.total_shares,
                'comments', pc.total_comments
            )
        ) as platform_breakdown
    FROM clip_posts cp
    INNER JOIN platform_posts pp ON cp.post_id = pp.id
    LEFT JOIN LATERAL (
        SELECT 
            MAX(views) as total_views,
            MAX(likes) as total_likes,
            MAX(shares) as total_shares,
            MAX(comments) as total_comments
        FROM platform_checkbacks
        WHERE post_id = pp.id
    ) pc ON true
    WHERE cp.clip_id = p_clip_id
    GROUP BY cp.clip_id;
END;
$$;


--
-- Name: get_next_queue_items(integer, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_queue_items(p_limit integer DEFAULT 10, p_platform character varying DEFAULT NULL::character varying) RETURNS TABLE(id uuid, content_item_id uuid, clip_id uuid, platform character varying, scheduled_for timestamp with time zone, priority integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        q.id,
        q.content_item_id,
        q.clip_id,
        q.platform,
        q.scheduled_for,
        q.priority
    FROM publishing_queue q
    WHERE q.status = 'queued'
        AND q.scheduled_for <= NOW()
        AND (p_platform IS NULL OR q.platform = p_platform)
    ORDER BY q.priority DESC, q.scheduled_for ASC
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED;  -- Prevent concurrent processing
END;
$$;


--
-- Name: get_queue_statistics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_queue_statistics() RETURNS TABLE(status character varying, platform character varying, count bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        q.status,
        q.platform,
        COUNT(*) as count
    FROM publishing_queue q
    GROUP BY q.status, q.platform
    ORDER BY q.status, q.platform;
END;
$$;


--
-- Name: get_video_clips_with_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_video_clips_with_status(p_video_id uuid) RETURNS TABLE(clip_id uuid, title character varying, start_time double precision, end_time double precision, duration double precision, clip_type character varying, ai_score double precision, status character varying, post_count bigint, platforms character varying[])
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        vc.id,
        vc.title,
        vc.start_time,
        vc.end_time,
        vc.duration,
        vc.clip_type,
        vc.ai_score,
        vc.status,
        COUNT(DISTINCT cp.post_id) as post_count,
        ARRAY_AGG(DISTINCT cp.platform) FILTER (WHERE cp.platform IS NOT NULL) as platforms
    FROM video_clips vc
    LEFT JOIN clip_posts cp ON vc.id = cp.clip_id
    WHERE vc.video_id = p_video_id
    GROUP BY vc.id
    ORDER BY vc.created_at DESC;
END;
$$;


--
-- Name: link_ai_generation_to_videos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_ai_generation_to_videos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'completed' AND NEW.output_url IS NOT NULL AND NEW.video_id IS NULL THEN
        INSERT INTO videos (user_id, source_type, source_uri, file_name, duration_sec, resolution, aspect_ratio)
        VALUES (
            COALESCE(NEW.user_id, '00000000-0000-0000-0000-000000000000'::UUID),
            'ai_generated',
            NEW.output_url,
            COALESCE(NEW.ai_title, 'AI Generated Video'),
            NEW.duration_seconds::INTEGER,
            NEW.resolution,
            NEW.aspect_ratio
        )
        RETURNING id INTO NEW.video_id;
    END IF;
    
    RETURN NEW;
END;
$$;


--
-- Name: retry_failed_jobs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retry_failed_jobs(p_max_retries integer DEFAULT 3) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    retried_count INTEGER;
BEGIN
    UPDATE agent_queue
    SET status = 'queued',
        claimed_by = NULL,
        claimed_at = NULL,
        started_at = NULL,
        retry_count = retry_count + 1,
        updated_at = NOW()
    WHERE status = 'failed'
    AND retry_count < p_max_retries;
    
    GET DIAGNOSTICS retried_count = ROW_COUNT;
    RETURN retried_count;
END;
$$;


--
-- Name: retry_queue_item(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retry_queue_item(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_retry_count INTEGER;
    max_retry_count INTEGER;
BEGIN
    SELECT retry_count, max_retries
    INTO current_retry_count, max_retry_count
    FROM publishing_queue
    WHERE id = p_id;
    
    IF current_retry_count < max_retry_count THEN
        UPDATE publishing_queue
        SET status = 'queued',
            retry_count = retry_count + 1,
            last_error = NULL
        WHERE id = p_id;
        RETURN TRUE;
    ELSE
        RETURN FALSE;
    END IF;
END;
$$;


--
-- Name: safe_user_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.safe_user_id() RETURNS uuid
    LANGUAGE sql STABLE
    AS $$
  SELECT NULLIF(current_setting('request.jwt.claims', true)::json->>'sub', '')::uuid;
$$;


--
-- Name: sync_social_accounts_to_legacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_social_accounts_to_legacy() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Insert or update in social_media_accounts when social_accounts changes
    INSERT INTO social_media_accounts (
        platform, username, display_name, profile_pic_url,
        external_id, is_active, last_fetched_at, last_synced_at,
        updated_at
    )
    VALUES (
        NEW.platform, NEW.handle, NEW.display_name, NEW.avatar_url,
        NEW.external_id, 
        CASE WHEN NEW.status = 'connected' THEN TRUE ELSE FALSE END,
        NEW.last_synced_at, NEW.last_synced_at, NOW()
    )
    ON CONFLICT (platform, username)
    DO UPDATE SET
        display_name = EXCLUDED.display_name,
        profile_pic_url = EXCLUDED.avatar_url,
        external_id = EXCLUDED.external_id,
        is_active = EXCLUDED.is_active,
        last_fetched_at = EXCLUDED.last_fetched_at,
        last_synced_at = EXCLUDED.last_synced_at,
        updated_at = NOW();
    
    RETURN NEW;
END;
$$;


