--
-- Name: update_queue_status(uuid, character varying, text, character varying, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_queue_status(p_id uuid, p_status character varying, p_error text DEFAULT NULL::text, p_platform_post_id character varying DEFAULT NULL::character varying, p_platform_url character varying DEFAULT NULL::character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE publishing_queue
    SET status = p_status,
        last_error = p_error,
        platform_post_id = p_platform_post_id,
        platform_url = p_platform_url,
        published_at = CASE WHEN p_status = 'published' THEN NOW() ELSE published_at END
    WHERE id = p_id;
    
    RETURN FOUND;
END;
$$;


--
-- Name: update_segment_performance_scores(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_segment_performance_scores() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.engagement_score := calculate_segment_performance_score(
        NEW.retention_rate,
        NEW.likes_during,
        NEW.comments_during,
        NEW.shares_during,
        NEW.views_at_start
    );
    
    NEW.effectiveness_score := NEW.engagement_score;  -- Can be customized later
    
    RETURN NEW;
END;
$$;


