--
-- Name: content_cross_platform_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.content_cross_platform_summary AS
 SELECT ci.id AS content_id,
    ci.title,
    ci.description,
    ci.slug,
    ci.created_at,
    ci.updated_at,
    COALESCE(cr.total_views, (0)::bigint) AS total_views,
    COALESCE(cr.total_likes, (0)::bigint) AS total_likes,
    COALESCE(cr.total_comments, (0)::bigint) AS total_comments,
    COALESCE(cr.total_shares, (0)::bigint) AS total_shares,
    COALESCE(cr.total_saves, (0)::bigint) AS total_saves,
    cr.best_platform,
    ( SELECT count(DISTINCT cv.platform) AS count
           FROM public.content_variants cv
          WHERE (cv.content_id = ci.id)) AS platform_count,
    ( SELECT array_agg(DISTINCT cv.platform) AS array_agg
           FROM public.content_variants cv
          WHERE (cv.content_id = ci.id)) AS platforms
   FROM (public.content_items ci
     LEFT JOIN public.content_rollups cr ON ((ci.id = cr.content_id)));


