--

COMMENT ON TABLE public.social_analytics_snapshots IS 'Daily snapshots of account-level metrics across all platforms';


--
-- Name: social_analytics_latest; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.social_analytics_latest AS
 SELECT sa.id,
    sa.handle AS username,
    sa.platform,
    sa.display_name,
    sa.status AS account_status,
    sas.snapshot_date AS last_snapshot_date,
    sas.followers_count,
    sas.following_count,
    sas.posts_count,
    sas.total_views,
    sas.total_likes,
    sas.total_comments,
    sas.engagement_rate,
    sas.follower_growth,
    sac.monitoring_enabled,
    sac.last_fetched_at
   FROM ((public.social_accounts sa
     LEFT JOIN public.social_analytics_config sac ON ((sa.id = sac.social_account_id)))
     LEFT JOIN LATERAL ( SELECT social_analytics_snapshots.id,
            social_analytics_snapshots.social_account_id,
            social_analytics_snapshots.snapshot_date,
            social_analytics_snapshots.followers_count,
            social_analytics_snapshots.following_count,
            social_analytics_snapshots.posts_count,
            social_analytics_snapshots.total_likes,
            social_analytics_snapshots.total_comments,
            social_analytics_snapshots.total_views,
            social_analytics_snapshots.total_shares,
            social_analytics_snapshots.total_saves,
            social_analytics_snapshots.total_impressions,
            social_analytics_snapshots.subscribers_count,
            social_analytics_snapshots.pins_count,
            social_analytics_snapshots.boards_count,
            social_analytics_snapshots.retweets_count,
            social_analytics_snapshots.reactions_count,
            social_analytics_snapshots.watch_time_minutes,
            social_analytics_snapshots.engagement_rate,
            social_analytics_snapshots.avg_likes_per_post,
            social_analytics_snapshots.avg_comments_per_post,
            social_analytics_snapshots.avg_views_per_post,
            social_analytics_snapshots.follower_growth,
            social_analytics_snapshots.engagement_growth,
            social_analytics_snapshots.reach,
            social_analytics_snapshots.profile_visits,
            social_analytics_snapshots.data_source,
            social_analytics_snapshots.raw_response,
            social_analytics_snapshots.created_at
           FROM public.social_analytics_snapshots
          WHERE (social_analytics_snapshots.social_account_id = sa.id)
          ORDER BY social_analytics_snapshots.snapshot_date DESC
         LIMIT 1) sas ON (true));


