--
-- Name: social_post_performance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.social_post_performance AS
 SELECT p.id,
    p.platform,
    p.post_url,
    p.caption,
    p.media_type,
    p.posted_at,
    m.views_count AS current_views,
    m.likes_count AS current_likes,
    m.comments_count AS current_comments,
    m.engagement_rate,
    m.snapshot_date AS last_updated,
    sa.handle AS account_username
   FROM ((public.social_posts_analytics p
     JOIN public.social_accounts sa ON ((p.social_account_id = sa.id)))
     LEFT JOIN LATERAL ( SELECT social_post_metrics.id,
            social_post_metrics.post_id,
            social_post_metrics.snapshot_date,
            social_post_metrics.snapshot_hour,
            social_post_metrics.likes_count,
            social_post_metrics.comments_count,
            social_post_metrics.views_count,
            social_post_metrics.shares_count,
            social_post_metrics.saves_count,
            social_post_metrics.retweets_count,
            social_post_metrics.quote_tweets_count,
            social_post_metrics.reactions_count,
            social_post_metrics.repins_count,
            social_post_metrics.impressions,
            social_post_metrics.reach,
            social_post_metrics.unique_viewers,
            social_post_metrics.watch_time_seconds,
            social_post_metrics.avg_watch_percentage,
            social_post_metrics.completion_rate,
            social_post_metrics.profile_visits,
            social_post_metrics.follows_from_post,
            social_post_metrics.link_clicks,
            social_post_metrics.engagement_rate,
            social_post_metrics.viral_score,
            social_post_metrics.created_at
           FROM public.social_post_metrics
          WHERE (social_post_metrics.post_id = p.id)
          ORDER BY social_post_metrics.snapshot_date DESC, social_post_metrics.snapshot_hour DESC NULLS LAST
         LIMIT 1) m ON (true))
  WHERE (p.deleted_at IS NULL);


