--
-- Name: unified_media_library; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.unified_media_library AS
 SELECT v.id,
    v.file_name AS title,
    v.source_type,
    v.source_uri AS url,
    v.duration_sec,
    v.resolution,
    v.aspect_ratio,
    v.created_at,
    'ugc'::text AS origin,
    NULL::text AS ai_provider,
    NULL::text AS ai_prompt,
    NULL::text AS style_preset,
    va.pre_social_score AS score,
    va.topics,
    va.tone
   FROM (public.videos v
     LEFT JOIN public.video_analysis va ON ((v.id = va.video_id)))
  WHERE (v.source_type <> 'ai_generated'::text)
UNION ALL
 SELECT COALESCE(aig.video_id, aig.id) AS id,
    COALESCE(aig.ai_title, 'AI Video'::text) AS title,
    'ai_generated'::text AS source_type,
    aig.output_url AS url,
    (aig.duration_seconds)::integer AS duration_sec,
    aig.resolution,
    aig.aspect_ratio,
    aig.created_at,
    'ai'::text AS origin,
    aig.provider AS ai_provider,
    aig.prompt AS ai_prompt,
    aig.style_preset,
    NULL::numeric AS score,
    NULL::text[] AS topics,
    NULL::text AS tone
   FROM public.ai_video_generations aig
  WHERE (aig.status = 'completed'::text);


--
-- Name: v_event_statistics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_event_statistics AS
 SELECT date_trunc('hour'::text, "timestamp") AS hour,
    topic,
    count(*) AS event_count,
    count(DISTINCT correlation_id) AS unique_workflows,
    count(DISTINCT source) AS unique_sources
   FROM public.event_history
  WHERE ("timestamp" >= (now() - '7 days'::interval))
  GROUP BY (date_trunc('hour'::text, "timestamp")), topic
  ORDER BY (date_trunc('hour'::text, "timestamp")) DESC, (count(*)) DESC;


--
-- Name: v_recent_events_by_topic; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_recent_events_by_topic AS
 SELECT topic,
    count(*) AS event_count,
    max("timestamp") AS last_event_at,
    min("timestamp") AS first_event_at
   FROM public.event_history
  WHERE ("timestamp" >= (now() - '24:00:00'::interval))
  GROUP BY topic
  ORDER BY (count(*)) DESC;


--
-- Name: v_recent_runs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_recent_runs AS
SELECT
    NULL::uuid AS id,
    NULL::character varying(50) AS agent_type,
    NULL::character varying(20) AS status,
    NULL::integer AS progress_current,
    NULL::integer AS progress_total,
    NULL::timestamp with time zone AS started_at,
    NULL::timestamp with time zone AS finished_at,
    NULL::character varying(100) AS schedule_name,
    NULL::bigint AS step_count,
    NULL::bigint AS completed_steps;


--
-- Name: v_run_timeline; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_run_timeline AS
 SELECT e.run_id,
    e.ts,
    e.agent_type,
    e.event_type,
    e.title,
    e.message,
    e.severity,
    e.topic,
    e.step_id,
    st.step_name,
    st.step_key
   FROM (public.agent_events e
     LEFT JOIN public.agent_steps st ON ((e.step_id = st.id)))
  WHERE (e.run_id IS NOT NULL)
  ORDER BY e.ts;


--
-- Name: video_assessments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.video_assessments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    clip_run_id uuid NOT NULL,
