--

CREATE TABLE public.video_clips (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL,
    video_id uuid NOT NULL,
    user_id uuid NOT NULL,
    start_time double precision NOT NULL,
    end_time double precision NOT NULL,
    duration double precision GENERATED ALWAYS AS ((end_time - start_time)) STORED,
    title character varying(500),
    description text,
    clip_type character varying(50) DEFAULT 'custom'::character varying,
    overlay_config jsonb DEFAULT '{}'::jsonb,
    caption_config jsonb DEFAULT '{}'::jsonb,
    thumbnail_config jsonb DEFAULT '{}'::jsonb,
    ai_suggested boolean DEFAULT false,
    ai_score double precision,
    ai_reasoning text,
    segment_ids uuid[],
    hook_segment_id uuid,
    platform_variants jsonb DEFAULT '{}'::jsonb,
    target_platforms character varying(50)[],
    status character varying(50) DEFAULT 'draft'::character varying,
    render_status character varying(50),
    rendered_url character varying(500),
    render_error text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT valid_clip_type CHECK (((clip_type)::text = ANY ((ARRAY['highlight'::character varying, 'full'::character varying, 'custom'::character varying, 'ai_generated'::character varying])::text[]))),
    CONSTRAINT valid_render_status CHECK (((render_status IS NULL) OR ((render_status)::text = ANY ((ARRAY['pending'::character varying, 'processing'::character varying, 'completed'::character varying, 'failed'::character varying])::text[])))),
    CONSTRAINT valid_status CHECK (((status)::text = ANY ((ARRAY['draft'::character varying, 'ready'::character varying, 'published'::character varying, 'archived'::character varying])::text[]))),
    CONSTRAINT video_clips_ai_score_check CHECK (((ai_score >= (0)::double precision) AND (ai_score <= (1)::double precision))),
    CONSTRAINT video_clips_check CHECK ((end_time > start_time)),
    CONSTRAINT video_clips_start_time_check CHECK ((start_time >= (0)::double precision))
);


