20241121000000	{"-- EverReach/Blend: Comprehensive Database Schema\n\n-- Enable UUID extension if not already enabled\nCREATE EXTENSION IF NOT EXISTS \\"uuid-ossp\\"","-- ============================================================================\n-- People Graph (EverReach Core)\n-- ============================================================================\n\n-- 1. people\nCREATE TABLE IF NOT EXISTS people (\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  full_name TEXT,\n  primary_email TEXT,\n  company TEXT,\n  role TEXT,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  updated_at TIMESTAMPTZ DEFAULT NOW()\n)","-- 2. identities\nCREATE TABLE IF NOT EXISTS identities (\n  id BIGSERIAL PRIMARY KEY,\n  person_id UUID REFERENCES people(id) ON DELETE CASCADE,\n  channel TEXT CHECK (channel IN ('email','instagram','linkedin','twitter','facebook','tiktok','youtube','threads','bluesky','pinterest')),\n  handle TEXT NOT NULL,\n  extra JSONB,\n  is_verified BOOLEAN DEFAULT FALSE,\n  first_seen_at TIMESTAMPTZ DEFAULT NOW(),\n  last_seen_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  UNIQUE(channel, handle)\n)","CREATE INDEX IF NOT EXISTS idx_identities_person ON identities(person_id)","CREATE INDEX IF NOT EXISTS idx_identities_channel ON identities(channel)","-- 3. person_events\nCREATE TABLE IF NOT EXISTS person_events (\n  id BIGSERIAL PRIMARY KEY,\n  person_id UUID REFERENCES people(id) ON DELETE CASCADE,\n  channel TEXT NOT NULL,\n  event_type TEXT NOT NULL,\n  platform_id TEXT,\n  content_excerpt TEXT,\n  sentiment NUMERIC CHECK (sentiment >= -1 AND sentiment <= 1),\n  traffic_type TEXT CHECK (traffic_type IN ('organic','paid')) DEFAULT 'organic',\n  metadata JSONB,\n  occurred_at TIMESTAMPTZ DEFAULT NOW()\n)","CREATE INDEX IF NOT EXISTS idx_person_events_person ON person_events(person_id, occurred_at DESC)","CREATE INDEX IF NOT EXISTS idx_person_events_type ON person_events(event_type, occurred_at DESC)","CREATE INDEX IF NOT EXISTS idx_person_events_traffic ON person_events(traffic_type)","-- 4. person_insights\nCREATE TABLE IF NOT EXISTS person_insights (\n  person_id UUID PRIMARY KEY REFERENCES people(id) ON DELETE CASCADE,\n  interests JSONB,\n  tone_preferences JSONB,\n  channel_preferences JSONB,\n  avg_reply_time INTERVAL,\n  activity_state TEXT CHECK (activity_state IN ('active','warming','cool','dormant')),\n  last_active_at TIMESTAMPTZ,\n  seasonality JSONB,\n  warmth_score NUMERIC,\n  updated_at TIMESTAMPTZ DEFAULT NOW()\n)","-- 5. segments\nCREATE TABLE IF NOT EXISTS segments (\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  name TEXT NOT NULL,\n  description TEXT,\n  definition JSONB,\n  created_by UUID,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  updated_at TIMESTAMPTZ DEFAULT NOW()\n)","-- 6. segment_members\nCREATE TABLE IF NOT EXISTS segment_members (\n  segment_id UUID REFERENCES segments(id) ON DELETE CASCADE,\n  person_id UUID REFERENCES people(id) ON DELETE CASCADE,\n  added_at TIMESTAMPTZ DEFAULT NOW(),\n  PRIMARY KEY (segment_id, person_id)\n)","CREATE INDEX IF NOT EXISTS idx_segment_members_person ON segment_members(person_id)","-- 7. segment_insights\nCREATE TABLE IF NOT EXISTS segment_insights (\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  segment_id UUID REFERENCES segments(id) ON DELETE CASCADE,\n  traffic_type TEXT CHECK (traffic_type IN ('organic','paid')),\n  top_topics JSONB,\n  top_platforms JSONB,\n  top_formats JSONB,\n  engagement_style JSONB,\n  best_times JSONB,\n  expected_reach_range INT4RANGE,\n  expected_engagement_rate_range NUMRANGE,\n  updated_at TIMESTAMPTZ DEFAULT NOW(),\n  UNIQUE(segment_id, traffic_type)\n)","-- 8. outbound_messages\nCREATE TABLE IF NOT EXISTS outbound_messages (\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  person_id UUID REFERENCES people(id) ON DELETE CASCADE,\n  segment_id UUID REFERENCES segments(id) ON DELETE SET NULL,\n  channel TEXT NOT NULL,\n  goal_type TEXT,\n  variant TEXT,\n  subject TEXT,\n  body TEXT,\n  sent_at TIMESTAMPTZ DEFAULT NOW(),\n  opened_at TIMESTAMPTZ,\n  clicked_at TIMESTAMPTZ,\n  replied_at TIMESTAMPTZ,\n  metadata JSONB\n)","CREATE INDEX IF NOT EXISTS idx_outbound_person ON outbound_messages(person_id, sent_at DESC)","CREATE INDEX IF NOT EXISTS idx_outbound_segment ON outbound_messages(segment_id, sent_at DESC)","-- ============================================================================\n-- Content Graph (Blend Cross-Platform)\n-- ============================================================================\n\n-- 9. content_items\nCREATE TABLE IF NOT EXISTS content_items (\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  slug TEXT UNIQUE,\n  type TEXT CHECK (type IN ('video','article','audio','image','carousel')),\n  source_url TEXT,\n  title TEXT,\n  description TEXT,\n  created_by UUID,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  updated_at TIMESTAMPTZ DEFAULT NOW()\n)","CREATE INDEX IF NOT EXISTS idx_content_items_created ON content_items(created_at DESC)","CREATE INDEX IF NOT EXISTS idx_content_items_creator ON content_items(created_by)","-- 10. content_variants\nCREATE TABLE IF NOT EXISTS content_variants (\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  content_id UUID REFERENCES content_items(id) ON DELETE CASCADE,\n  platform TEXT CHECK (platform IN (\n    'instagram','tiktok','youtube','linkedin','twitter','facebook',\n    'pinterest','threads','bluesky','other'\n  )),\n  platform_post_id TEXT,\n  platform_post_url TEXT,\n  title TEXT,\n  description TEXT,\n  thumbnail_url TEXT,\n  scheduled_at TIMESTAMPTZ,\n  published_at TIMESTAMPTZ,\n  is_paid BOOLEAN DEFAULT FALSE,\n  experiment_id UUID,\n  variant_label TEXT,\n  created_at TIMESTAMPTZ DEFAULT NOW()\n)","CREATE INDEX IF NOT EXISTS idx_variants_content ON content_variants(content_id)","CREATE INDEX IF NOT EXISTS idx_variants_platform ON content_variants(platform, published_at DESC)","CREATE INDEX IF NOT EXISTS idx_variants_experiment ON content_variants(experiment_id)","-- 11. content_metrics\nCREATE TABLE IF NOT EXISTS content_metrics (\n  id BIGSERIAL PRIMARY KEY,\n  variant_id UUID REFERENCES content_variants(id) ON DELETE CASCADE,\n  snapshot_at TIMESTAMPTZ DEFAULT NOW(),\n  views BIGINT,\n  impressions BIGINT,\n  reach BIGINT,\n  likes BIGINT,\n  comments BIGINT,\n  shares BIGINT,\n  saves BIGINT,\n  clicks BIGINT,\n  watch_time_seconds BIGINT,\n  sentiment_score NUMERIC CHECK (sentiment_score >= -1 AND sentiment_score <= 1),\n  traffic_type TEXT CHECK (traffic_type IN ('organic','paid')) DEFAULT 'organic',\n  metadata JSONB\n)","CREATE INDEX IF NOT EXISTS idx_metrics_variant ON content_metrics(variant_id, snapshot_at DESC)","CREATE INDEX IF NOT EXISTS idx_metrics_traffic ON content_metrics(traffic_type)","-- 12. content_rollups\nCREATE TABLE IF NOT EXISTS content_rollups (\n  content_id UUID PRIMARY KEY REFERENCES content_items(id) ON DELETE CASCADE,\n  total_views BIGINT,\n  total_impressions BIGINT,\n  total_likes BIGINT,\n  total_comments BIGINT,\n  total_shares BIGINT,\n  total_saves BIGINT,\n  total_clicks BIGINT,\n  avg_watch_time_seconds NUMERIC,\n  global_sentiment NUMERIC,\n  best_platform TEXT,\n  last_updated_at TIMESTAMPTZ DEFAULT NOW()\n)","-- 13. content_experiments\nCREATE TABLE IF NOT EXISTS content_experiments (\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  content_id UUID REFERENCES content_items(id) ON DELETE CASCADE,\n  name TEXT NOT NULL,\n  hypothesis TEXT,\n  primary_metric TEXT,\n  status TEXT CHECK (status IN ('draft','running','completed','cancelled')) DEFAULT 'draft',\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  started_at TIMESTAMPTZ,\n  completed_at TIMESTAMPTZ\n)","-- ============================================================================\n-- Platform Connectors\n-- ============================================================================\n\n-- 14. ig_connections\nCREATE TABLE IF NOT EXISTS ig_connections (\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  everreach_user_id UUID NOT NULL,\n  fb_page_id TEXT NOT NULL,\n  ig_business_id TEXT NOT NULL,\n  access_token TEXT NOT NULL,\n  token_expires_at TIMESTAMPTZ NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  last_synced_at TIMESTAMPTZ\n)","CREATE INDEX IF NOT EXISTS idx_ig_conn_user ON ig_connections(everreach_user_id)","-- 15. connector_configs\nCREATE TABLE IF NOT EXISTS connector_configs (\n  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n  user_id UUID NOT NULL,\n  connector_type TEXT NOT NULL,\n  config JSONB NOT NULL,\n  is_enabled BOOLEAN DEFAULT TRUE,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  updated_at TIMESTAMPTZ DEFAULT NOW(),\n  UNIQUE(user_id, connector_type)\n)","-- ============================================================================\n-- Indexes for Search & Performance\n-- ============================================================================\n\n-- Full-text search on content\nCREATE INDEX IF NOT EXISTS idx_content_title_search ON content_items USING GIN (to_tsvector('english', title))","CREATE INDEX IF NOT EXISTS idx_content_desc_search ON content_items USING GIN (to_tsvector('english', description))","-- Partial indexes for active data\nCREATE INDEX IF NOT EXISTS idx_active_people ON person_insights(person_id) WHERE activity_state IN ('active','warming')","CREATE INDEX IF NOT EXISTS idx_scheduled_variants ON content_variants(scheduled_at) WHERE published_at IS NULL","-- ============================================================================\n-- Row Level Security (RLS) - Basic Setup\n-- ============================================================================\n\n-- Enable RLS on all tables\nALTER TABLE people ENABLE ROW LEVEL SECURITY","ALTER TABLE identities ENABLE ROW LEVEL SECURITY","ALTER TABLE person_events ENABLE ROW LEVEL SECURITY","ALTER TABLE person_insights ENABLE ROW LEVEL SECURITY","ALTER TABLE segments ENABLE ROW LEVEL SECURITY","ALTER TABLE segment_members ENABLE ROW LEVEL SECURITY","ALTER TABLE segment_insights ENABLE ROW LEVEL SECURITY","ALTER TABLE outbound_messages ENABLE ROW LEVEL SECURITY","ALTER TABLE content_items ENABLE ROW LEVEL SECURITY","ALTER TABLE content_variants ENABLE ROW LEVEL SECURITY","ALTER TABLE content_metrics ENABLE ROW LEVEL SECURITY","ALTER TABLE content_rollups ENABLE ROW LEVEL SECURITY","ALTER TABLE content_experiments ENABLE ROW LEVEL SECURITY","ALTER TABLE ig_connections ENABLE ROW LEVEL SECURITY","ALTER TABLE connector_configs ENABLE ROW LEVEL SECURITY","-- Create policies (Placeholder: allow all for authenticated users for now, refine later)\n-- Note: In a real production app, you'd want stricter policies based on user ownership.\n\nCREATE POLICY \\"Allow all access for authenticated users\\" ON people FOR ALL TO authenticated USING (true)","CREATE POLICY \\"Allow all access for authenticated users\\" ON identities FOR ALL TO authenticated USING (true)","CREATE POLICY \\"Allow all access for authenticated users\\" ON person_events FOR ALL TO authenticated USING (true)","CREATE POLICY \\"Allow all access for authenticated users\\" ON person_insights FOR ALL TO authenticated USING (true)","CREATE POLICY \\"Allow all access for authenticated users\\" ON segments FOR ALL TO authenticated USING (true)","CREATE POLICY \\"Allow all access for authenticated users\\" ON segment_members FOR ALL TO authenticated USING (true)","CREATE POLICY \\"Allow all access for authenticated users\\" ON segment_insights FOR ALL TO authenticated USING (true)","CREATE POLICY \\"Allow all access for authenticated users\\" ON outbound_messages FOR ALL TO authenticated USING (true)","CREATE POLICY \\"Allow all access for authenticated users\\" ON content_items FOR ALL TO authenticated USING (true)","CREATE POLICY \\"Allow all access for authenticated users\\" ON content_variants FOR ALL TO authenticated USING (true)","CREATE POLICY \\"Allow all access for authenticated users\\" ON content_metrics FOR ALL TO authenticated USING (true)","CREATE POLICY \\"Allow all access for authenticated users\\" ON content_rollups FOR ALL TO authenticated USING (true)","CREATE POLICY \\"Allow all access for authenticated users\\" ON content_experiments FOR ALL TO authenticated USING (true)","CREATE POLICY \\"Allow all access for authenticated users\\" ON ig_connections FOR ALL TO authenticated USING (true)","CREATE POLICY \\"Allow all access for authenticated users\\" ON connector_configs FOR ALL TO authenticated USING (true)"}	everreach_blend_schema
20241222	{"-- Video Orchestrator Schema\n-- Supports Sora-first video generation with Director/SceneCrafter/Assessor workflow\n\n-- 0) Extensions\nCREATE EXTENSION IF NOT EXISTS pgcrypto","-- 1) Enums\nDO $$ BEGIN\n  CREATE TYPE video_provider_name AS ENUM ('sora', 'runway', 'kling', 'pika', 'luma', 'mock');\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","DO $$ BEGIN\n  CREATE TYPE clip_run_status AS ENUM ('queued', 'running', 'succeeded', 'failed', 'canceled');\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","DO $$ BEGIN\n  CREATE TYPE assessment_verdict AS ENUM ('pass', 'fail', 'needs_review');\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","DO $$ BEGIN\n  CREATE TYPE orchestrator_role AS ENUM ('content_brief', 'director', 'scene_crafter', 'assessor');\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","DO $$ BEGIN\n  CREATE TYPE clip_state AS ENUM ('pending', 'generating', 'passed', 'failed', 'skipped');\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","DO $$ BEGIN\n  CREATE TYPE plan_status AS ENUM ('draft', 'ready', 'running', 'completed', 'failed', 'archived');\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","DO $$ BEGIN\n  CREATE TYPE render_status AS ENUM ('queued', 'running', 'succeeded', 'failed');\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","DO $$ BEGIN\n  CREATE TYPE bible_kind AS ENUM ('style', 'character', 'continuity');\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","-- 2) Video Projects (top-level container)\nCREATE TABLE IF NOT EXISTS video_projects (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  owner_id UUID, -- references auth.users if using Supabase auth\n  title TEXT NOT NULL,\n  description TEXT,\n  tags TEXT[] NOT NULL DEFAULT '{}',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n)","-- 3) Bibles (style, character, continuity rules)\nCREATE TABLE IF NOT EXISTS video_bibles (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  project_id UUID NOT NULL REFERENCES video_projects(id) ON DELETE CASCADE,\n  kind bible_kind NOT NULL,\n  name TEXT NOT NULL,\n  body JSONB NOT NULL DEFAULT '{}'::jsonb,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n)","-- 4) Content Briefs\nCREATE TABLE IF NOT EXISTS video_content_briefs (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  project_id UUID NOT NULL REFERENCES video_projects(id) ON DELETE CASCADE,\n  objective TEXT NOT NULL,\n  audience TEXT NOT NULL,\n  tone TEXT,\n  cta TEXT,\n  key_points TEXT[] NOT NULL DEFAULT '{}',\n  safety JSONB NOT NULL DEFAULT '{}'::jsonb,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n)","-- 5) Scripts\nCREATE TABLE IF NOT EXISTS video_scripts (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  project_id UUID NOT NULL REFERENCES video_projects(id) ON DELETE CASCADE,\n  brief_id UUID REFERENCES video_content_briefs(id) ON DELETE SET NULL,\n  title TEXT NOT NULL,\n  body TEXT NOT NULL,\n  language TEXT NOT NULL DEFAULT 'en',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n)","-- 6) Clip Plans (orchestration plan)\nCREATE TABLE IF NOT EXISTS video_clip_plans (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  project_id UUID NOT NULL REFERENCES video_projects(id) ON DELETE CASCADE,\n  brief_id UUID REFERENCES video_content_briefs(id) ON DELETE SET NULL,\n  script_id UUID REFERENCES video_scripts(id) ON DELETE SET NULL,\n  \n  style_bible_id UUID REFERENCES video_bibles(id) ON DELETE SET NULL,\n  character_bible_id UUID REFERENCES video_bibles(id) ON DELETE SET NULL,\n  continuity_bible_id UUID REFERENCES video_bibles(id) ON DELETE SET NULL,\n  \n  version TEXT NOT NULL DEFAULT '1.0.0',\n  constraints JSONB NOT NULL DEFAULT '{}'::jsonb,\n  plan_json JSONB NOT NULL DEFAULT '{}'::jsonb,\n  status plan_status NOT NULL DEFAULT 'draft',\n  \n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n)","-- 7) Scenes (containers within clip plans)\nCREATE TABLE IF NOT EXISTS video_scenes (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  clip_plan_id UUID NOT NULL REFERENCES video_clip_plans(id) ON DELETE CASCADE,\n  name TEXT NOT NULL,\n  goal TEXT,\n  beats TEXT[] NOT NULL DEFAULT '{}',\n  scene_order INT NOT NULL DEFAULT 0,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n)","-- 8) Clip Plan Clips (individual clip definitions)\nCREATE TABLE IF NOT EXISTS video_clip_plan_clips (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  scene_id UUID NOT NULL REFERENCES video_scenes(id) ON DELETE CASCADE,\n  clip_order INT NOT NULL,\n  \n  target_seconds INT NOT NULL CHECK (target_seconds > 0 AND target_seconds <= 60),\n  \n  narration JSONB NOT NULL DEFAULT '{}'::jsonb,\n  visual_intent JSONB NOT NULL DEFAULT '{}'::jsonb,\n  provider_hints JSONB NOT NULL DEFAULT '{}'::jsonb,\n  acceptance JSONB NOT NULL DEFAULT '{}'::jsonb,\n  \n  state clip_state NOT NULL DEFAULT 'pending',\n  provider_override video_provider_name,\n  \n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n)","-- 9) Clip Runs (provider generation attempts)\nCREATE TABLE IF NOT EXISTS video_clip_runs (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  clip_plan_clip_id UUID NOT NULL REFERENCES video_clip_plan_clips(id) ON DELETE CASCADE,\n  \n  provider video_provider_name NOT NULL,\n  provider_generation_id TEXT NOT NULL,\n  \n  attempt INT NOT NULL DEFAULT 1,\n  status clip_run_status NOT NULL DEFAULT 'queued',\n  \n  request_payload JSONB NOT NULL DEFAULT '{}'::jsonb,\n  response_payload JSONB NOT NULL DEFAULT '{}'::jsonb,\n  \n  error TEXT,\n  duration_actual FLOAT,\n  \n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  \n  UNIQUE (clip_plan_clip_id, attempt)\n)","-- 10) Video Assets (stored files)\nCREATE TABLE IF NOT EXISTS video_assets (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  project_id UUID NOT NULL REFERENCES video_projects(id) ON DELETE CASCADE,\n  kind TEXT NOT NULL CHECK (kind IN ('video_mp4', 'image_png', 'image_jpg', 'json', 'text', 'audio_wav', 'audio_mp3')),\n  url TEXT NOT NULL,\n  content_type TEXT,\n  bytes BIGINT,\n  sha256 TEXT,\n  meta JSONB NOT NULL DEFAULT '{}'::jsonb,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n)","-- 11) Clip Run Assets (link runs to assets)\nCREATE TABLE IF NOT EXISTS video_clip_run_assets (\n  clip_run_id UUID NOT NULL REFERENCES video_clip_runs(id) ON DELETE CASCADE,\n  asset_id UUID NOT NULL REFERENCES video_assets(id) ON DELETE CASCADE,\n  PRIMARY KEY (clip_run_id, asset_id)\n)","-- 12) Assessments\nCREATE TABLE IF NOT EXISTS video_assessments (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  clip_run_id UUID NOT NULL REFERENCES video_clip_runs(id) ON DELETE CASCADE,\n  assessor_role orchestrator_role NOT NULL DEFAULT 'assessor',\n  \n  verdict assessment_verdict NOT NULL,\n  score NUMERIC NOT NULL CHECK (score >= 0 AND score <= 1),\n  reasons TEXT[] NOT NULL DEFAULT '{}',\n  breakdown JSONB NOT NULL DEFAULT '[]'::jsonb,\n  repair_instruction JSONB NOT NULL DEFAULT '{}'::jsonb,\n  \n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n)","-- 13) Repair Attempts\nCREATE TABLE IF NOT EXISTS video_repair_attempts (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  clip_plan_clip_id UUID NOT NULL REFERENCES video_clip_plan_clips(id) ON DELETE CASCADE,\n  from_clip_run_id UUID REFERENCES video_clip_runs(id) ON DELETE SET NULL,\n  strategy TEXT NOT NULL CHECK (strategy IN ('prompt_patch', 'remix', 'fallback_provider')),\n  prompt_delta TEXT,\n  fallback_provider video_provider_name,\n  notes TEXT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n)","-- 14) Final Renders (assembled timeline outputs)\nCREATE TABLE IF NOT EXISTS video_renders (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  clip_plan_id UUID NOT NULL REFERENCES video_clip_plans(id) ON DELETE CASCADE,\n  status render_status NOT NULL DEFAULT 'queued',\n  output_asset_id UUID REFERENCES video_assets(id) ON DELETE SET NULL,\n  timeline_json JSONB NOT NULL DEFAULT '{}'::jsonb,\n  error TEXT,\n  duration_seconds FLOAT,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n)","-- 15) Indexes for performance\nCREATE INDEX IF NOT EXISTS idx_video_clip_plan_clips_scene_order ON video_clip_plan_clips(scene_id, clip_order)","CREATE INDEX IF NOT EXISTS idx_video_clip_runs_clip_attempt ON video_clip_runs(clip_plan_clip_id, attempt)","CREATE INDEX IF NOT EXISTS idx_video_assessments_clip_run ON video_assessments(clip_run_id)","CREATE INDEX IF NOT EXISTS idx_video_assets_project_kind ON video_assets(project_id, kind)","CREATE INDEX IF NOT EXISTS idx_video_scenes_plan_order ON video_scenes(clip_plan_id, scene_order)","CREATE INDEX IF NOT EXISTS idx_video_clip_plans_project ON video_clip_plans(project_id)","CREATE INDEX IF NOT EXISTS idx_video_bibles_project_kind ON video_bibles(project_id, kind)","-- 16) Updated_at triggers\nCREATE OR REPLACE FUNCTION update_updated_at_column()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.updated_at = NOW();\n  RETURN NEW;\nEND;\n$$ language 'plpgsql'","DO $$ BEGIN\n  CREATE TRIGGER update_video_projects_updated_at BEFORE UPDATE ON video_projects\n    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","DO $$ BEGIN\n  CREATE TRIGGER update_video_bibles_updated_at BEFORE UPDATE ON video_bibles\n    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","DO $$ BEGIN\n  CREATE TRIGGER update_video_content_briefs_updated_at BEFORE UPDATE ON video_content_briefs\n    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","DO $$ BEGIN\n  CREATE TRIGGER update_video_scripts_updated_at BEFORE UPDATE ON video_scripts\n    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","DO $$ BEGIN\n  CREATE TRIGGER update_video_clip_plans_updated_at BEFORE UPDATE ON video_clip_plans\n    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","DO $$ BEGIN\n  CREATE TRIGGER update_video_clip_plan_clips_updated_at BEFORE UPDATE ON video_clip_plan_clips\n    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","DO $$ BEGIN\n  CREATE TRIGGER update_video_clip_runs_updated_at BEFORE UPDATE ON video_clip_runs\n    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nEXCEPTION WHEN duplicate_object THEN NULL; END $$","DO $$ BEGIN\n  CREATE TRIGGER update_video_renders_updated_at BEFORE UPDATE ON video_renders\n    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nEXCEPTION WHEN duplicate_object THEN NULL; END $$"}	video_orchestrator
20250121000000	{"-- Content Base Tables\n-- Migration: 000_content_base_tables\n-- Created: 2025-01-21\n-- Creates the base content tables that other migrations depend on\n\n-- Enable UUID extension if not exists\nCREATE EXTENSION IF NOT EXISTS \\"uuid-ossp\\"","-- content_items\nCREATE TABLE IF NOT EXISTS content_items (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  slug TEXT UNIQUE,\n  type TEXT CHECK (type IN ('video','article','audio','image','carousel')),\n  source_url TEXT,\n  title TEXT,\n  description TEXT,\n  created_by UUID,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  updated_at TIMESTAMPTZ DEFAULT NOW()\n)","CREATE INDEX IF NOT EXISTS idx_content_items_created ON content_items(created_at DESC)","CREATE INDEX IF NOT EXISTS idx_content_items_creator ON content_items(created_by)","-- content_variants\nCREATE TABLE IF NOT EXISTS content_variants (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  content_id UUID REFERENCES content_items(id) ON DELETE CASCADE,\n  platform TEXT CHECK (platform IN (\n    'instagram','tiktok','youtube','linkedin','twitter','facebook',\n    'pinterest','threads','bluesky','other'\n  )),\n  platform_post_id TEXT,\n  platform_post_url TEXT,\n  title TEXT,\n  description TEXT,\n  thumbnail_url TEXT,\n  scheduled_at TIMESTAMPTZ,\n  published_at TIMESTAMPTZ,\n  is_paid BOOLEAN DEFAULT FALSE,\n  experiment_id UUID,\n  variant_label TEXT,\n  created_at TIMESTAMPTZ DEFAULT NOW()\n)","CREATE INDEX IF NOT EXISTS idx_variants_content ON content_variants(content_id)","CREATE INDEX IF NOT EXISTS idx_variants_platform ON content_variants(platform, published_at DESC)","CREATE INDEX IF NOT EXISTS idx_variants_experiment ON content_variants(experiment_id)","-- content_metrics\nCREATE TABLE IF NOT EXISTS content_metrics (\n  id BIGSERIAL PRIMARY KEY,\n  variant_id UUID REFERENCES content_variants(id) ON DELETE CASCADE,\n  snapshot_at TIMESTAMPTZ DEFAULT NOW(),\n  views BIGINT,\n  impressions BIGINT,\n  reach BIGINT,\n  likes BIGINT,\n  comments BIGINT,\n  shares BIGINT,\n  saves BIGINT,\n  clicks BIGINT,\n  watch_time_seconds BIGINT,\n  sentiment_score NUMERIC CHECK (sentiment_score >= -1 AND sentiment_score <= 1),\n  traffic_type TEXT CHECK (traffic_type IN ('organic','paid')) DEFAULT 'organic',\n  metadata JSONB\n)","CREATE INDEX IF NOT EXISTS idx_metrics_variant ON content_metrics(variant_id, snapshot_at DESC)","CREATE INDEX IF NOT EXISTS idx_metrics_traffic ON content_metrics(traffic_type)","-- Enable RLS\nALTER TABLE content_items ENABLE ROW LEVEL SECURITY","ALTER TABLE content_variants ENABLE ROW LEVEL SECURITY","ALTER TABLE content_metrics ENABLE ROW LEVEL SECURITY","-- Comments\nCOMMENT ON TABLE content_items IS 'Canonical content assets (Video, Article) with a global ID'","COMMENT ON TABLE content_variants IS 'Platform-specific executions of a content item'","COMMENT ON TABLE content_metrics IS 'Time-series snapshots of performance'"}	content_base_tables
20250121000001	{"-- EverReach People Graph Tables\n-- Migration: 001_people_graph\n-- Created: 2025-01-21\n\n-- Enable UUID extension if not exists\nCREATE EXTENSION IF NOT EXISTS \\"uuid-ossp\\"","-- =====================================================\n-- PEOPLE GRAPH: Core person entities\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS people (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  full_name TEXT,\n  primary_email TEXT,\n  company TEXT,\n  role TEXT,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  updated_at TIMESTAMPTZ DEFAULT NOW()\n)","CREATE INDEX IF NOT EXISTS idx_people_email ON people(primary_email)","CREATE INDEX IF NOT EXISTS idx_people_created ON people(created_at DESC)","-- =====================================================\n-- IDENTITIES: Cross-platform identity mapping\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS identities (\n  id BIGSERIAL PRIMARY KEY,\n  person_id UUID REFERENCES people(id) ON DELETE CASCADE,\n  channel TEXT CHECK (channel IN (\n    'email','instagram','linkedin','twitter','facebook',\n    'tiktok','youtube','threads','bluesky','pinterest'\n  )),\n  handle TEXT NOT NULL,\n  extra JSONB,\n  is_verified BOOLEAN DEFAULT FALSE,\n  first_seen_at TIMESTAMPTZ DEFAULT NOW(),\n  last_seen_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  UNIQUE(channel, handle)\n)","CREATE INDEX IF NOT EXISTS idx_identities_person ON identities(person_id)","CREATE INDEX IF NOT EXISTS idx_identities_channel ON identities(channel)","CREATE INDEX IF NOT EXISTS idx_identities_handle ON identities(handle)","-- =====================================================\n-- PERSON EVENTS: Unified interaction stream\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS person_events (\n  id BIGSERIAL PRIMARY KEY,\n  person_id UUID REFERENCES people(id) ON DELETE CASCADE,\n  channel TEXT NOT NULL,\n  event_type TEXT NOT NULL,\n  platform_id TEXT,\n  content_excerpt TEXT,\n  sentiment NUMERIC CHECK (sentiment >= -1 AND sentiment <= 1),\n  traffic_type TEXT CHECK (traffic_type IN ('organic','paid')) DEFAULT 'organic',\n  metadata JSONB,\n  occurred_at TIMESTAMPTZ DEFAULT NOW()\n)","CREATE INDEX IF NOT EXISTS idx_person_events_person ON person_events(person_id, occurred_at DESC)","CREATE INDEX IF NOT EXISTS idx_person_events_type ON person_events(event_type, occurred_at DESC)","CREATE INDEX IF NOT EXISTS idx_person_events_traffic ON person_events(traffic_type)","CREATE INDEX IF NOT EXISTS idx_person_events_channel ON person_events(channel, occurred_at DESC)","CREATE INDEX IF NOT EXISTS idx_person_events_person_channel ON person_events(person_id, channel, occurred_at DESC)","-- =====================================================\n-- PERSON INSIGHTS: Computed \\"lens\\" for each person\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS person_insights (\n  person_id UUID PRIMARY KEY REFERENCES people(id) ON DELETE CASCADE,\n  interests JSONB,\n  tone_preferences JSONB,\n  channel_preferences JSONB,\n  avg_reply_time INTERVAL,\n  activity_state TEXT CHECK (activity_state IN ('active','warming','cool','dormant')),\n  last_active_at TIMESTAMPTZ,\n  seasonality JSONB,\n  warmth_score NUMERIC,\n  updated_at TIMESTAMPTZ DEFAULT NOW()\n)","CREATE INDEX IF NOT EXISTS idx_active_people ON person_insights(person_id) \n  WHERE activity_state IN ('active','warming')","-- =====================================================\n-- SEGMENTS: Dynamic people grouping\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS segments (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  name TEXT NOT NULL,\n  description TEXT,\n  definition JSONB,\n  created_by UUID,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  updated_at TIMESTAMPTZ DEFAULT NOW()\n)","CREATE TABLE IF NOT EXISTS segment_members (\n  segment_id UUID REFERENCES segments(id) ON DELETE CASCADE,\n  person_id UUID REFERENCES people(id) ON DELETE CASCADE,\n  added_at TIMESTAMPTZ DEFAULT NOW(),\n  PRIMARY KEY (segment_id, person_id)\n)","CREATE INDEX IF NOT EXISTS idx_segment_members_person ON segment_members(person_id)","CREATE INDEX IF NOT EXISTS idx_segment_members_segment ON segment_members(segment_id)","-- =====================================================\n-- SEGMENT INSIGHTS: Per-segment analytics\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS segment_insights (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  segment_id UUID REFERENCES segments(id) ON DELETE CASCADE,\n  traffic_type TEXT CHECK (traffic_type IN ('organic','paid')),\n  top_topics JSONB,\n  top_platforms JSONB,\n  top_formats JSONB,\n  engagement_style JSONB,\n  best_times JSONB,\n  expected_reach_range INT4RANGE,\n  expected_engagement_rate_range NUMRANGE,\n  updated_at TIMESTAMPTZ DEFAULT NOW(),\n  UNIQUE(segment_id, traffic_type)\n)","CREATE INDEX IF NOT EXISTS idx_segment_insights_segment ON segment_insights(segment_id)","-- =====================================================\n-- OUTBOUND MESSAGES: Email/DM tracking\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS outbound_messages (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  person_id UUID REFERENCES people(id) ON DELETE CASCADE,\n  segment_id UUID REFERENCES segments(id) ON DELETE SET NULL,\n  channel TEXT NOT NULL,\n  goal_type TEXT,\n  variant TEXT,\n  subject TEXT,\n  body TEXT,\n  sent_at TIMESTAMPTZ DEFAULT NOW(),\n  opened_at TIMESTAMPTZ,\n  clicked_at TIMESTAMPTZ,\n  replied_at TIMESTAMPTZ,\n  metadata JSONB\n)","CREATE INDEX IF NOT EXISTS idx_outbound_person ON outbound_messages(person_id, sent_at DESC)","CREATE INDEX IF NOT EXISTS idx_outbound_segment ON outbound_messages(segment_id, sent_at DESC)","CREATE INDEX IF NOT EXISTS idx_outbound_channel ON outbound_messages(channel, sent_at DESC)","-- =====================================================\n-- Enable Row Level Security (RLS)\n-- =====================================================\n\nALTER TABLE people ENABLE ROW LEVEL SECURITY","ALTER TABLE identities ENABLE ROW LEVEL SECURITY","ALTER TABLE person_events ENABLE ROW LEVEL SECURITY","ALTER TABLE person_insights ENABLE ROW LEVEL SECURITY","ALTER TABLE segments ENABLE ROW LEVEL SECURITY","ALTER TABLE segment_members ENABLE ROW LEVEL SECURITY","ALTER TABLE segment_insights ENABLE ROW LEVEL SECURITY","ALTER TABLE outbound_messages ENABLE ROW LEVEL SECURITY","-- =====================================================\n-- Comments for documentation\n-- =====================================================\n\nCOMMENT ON TABLE people IS 'Core person entities - one row per unique human'","COMMENT ON TABLE identities IS 'Cross-platform identity mapping (email, social handles)'","COMMENT ON TABLE person_events IS 'Unified event stream of all interactions'","COMMENT ON TABLE person_insights IS 'Computed person lens (interests, preferences, warmth)'","COMMENT ON TABLE segments IS 'Dynamic groups of people'","COMMENT ON TABLE segment_insights IS 'Per-segment analytics (organic vs paid separated)'","COMMENT ON TABLE outbound_messages IS 'Log of all emails/DMs sent'"}	people_graph
20250121000002	{"-- Content Graph Extensions  \n-- Migration: 002_content_graph_extensions\n-- Created: 2025-01-21\n-- Note: content_items, content_variants, content_metrics already exist\n\n-- =====================================================\n-- CONTENT ROLLUPS: Aggregated cross-platform metrics\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS content_rollups (\n  content_id UUID PRIMARY KEY REFERENCES content_items(id) ON DELETE CASCADE,\n  total_views BIGINT DEFAULT 0,\n  total_impressions BIGINT DEFAULT 0,\n  total_likes BIGINT DEFAULT 0,\n  total_comments BIGINT DEFAULT 0,\n  total_shares BIGINT DEFAULT 0,\n  total_saves BIGINT DEFAULT 0,\n  total_clicks BIGINT DEFAULT 0,\n  avg_watch_time_seconds NUMERIC,\n  global_sentiment NUMERIC CHECK (global_sentiment >= -1 AND global_sentiment <= 1),\n  best_platform TEXT,\n  last_updated_at TIMESTAMPTZ DEFAULT NOW()\n)","CREATE INDEX IF NOT EXISTS idx_rollups_platform ON content_rollups(best_platform)","CREATE INDEX IF NOT EXISTS idx_rollups_updated ON content_rollups(last_updated_at DESC)","-- =====================================================\n-- CONTENT EXPERIMENTS: A/B/multivariate testing\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS content_experiments (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  content_id UUID REFERENCES content_items(id) ON DELETE CASCADE,\n  name TEXT NOT NULL,\n  hypothesis TEXT,\n  primary_metric TEXT,\n  status TEXT CHECK (status IN ('draft','running','completed','cancelled')) DEFAULT 'draft',\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  started_at TIMESTAMPTZ,\n  completed_at TIMESTAMPTZ\n)","CREATE INDEX IF NOT EXISTS idx_experiments_content ON content_experiments(content_id)","CREATE INDEX IF NOT EXISTS idx_experiments_status ON content_experiments(status)","-- =====================================================\n-- Update content_metrics if needed (add traffic_type)\n-- =====================================================\n\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM information_schema.columns \n    WHERE table_name='content_metrics' AND column_name='traffic_type'\n  ) THEN\n    ALTER TABLE content_metrics \n    ADD COLUMN traffic_type TEXT CHECK (traffic_type IN ('organic','paid')) DEFAULT 'organic';\n    \n    CREATE INDEX idx_metrics_traffic ON content_metrics(traffic_type);\n  END IF;\nEND $$","-- =====================================================\n-- Enable RLS\n-- =====================================================\n\nALTER TABLE content_rollups ENABLE ROW LEVEL SECURITY","ALTER TABLE content_experiments ENABLE ROW LEVEL SECURITY","-- =====================================================\n-- Comments\n-- =====================================================\n\nCOMMENT ON TABLE content_rollups IS 'Nightly aggregated metrics per content ID (cross-platform)'","COMMENT ON TABLE content_experiments IS 'A/B/multivariate testing framework'"}	content_graph_extensions
20250121000003	{"-- Platform Connectors Configuration\n-- Migration: 003_connectors\n-- Created: 2025-01-21\n\n-- =====================================================\n-- IG_CONNECTIONS: Instagram/Meta OAuth tokens\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS ig_connections (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  everreach_user_id UUID NOT NULL,\n  fb_page_id TEXT NOT NULL,\n  ig_business_id TEXT NOT NULL,\n  access_token TEXT NOT NULL,\n  token_expires_at TIMESTAMPTZ NOT NULL,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  last_synced_at TIMESTAMPTZ\n)","CREATE INDEX IF NOT EXISTS idx_ig_conn_user ON ig_connections(everreach_user_id)","CREATE INDEX IF NOT EXISTS idx_ig_conn_expires ON ig_connections(token_expires_at)","-- =====================================================\n-- CONNECTOR_CONFIGS: Generic connector configuration\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS connector_configs (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL,\n  connector_type TEXT NOT NULL CHECK (connector_type IN (\n    'meta','youtube','tiktok','blotato','linkedin','twitter',\n    'pinterest','threads','bluesky','rapidapi','esp'\n  )),\n  config JSONB NOT NULL,\n  is_enabled BOOLEAN DEFAULT TRUE,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  updated_at TIMESTAMPTZ DEFAULT NOW(),\n  UNIQUE(user_id, connector_type)\n)","CREATE INDEX IF NOT EXISTS idx_connector_user ON connector_configs(user_id)","CREATE INDEX IF NOT EXISTS idx_connector_type ON connector_configs(connector_type)","CREATE INDEX IF NOT EXISTS idx_connector_enabled ON connector_configs(is_enabled) WHERE is_enabled = TRUE","-- =====================================================\n-- Enable RLS\n-- =====================================================\n\nALTER TABLE ig_connections ENABLE ROW LEVEL SECURITY","ALTER TABLE connector_configs ENABLE ROW LEVEL SECURITY","-- =====================================================\n-- Comments\n-- =====================================================\n\nCOMMENT ON TABLE ig_connections IS 'Instagram/Meta OAuth connection tokens'","COMMENT ON TABLE connector_configs IS 'Generic connector configuration store for all platforms'","COMMENT ON COLUMN connector_configs.config IS 'JSONB containing API keys, OAuth tokens, and connector-specific settings'"}	connectors
20250121000004	{"-- Base video tables for Content Intelligence System\n-- Migration: 003_base_video_tables\n-- Created: 2025-01-21\n-- Creates original_videos and clips tables with id columns to match migration expectations\n\n-- Enable UUID extension if not exists\nCREATE EXTENSION IF NOT EXISTS \\"uuid-ossp\\"","-- Original Videos Table (with id column for compatibility)\nCREATE TABLE IF NOT EXISTS original_videos (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    video_id UUID UNIQUE DEFAULT gen_random_uuid(), -- Keep for backward compatibility\n    source VARCHAR(255) NOT NULL,\n    file_path TEXT NOT NULL,\n    file_name VARCHAR(500) NOT NULL,\n    file_size_bytes BIGINT NOT NULL,\n    duration_seconds FLOAT NOT NULL,\n    \n    date_recorded TIMESTAMP WITH TIME ZONE,\n    date_uploaded TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    date_processed TIMESTAMP WITH TIME ZONE,\n    \n    transcript TEXT,\n    topics TEXT[],\n    keywords TEXT[],\n    \n    analysis_data JSONB,\n    metadata JSONB,\n    \n    processing_status VARCHAR(50) DEFAULT 'pending',\n    error_message TEXT,\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n)","CREATE INDEX IF NOT EXISTS idx_original_videos_status ON original_videos(processing_status)","CREATE INDEX IF NOT EXISTS idx_original_videos_date_recorded ON original_videos(date_recorded DESC)","CREATE INDEX IF NOT EXISTS idx_original_videos_video_id ON original_videos(video_id)","-- Clips Table (with id column for compatibility)\nCREATE TABLE IF NOT EXISTS clips (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    clip_id UUID UNIQUE DEFAULT gen_random_uuid(), -- Keep for backward compatibility\n    parent_video_id UUID REFERENCES original_videos(id) ON DELETE CASCADE,\n    \n    segment_start_seconds FLOAT NOT NULL,\n    segment_end_seconds FLOAT NOT NULL,\n    clip_duration_seconds FLOAT NOT NULL,\n    \n    file_path TEXT,\n    file_size_bytes BIGINT,\n    \n    hook_text TEXT,\n    caption_text TEXT,\n    generated_hashtags TEXT[],\n    \n    tags TEXT[],\n    content_category VARCHAR(100),\n    hook_type VARCHAR(100),\n    has_cta BOOLEAN DEFAULT false,\n    visual_elements JSONB,\n    target_keyword VARCHAR(255),\n    predicted_audience_reaction VARCHAR(100),\n    \n    clip_status VARCHAR(50) DEFAULT 'generated',\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n)","CREATE INDEX IF NOT EXISTS idx_clips_parent_video ON clips(parent_video_id)","CREATE INDEX IF NOT EXISTS idx_clips_status ON clips(clip_status)","CREATE INDEX IF NOT EXISTS idx_clips_hook_type ON clips(hook_type)","CREATE INDEX IF NOT EXISTS idx_clips_target_keyword ON clips(target_keyword)","CREATE INDEX IF NOT EXISTS idx_clips_clip_id ON clips(clip_id)","-- Enable RLS\nALTER TABLE original_videos ENABLE ROW LEVEL SECURITY","ALTER TABLE clips ENABLE ROW LEVEL SECURITY","COMMENT ON TABLE original_videos IS 'Original videos uploaded from iPhone or other sources'","COMMENT ON TABLE clips IS 'Generated short clips from video highlights'"}	base_video_tables
20250121000005	{"-- Content Intelligence System - Part 1: Video Analysis Tables\n-- This migration creates tables for comprehensive video/image analysis\n-- including word-level timestamps, frame analysis, segments, captions, and headlines\n\n-- Core video analysis metadata\nCREATE TABLE IF NOT EXISTS analyzed_videos (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    original_video_id UUID REFERENCES original_videos(id) ON DELETE CASCADE,\n    content_item_id UUID REFERENCES content_items(id) ON DELETE CASCADE,\n    duration_seconds DECIMAL,\n    transcript_full TEXT,\n    analyzed_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n)","-- Timeline segments (hook, context, body, CTA, payoff)\nCREATE TABLE IF NOT EXISTS video_segments (\n    id BIGSERIAL PRIMARY KEY,\n    video_id UUID REFERENCES analyzed_videos(id) ON DELETE CASCADE,\n    segment_type TEXT NOT NULL, -- 'hook' | 'context' | 'body' | 'cta' | 'payoff'\n    start_s DECIMAL NOT NULL,\n    end_s DECIMAL NOT NULL,\n    \n    -- Psychology tags (FATE + AIDA framework)\n    hook_type TEXT, -- 'pain' | 'curiosity' | 'aspirational' | 'contrarian' | 'gap' | 'absurd'\n    focus TEXT, -- Target audience/problem description\n    authority_signal TEXT, -- Credentials, proof, experience mentioned\n    tribe_marker TEXT, -- Identity calls, shared language\n    emotion TEXT, -- 'relief' | 'excitement' | 'curiosity' | 'FOMO' | 'frustration'\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    CONSTRAINT valid_time_range CHECK (end_s >= start_s)\n)","-- Word-level timestamps with NLP analysis\nCREATE TABLE IF NOT EXISTS video_words (\n    id BIGSERIAL PRIMARY KEY,\n    video_id UUID REFERENCES analyzed_videos(id) ON DELETE CASCADE,\n    segment_id BIGINT REFERENCES video_segments(id) ON DELETE CASCADE,\n    word_index INTEGER NOT NULL,\n    word TEXT NOT NULL,\n    start_s DECIMAL NOT NULL,\n    end_s DECIMAL NOT NULL,\n    \n    -- Analysis tags\n    is_emphasis BOOLEAN DEFAULT FALSE, -- Caps, pitch change, hook words\n    is_question BOOLEAN DEFAULT FALSE,\n    is_cta_keyword BOOLEAN DEFAULT FALSE,\n    speech_function TEXT, -- 'hook' | 'proof' | 'step' | 'metaphor' | 'cta' | 'future_promise'\n    sentiment_score DECIMAL, -- -1 to +1\n    emotion TEXT, -- 'curiosity' | 'frustration' | 'hope' | 'flex' | 'warning'\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    CONSTRAINT valid_word_time CHECK (end_s >= start_s)\n)","-- Frame-by-frame visual analysis\nCREATE TABLE IF NOT EXISTS video_frames (\n    id BIGSERIAL PRIMARY KEY,\n    video_id UUID REFERENCES analyzed_videos(id) ON DELETE CASCADE,\n    segment_id BIGINT REFERENCES video_segments(id) ON DELETE SET NULL,\n    frame_time_s DECIMAL NOT NULL,\n    frame_url TEXT, -- S3/storage URL for the frame image\n    \n    -- Visual classification\n    shot_type TEXT, -- 'close_up' | 'medium' | 'wide' | 'screen_record' | 'broll'\n    camera_motion TEXT, -- 'static' | 'slight' | 'aggressive'\n    presence TEXT[], -- ['face', 'full_body', 'hands', 'laptop', 'whiteboard', 'phone']\n    objects TEXT[], -- Detected objects\n    text_on_screen TEXT, -- OCR extracted text\n    logo_detected TEXT[], -- Brand logos found\n    \n    -- Visual properties\n    brightness_level TEXT, -- 'dark' | 'normal' | 'bright'\n    color_temperature TEXT, -- 'warm' | 'neutral' | 'cool'\n    visual_clutter_score DECIMAL, -- 0-1 (how busy/messy the frame is)\n    \n    -- Pattern analysis\n    is_pattern_interrupt BOOLEAN DEFAULT FALSE, -- Big change vs previous frame\n    is_hook_frame BOOLEAN DEFAULT FALSE, -- Eyes to camera, bold text, etc.\n    has_meme_element BOOLEAN DEFAULT FALSE, -- Reaction face, overlay, cutaway\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n)","-- Caption styling and positioning\nCREATE TABLE IF NOT EXISTS video_captions (\n    id BIGSERIAL PRIMARY KEY,\n    video_id UUID REFERENCES analyzed_videos(id) ON DELETE CASCADE,\n    clip_id UUID REFERENCES clips(id) ON DELETE CASCADE,\n    start_s DECIMAL NOT NULL,\n    end_s DECIMAL NOT NULL,\n    text TEXT NOT NULL,\n    \n    -- Styling\n    font_family TEXT,\n    font_weight TEXT, -- 'regular' | 'semibold' | 'bold'\n    font_size INTEGER,\n    text_color TEXT,\n    background_style TEXT, -- 'box' | 'outline' | 'highlight_bar' | 'none'\n    position TEXT, -- 'top' | 'mid' | 'bottom'\n    animation TEXT, -- 'fade' | 'pop' | 'typewriter' | 'karaoke'\n    \n    -- Keyword emphasis\n    emphasized_words TEXT[],\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    CONSTRAINT valid_caption_time CHECK (end_s >= start_s)\n)","-- Persistent headline overlay (\\"catchy text throughout\\")\nCREATE TABLE IF NOT EXISTS video_headlines (\n    id BIGSERIAL PRIMARY KEY,\n    video_id UUID REFERENCES analyzed_videos(id) ON DELETE CASCADE,\n    clip_id UUID REFERENCES clips(id) ON DELETE CASCADE,\n    main_text TEXT NOT NULL,\n    sub_text TEXT,\n    start_s DECIMAL DEFAULT 0,\n    end_s DECIMAL, -- NULL = entire video duration\n    position TEXT, -- 'top_bar' | 'bottom_bar' | 'mid_left' | 'mid_right'\n    \n    -- Styling\n    font_family TEXT,\n    font_size INTEGER,\n    text_color TEXT,\n    background_style TEXT, -- 'pill' | 'banner' | 'transparent' | 'blur_bar'\n    corner_radius INTEGER,\n    padding INTEGER,\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n)","-- Indexes for performance\nCREATE INDEX IF NOT EXISTS idx_analyzed_videos_original ON analyzed_videos(original_video_id)","CREATE INDEX IF NOT EXISTS idx_analyzed_videos_content ON analyzed_videos(content_item_id)","CREATE INDEX IF NOT EXISTS idx_video_segments_video ON video_segments(video_id)","CREATE INDEX IF NOT EXISTS idx_video_segments_type ON video_segments(segment_type)","CREATE INDEX IF NOT EXISTS idx_video_segments_time ON video_segments(start_s, end_s)","CREATE INDEX IF NOT EXISTS idx_video_words_video ON video_words(video_id)","CREATE INDEX IF NOT EXISTS idx_video_words_segment ON video_words(segment_id)","CREATE INDEX IF NOT EXISTS idx_video_words_time ON video_words(start_s)","CREATE INDEX IF NOT EXISTS idx_video_words_cta ON video_words(is_cta_keyword) WHERE is_cta_keyword = TRUE","CREATE INDEX IF NOT EXISTS idx_video_frames_video ON video_frames(video_id)","CREATE INDEX IF NOT EXISTS idx_video_frames_segment ON video_frames(segment_id)","CREATE INDEX IF NOT EXISTS idx_video_frames_time ON video_frames(frame_time_s)","CREATE INDEX IF NOT EXISTS idx_video_frames_hooks ON video_frames(is_hook_frame) WHERE is_hook_frame = TRUE","CREATE INDEX IF NOT EXISTS idx_video_frames_interrupts ON video_frames(is_pattern_interrupt) WHERE is_pattern_interrupt = TRUE","CREATE INDEX IF NOT EXISTS idx_video_captions_video ON video_captions(video_id)","CREATE INDEX IF NOT EXISTS idx_video_captions_clip ON video_captions(clip_id)","CREATE INDEX IF NOT EXISTS idx_video_headlines_video ON video_headlines(video_id)","CREATE INDEX IF NOT EXISTS idx_video_headlines_clip ON video_headlines(clip_id)","-- Enable RLS\nALTER TABLE analyzed_videos ENABLE ROW LEVEL SECURITY","ALTER TABLE video_segments ENABLE ROW LEVEL SECURITY","ALTER TABLE video_words ENABLE ROW LEVEL SECURITY","ALTER TABLE video_frames ENABLE ROW LEVEL SECURITY","ALTER TABLE video_captions ENABLE ROW LEVEL SECURITY","ALTER TABLE video_headlines ENABLE ROW LEVEL SECURITY","-- Comments for documentation\nCOMMENT ON TABLE analyzed_videos IS 'Core video analysis metadata with transcript'","COMMENT ON TABLE video_segments IS 'Timeline segments: hook, context, body, CTA with psychology tags'","COMMENT ON TABLE video_words IS 'Word-level timestamps with NLP analysis and sentiment'","COMMENT ON TABLE video_frames IS 'Frame-by-frame visual analysis with OCR and object detection'","COMMENT ON TABLE video_captions IS 'Caption styling and positioning for generated clips'","COMMENT ON TABLE video_headlines IS 'Persistent headline overlays explaining the video'"}	content_intelligence_video_analysis
20250121000006	{"-- Content Intelligence System - Part 2: Platform Performance & Checkback Tracking\n-- This migration creates tables for tracking posts across 9 social media platforms\n-- with detailed checkback metrics, comment sentiment, and engagement analysis\n\n-- Platform-specific post tracking (extends content_variants)\nCREATE TABLE IF NOT EXISTS platform_posts (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    content_variant_id UUID REFERENCES content_variants(id) ON DELETE CASCADE,\n    clip_id UUID REFERENCES clips(id) ON DELETE SET NULL,\n    platform TEXT NOT NULL, -- 'tiktok' | 'instagram' | 'youtube' | 'linkedin' | 'twitter' | 'facebook' | 'pinterest' | 'snapchat' | 'threads'\n    platform_post_id TEXT NOT NULL,\n    platform_url TEXT,\n    published_at TIMESTAMP WITH TIME ZONE,\n    scheduled_for TIMESTAMP WITH TIME ZONE,\n    status TEXT DEFAULT 'scheduled', -- 'scheduled' | 'publishing' | 'published' | 'failed' | 'deleted'\n    \n    -- Metadata\n    title TEXT,\n    caption TEXT,\n    hashtags TEXT[],\n    thumbnail_url TEXT,\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    UNIQUE(platform, platform_post_id)\n)","-- Checkback metrics at specific intervals (1h, 6h, 24h, 72h, 7d)\nCREATE TABLE IF NOT EXISTS platform_checkbacks (\n    id BIGSERIAL PRIMARY KEY,\n    platform_post_id UUID REFERENCES platform_posts(id) ON DELETE CASCADE,\n    checkback_h INTEGER NOT NULL, -- 1, 6, 24, 72, 168 (hours after publishing)\n    checked_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    \n    -- Core metrics\n    views INTEGER DEFAULT 0,\n    unique_viewers INTEGER DEFAULT 0,\n    impressions INTEGER DEFAULT 0,\n    \n    -- Retention metrics\n    avg_watch_time_s DECIMAL,\n    avg_watch_pct DECIMAL, -- 0-1\n    retention_curve JSONB, -- [{\\"t_pct\\": 0.1, \\"retention\\": 0.96}, ...]\n    \n    -- Engagement metrics\n    likes INTEGER DEFAULT 0,\n    comments INTEGER DEFAULT 0,\n    shares INTEGER DEFAULT 0,\n    saves INTEGER DEFAULT 0,\n    profile_taps INTEGER DEFAULT 0,\n    link_clicks INTEGER DEFAULT 0,\n    \n    -- Derived rates (calculated)\n    like_rate DECIMAL, -- likes / views\n    comment_rate DECIMAL, -- comments / views\n    share_rate DECIMAL, -- shares / views\n    save_rate DECIMAL, -- saves / views\n    cta_response_count INTEGER DEFAULT 0, -- Comments matching CTA keywords\n    \n    -- Engaged reach\n    engaged_users INTEGER DEFAULT 0, -- Unique users who engaged (comment/save/share/tap/click)\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    UNIQUE(platform_post_id, checkback_h)\n)","-- Comment-level sentiment and theme analysis\nCREATE TABLE IF NOT EXISTS post_comments (\n    id BIGSERIAL PRIMARY KEY,\n    platform_post_id UUID REFERENCES platform_posts(id) ON DELETE CASCADE,\n    platform_comment_id TEXT NOT NULL,\n    author_handle TEXT,\n    author_name TEXT,\n    text TEXT NOT NULL,\n    created_at_platform TIMESTAMP WITH TIME ZONE,\n    \n    -- Sentiment analysis\n    sentiment_score DECIMAL, -- -1 (negative) to +1 (positive)\n    emotion_tags TEXT[], -- ['excited', 'skeptical', 'confused', 'grateful', 'angry']\n    intent TEXT, -- 'question' | 'praise' | 'critique' | 'spam' | 'engagement'\n    theme_tags TEXT[], -- ['automation_overwhelm', 'want_templates', 'skeptical_of_bots']\n    \n    -- CTA response tracking\n    is_cta_response BOOLEAN DEFAULT FALSE,\n    cta_keyword TEXT, -- The keyword they typed (e.g., \\"Tech\\", \\"PROMPT\\")\n    \n    -- Moderation\n    is_spam BOOLEAN DEFAULT FALSE,\n    is_hidden BOOLEAN DEFAULT FALSE,\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    UNIQUE(platform_post_id, platform_comment_id)\n)","-- Retention drop events (for detailed analysis)\nCREATE TABLE IF NOT EXISTS retention_events (\n    id BIGSERIAL PRIMARY KEY,\n    platform_post_id UUID REFERENCES platform_posts(id) ON DELETE CASCADE,\n    video_id UUID REFERENCES analyzed_videos(id) ON DELETE CASCADE,\n    event_type TEXT NOT NULL, -- 'drop' | 'spike' | 'plateau'\n    time_s DECIMAL NOT NULL, -- When in the video this happened\n    retention_before DECIMAL, -- 0-1\n    retention_after DECIMAL, -- 0-1\n    delta DECIMAL, -- Change in retention\n    \n    -- Context at that moment\n    segment_id BIGINT REFERENCES video_segments(id) ON DELETE SET NULL,\n    local_words TEXT[], -- Words spoken around this time\n    frame_snapshot JSONB, -- Frame analysis at this time\n    \n    -- Analysis\n    likely_cause TEXT, -- 'jargon_heavy' | 'no_face' | 'visual_clutter' | 'topic_shift'\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n)","-- A/B Test tracking for content experiments\nCREATE TABLE IF NOT EXISTS content_ab_tests (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    test_name TEXT NOT NULL,\n    hypothesis TEXT, -- What you're testing\n    variable_tested TEXT, -- 'hook_type' | 'caption_style' | 'thumbnail' | 'posting_time'\n    start_date DATE NOT NULL,\n    end_date DATE,\n    status TEXT DEFAULT 'active', --'active' | 'completed' | 'paused'\n    \n    -- Variant posts (array of platform_post IDs)\n    variant_a_posts UUID[] DEFAULT '{}',\n    variant_b_posts UUID[] DEFAULT '{}',\n    \n    -- Results (filled when completed)\n    winner TEXT, -- 'a' | 'b' | 'tie'\n    improvement_pct DECIMAL,\n    confidence_score DECIMAL, -- Statistical confidence\n    notes TEXT,\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n)","-- Indexes for performance\nCREATE INDEX IF NOT EXISTS idx_platform_posts_variant ON platform_posts(content_variant_id)","CREATE INDEX IF NOT EXISTS idx_platform_posts_clip ON platform_posts(clip_id)","CREATE INDEX IF NOT EXISTS idx_platform_posts_platform ON platform_posts(platform)","CREATE INDEX IF NOT EXISTS idx_platform_posts_status ON platform_posts(status)","CREATE INDEX IF NOT EXISTS idx_platform_posts_published ON platform_posts(published_at)","CREATE INDEX IF NOT EXISTS idx_platform_posts_scheduled ON platform_posts(scheduled_for) WHERE status = 'scheduled'","CREATE INDEX IF NOT EXISTS idx_checkbacks_post ON platform_checkbacks(platform_post_id)","CREATE INDEX IF NOT EXISTS idx_checkbacks_time ON platform_checkbacks(checkback_h)","CREATE INDEX IF NOT EXISTS idx_checkbacks_checked ON platform_checkbacks(checked_at)","CREATE INDEX IF NOT EXISTS idx_comments_post ON post_comments(platform_post_id)","CREATE INDEX IF NOT EXISTS idx_comments_sentiment ON post_comments(sentiment_score)","CREATE INDEX IF NOT EXISTS idx_comments_cta ON post_comments(is_cta_response) WHERE is_cta_response = TRUE","CREATE INDEX IF NOT EXISTS idx_comments_platform_created ON post_comments(created_at_platform)","CREATE INDEX IF NOT EXISTS idx_retention_events_post ON retention_events(platform_post_id)","CREATE INDEX IF NOT EXISTS idx_retention_events_video ON retention_events(video_id)","CREATE INDEX IF NOT EXISTS idx_retention_events_type ON retention_events(event_type)","CREATE INDEX IF NOT EXISTS idx_ab_tests_status ON content_ab_tests(status)","CREATE INDEX IF NOT EXISTS idx_ab_tests_dates ON content_ab_tests(start_date, end_date)","-- Enable RLS\nALTER TABLE platform_posts ENABLE ROW LEVEL SECURITY","ALTER TABLE platform_checkbacks ENABLE ROW LEVEL SECURITY","ALTER TABLE post_comments ENABLE ROW LEVEL SECURITY","ALTER TABLE retention_events ENABLE ROW LEVEL SECURITY","ALTER TABLE content_ab_tests ENABLE ROW LEVEL SECURITY","-- Comments for documentation\nCOMMENT ON TABLE platform_posts IS 'Platform-specific post tracking across 9 social media platforms'","COMMENT ON TABLE platform_checkbacks IS 'Checkback metrics at 1h, 6h, 24h, 72h, 7d intervals'","COMMENT ON TABLE post_comments IS 'Comment-level sentiment and theme analysis with CTA tracking'","COMMENT ON TABLE retention_events IS 'Retention drops/spikes with contextual word and frame data'","COMMENT ON TABLE content_ab_tests IS 'A/B test tracking for content experiments'"}	content_intelligence_platform_tracking
20250121000007	{"-- Content Intelligence System - Part 3: North Star Metrics & AI Insights\n-- This migration creates tables for weekly aggregated metrics, north star metrics,\n-- AI-generated insights, and content recommendations\n\n-- Weekly aggregated metrics (North Star Metrics)\nCREATE TABLE IF NOT EXISTS weekly_metrics (\n    id BIGSERIAL PRIMARY KEY,\n    week_start_date DATE NOT NULL,\n    user_id UUID, -- For multi-account support (future)\n    \n    -- North Star Metric #1: Weekly Engaged Reach\n    engaged_reach INTEGER DEFAULT 0, -- Unique people who meaningfully engaged\n    engaged_reach_delta_pct DECIMAL, -- % change vs last week\n    \n    -- North Star Metric #2: Content Leverage Score\n    content_leverage_score DECIMAL DEFAULT 0, -- (comments + saves + shares + taps) / posts\n    cls_delta_pct DECIMAL,\n    \n    -- North Star Metric #3: Warm Lead Flow\n    warm_lead_flow INTEGER DEFAULT 0, -- link_clicks + dm_starts + email_signups\n    warm_lead_flow_delta_pct DECIMAL,\n    \n    -- Supporting metrics\n    total_posts INTEGER DEFAULT 0,\n    total_views INTEGER DEFAULT 0,\n    total_watch_time_s BIGINT DEFAULT 0,\n    avg_retention_pct DECIMAL,\n    \n    -- Platform breakdown\n    platform_reach JSONB, -- {\\"tiktok\\": 1200, \\"instagram\\": 800, ...}\n    platform_posts JSONB, -- {\\"tiktok\\": 5, \\"instagram\\": 7, ...}\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    UNIQUE(week_start_date, user_id)\n)","-- AI-generated insights (pattern detection)\nCREATE TABLE IF NOT EXISTS content_insights (\n    id BIGSERIAL PRIMARY KEY,\n    insight_type TEXT NOT NULL, -- 'hook' | 'retention' | 'cta' | 'visual' | 'timing' | 'format'\n    title TEXT NOT NULL,\n    description TEXT NOT NULL,\n    metric_impact TEXT, -- \\"+23% avg improvement\\" | \\"2.1x higher engagement\\"\n    \n    -- What this insight is based on\n    based_on_post_ids UUID[], -- Array of platform_post IDs\n    based_on_segment_ids BIGINT[], -- Array of segment IDs\n    sample_size INTEGER, -- How many posts/segments this pattern was found in\n    confidence_score DECIMAL, -- 0-1 statistical confidence\n    \n    -- Pattern details\n    pattern_data JSONB, -- {\\"hook_type\\": \\"pain + identity\\", \\"visual_type\\": \\"close_up\\", ...}\n    \n    -- Recommended actions\n    recommended_action JSONB, -- {\\"type\\": \\"generate_hooks\\", \\"pattern\\": \\"pain + identity\\", \\"button_text\\": \\"Generate hooks\\"}\n    \n    -- Lifecycle\n    status TEXT DEFAULT 'active', -- 'active' | 'archived' | 'dismissed'\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    expires_at TIMESTAMP WITH TIME ZONE, -- Insights can be time-limited\n    dismissed_at TIMESTAMP WITH TIME ZONE,\n    \n    -- Tracking\n    times_applied INTEGER DEFAULT 0, -- How many times user acted on this\n    avg_result_improvement DECIMAL -- Did it actually help?\n)","-- Content performance predictions (ML model scores)\nCREATE TABLE IF NOT EXISTS content_predictions (\n    id BIGSERIAL PRIMARY KEY,\n    platform_post_id UUID REFERENCES platform_posts(id) ON DELETE CASCADE,\n    predicted_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    \n    -- Predictions (before publishing)\n    predicted_views INTEGER,\n    predicted_engagement_rate DECIMAL,\n    predicted_save_rate DECIMAL,\n    predicted_cta_response_rate DECIMAL,\n    confidence_score DECIMAL, -- 0-1\n    \n    -- Actual results (after checkbacks)\n    actual_views INTEGER,\n    actual_engagement_rate DECIMAL,\n    actual_save_rate DECIMAL,\n    actual_cta_response_rate DECIMAL,\n    \n    -- Model performance\n    prediction_accuracy DECIMAL, -- How close were we?\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n)","-- Content recommendations (what to post next)\nCREATE TABLE IF NOT EXISTS content_recommendations (\n    id BIGSERIAL PRIMARY KEY,\n    recommendation_type TEXT NOT NULL, -- 'post_timing' | 'topic' | 'format' | 'platform' | 'remix'\n    title TEXT NOT NULL,\n    description TEXT NOT NULL,\n    reasoning TEXT, -- Why this recommendation\n    \n    -- Details\n    recommended_data JSONB, -- {\\"day\\": \\"Tuesday\\", \\"time\\": \\"3-6pm\\", \\"platform\\": \\"tiktok\\"}\n    \n    -- Based on\n    based_on_insight_ids BIGINT[], -- References to insights\n    expected_improvement TEXT, -- \\"+15% engagement vs your baseline\\"\n    \n    -- Priority\n    priority INTEGER DEFAULT 5, -- 1-10\n    \n    -- Status\n    status TEXT DEFAULT 'pending', -- 'pending' | 'accepted' | 'rejected' | 'completed'\n    accepted_at TIMESTAMP WITH TIME ZONE,\n    completed_at TIMESTAMP WITH TIME ZONE,\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    expires_at TIMESTAMP WITH TIME ZONE\n)","-- Content quality scores (overall health metrics)\nCREATE TABLE IF NOT EXISTS content_quality_scores (\n    id BIGSERIAL PRIMARY KEY,\n    platform_post_id UUID REFERENCES platform_posts(id) ON DELETE CASCADE,\n    video_id UUID REFERENCES analyzed_videos(id) ON DELETE CASCADE,\n    \n    -- Hook quality\n    hook_retention_3s DECIMAL, -- 0-1, retention at 3 seconds\n    hook_clarity_score DECIMAL, -- 0-1, is the hook clear and specific?\n    hook_pattern_score DECIMAL, -- 0-1, does it match proven patterns?\n    \n    -- Content structure\n    segment_balance_score DECIMAL, -- 0-1, good ratio of hook/body/cta?\n    pacing_score DECIMAL, -- 0-1, words per minute variance\n    \n    -- Visual quality\n    visual_variety_score DECIMAL, -- 0-1, shot type variety\n    text_readability_score DECIMAL, -- 0-1, can you read on-screen text?\n    pattern_interrupt_count INTEGER,\n    \n    -- CTA effectiveness\n    cta_clarity_score DECIMAL, -- 0-1, is CTA clear?\n    cta_timing_score DECIMAL, -- 0-1, is CTA timed well?\n    \n    -- Overall\n    overall_score DECIMAL, -- 0-100, weighted average\n    score_tier TEXT, -- 'excellent' | 'good' | 'average' | 'needs_work'\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n)","-- Indexes for performance\nCREATE INDEX IF NOT EXISTS idx_weekly_metrics_week ON weekly_metrics(week_start_date)","CREATE INDEX IF NOT EXISTS idx_weekly_metrics_user ON weekly_metrics(user_id)","CREATE INDEX IF NOT EXISTS idx_insights_type ON content_insights(insight_type)","CREATE INDEX IF NOT EXISTS idx_insights_status ON content_insights(status)","CREATE INDEX IF NOT EXISTS idx_insights_created ON content_insights(created_at)","CREATE INDEX IF NOT EXISTS idx_insights_expires ON content_insights(expires_at) WHERE expires_at IS NOT NULL","CREATE INDEX IF NOT EXISTS idx_predictions_post ON content_predictions(platform_post_id)","CREATE INDEX IF NOT EXISTS idx_predictions_predicted ON content_predictions(predicted_at)","CREATE INDEX IF NOT EXISTS idx_recommendations_type ON content_recommendations(recommendation_type)","CREATE INDEX IF NOT EXISTS idx_recommendations_status ON content_recommendations(status)","CREATE INDEX IF NOT EXISTS idx_recommendations_priority ON content_recommendations(priority)","CREATE INDEX IF NOT EXISTS idx_recommendations_expires ON content_recommendations(expires_at) WHERE expires_at IS NOT NULL","CREATE INDEX IF NOT EXISTS idx_quality_post ON content_quality_scores(platform_post_id)","CREATE INDEX IF NOT EXISTS idx_quality_video ON content_quality_scores(video_id)","CREATE INDEX IF NOT EXISTS idx_quality_tier ON content_quality_scores(score_tier)","-- Enable RLS\nALTER TABLE weekly_metrics ENABLE ROW LEVEL SECURITY","ALTER TABLE content_insights ENABLE ROW LEVEL SECURITY","ALTER TABLE content_predictions ENABLE ROW LEVEL SECURITY","ALTER TABLE content_recommendations ENABLE ROW LEVEL SECURITY","ALTER TABLE content_quality_scores ENABLE ROW LEVEL SECURITY","-- Comments for documentation\nCOMMENT ON TABLE weekly_metrics IS 'Weekly aggregated North Star Metrics: Engaged Reach, Content Leverage Score, Warm Lead Flow'","COMMENT ON TABLE content_insights IS 'AI-generated insights from pattern detection across videos'","COMMENT ON TABLE content_predictions IS 'ML predictions for content performance before publishing'","COMMENT ON TABLE content_recommendations IS 'Smart recommendations for what to post next'","COMMENT ON TABLE content_quality_scores IS 'Overall content quality scoring across multiple dimensions'"}	content_intelligence_insights_metrics
20250121000008	{"-- Phase 2: Video Library & Content Analysis\n-- Stores references to video files (local, drive, s3) and their analysis data\n\nCREATE TABLE IF NOT EXISTS videos (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    user_id UUID NOT NULL, -- Removed FK constraint for now (no auth system yet)\n    source_type TEXT NOT NULL CHECK (source_type IN ('local', 'gdrive', 'supabase', 's3', 'other')),\n    source_uri TEXT NOT NULL, -- path, file ID, or URL\n    file_name TEXT,\n    duration_sec INTEGER,\n    resolution TEXT, -- '1920x1080' etc\n    aspect_ratio TEXT, -- '9:16', '16:9'\n    content_item_id UUID REFERENCES content_items(id) ON DELETE SET NULL, -- Link to content system for cross-platform posting\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n)","CREATE TABLE IF NOT EXISTS video_analysis (\n    video_id UUID PRIMARY KEY REFERENCES videos(id) ON DELETE CASCADE,\n    transcript TEXT,\n    topics TEXT[], -- ['AI news', 'cat meme']\n    hooks TEXT[], -- standout hook lines\n    tone TEXT, -- 'educational', 'comedic'\n    pacing TEXT, -- 'fast', 'medium', 'slow'\n    key_moments JSONB, -- [{start, end, summary, suggested_caption}, ...]\n    pre_social_score NUMERIC, -- 0-100\n    analysis_version TEXT, -- model / prompt version\n    analyzed_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n)","-- Indexes\nCREATE INDEX IF NOT EXISTS idx_videos_user ON videos(user_id)","CREATE INDEX IF NOT EXISTS idx_videos_source ON videos(source_type)","CREATE INDEX IF NOT EXISTS idx_videos_content_item ON videos(content_item_id)","CREATE INDEX IF NOT EXISTS idx_video_analysis_score ON video_analysis(pre_social_score)","-- Note: RLS disabled for now since we don't have auth yet\n-- ALTER TABLE videos ENABLE ROW LEVEL SECURITY;\n-- ALTER TABLE video_analysis ENABLE ROW LEVEL SECURITY;\n\n-- Comments for documentation\nCOMMENT ON TABLE videos IS 'Video file references (local paths, Drive IDs, S3 URLs) - media stored externally, only metadata here'","COMMENT ON TABLE video_analysis IS 'AI analysis results for videos: transcripts, hooks, key moments, social score'","COMMENT ON COLUMN videos.content_item_id IS 'Links to content_items for cross-platform posting and unified stats tracking'"}	video_library
20250121000009	{"-- Fix Video Library Foreign Key Constraint\n-- Migration: 009_fix_video_library_fk\n-- Removes FK constraint to auth.users to allow placeholder UUIDs\n-- RLS policies will be added later when auth system is implemented\n\n-- Drop the foreign key constraint on user_id\nALTER TABLE videos \nDROP CONSTRAINT IF EXISTS videos_user_id_fkey","-- Note: RLS is already disabled in the original migration\n-- When auth is implemented, re-enable RLS and add policies:\n-- ALTER TABLE videos ENABLE ROW LEVEL SECURITY;\n-- CREATE POLICY \\"Users can view their own videos\\" ON videos\n--     FOR SELECT USING (auth.uid() = user_id);\n\nCOMMENT ON COLUMN videos.user_id IS 'User ID - FK constraint removed temporarily to allow placeholder UUIDs until auth system is implemented'"}	fix_video_library_fk
20250121000010	{"-- Add thumbnail support to videos table\n-- Migration 009: Video Thumbnails\n\nALTER TABLE videos\nADD COLUMN thumbnail_path TEXT,\nADD COLUMN thumbnail_generated_at TIMESTAMP WITH TIME ZONE,\nADD COLUMN best_frame_score DECIMAL(5,3)","-- Add comment\nCOMMENT ON COLUMN videos.thumbnail_path IS 'Path to generated thumbnail image'","COMMENT ON COLUMN videos.thumbnail_generated_at IS 'When thumbnail was generated'","COMMENT ON COLUMN videos.best_frame_score IS 'Quality score of selected thumbnail frame (0-1)'","-- Index for efficient queries\nCREATE INDEX IF NOT EXISTS idx_videos_thumbnail_generated \n  ON videos(thumbnail_generated_at) \n  WHERE thumbnail_path IS NOT NULL","-- Index for videos without thumbnails (for batch processing)\nCREATE INDEX IF NOT EXISTS idx_videos_no_thumbnail\n  ON videos(id)\n  WHERE thumbnail_path IS NULL"}	video_thumbnails
20250121000011	{"-- Clip Generation System Database Schema\n-- Creates tables for video clip selection, configuration, and publishing\n\n-- Enable UUID extension if not already enabled\nCREATE EXTENSION IF NOT EXISTS \\"uuid-ossp\\"","-- =====================================================\n-- VIDEO CLIPS TABLE\n-- =====================================================\n-- Stores clip configurations extracted from analyzed videos\n\nCREATE TABLE video_clips (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    video_id UUID NOT NULL,\n    user_id UUID NOT NULL,\n    \n    -- Clip timing (in seconds)\n    start_time FLOAT NOT NULL CHECK (start_time >= 0),\n    end_time FLOAT NOT NULL CHECK (end_time > start_time),\n    duration FLOAT GENERATED ALWAYS AS (end_time - start_time) STORED,\n    \n    -- Clip metadata\n    title VARCHAR(500),\n    description TEXT,\n    clip_type VARCHAR(50) DEFAULT 'custom',  -- 'highlight', 'full', 'custom', 'ai_generated'\n    \n    -- Configuration (JSONB for flexibility)\n    overlay_config JSONB DEFAULT '{}',  -- text overlays, positioning, styling\n    caption_config JSONB DEFAULT '{}',  -- caption styling, animations, timing\n    thumbnail_config JSONB DEFAULT '{}',  -- thumbnail frame selection, enhancements\n    \n    -- AI-generated insights\n    ai_suggested BOOLEAN DEFAULT false,\n    ai_score FLOAT CHECK (ai_score >= 0 AND ai_score <= 1),  -- 0-1 quality score\n    ai_reasoning TEXT,  -- why this clip was selected by AI\n    \n    -- Segment associations (references to video_segments)\n    segment_ids UUID[],  -- array of segment UUIDs\n    hook_segment_id UUID,  -- primary hook segment\n    \n    -- Platform optimization\n    platform_variants JSONB DEFAULT '{}',  -- platform-specific configurations\n    target_platforms VARCHAR(50)[],  -- intended platforms for this clip\n    \n    -- Status tracking\n    status VARCHAR(50) DEFAULT 'draft',  -- draft, ready, published, archived\n    render_status VARCHAR(50),  -- pending, processing, completed, failed (if rendering enabled)\n    rendered_url VARCHAR(500),  -- URL to rendered video file\n    render_error TEXT,  -- error message if rendering failed\n    \n    -- Metadata\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    \n    -- Constraints\n    CONSTRAINT fk_video FOREIGN KEY (video_id) REFERENCES videos(id) ON DELETE CASCADE,\n    CONSTRAINT valid_clip_type CHECK (clip_type IN ('highlight', 'full', 'custom', 'ai_generated')),\n    CONSTRAINT valid_status CHECK (status IN ('draft', 'ready', 'published', 'archived')),\n    CONSTRAINT valid_render_status CHECK (render_status IS NULL OR render_status IN ('pending', 'processing', 'completed', 'failed'))\n)","-- Indexes for performance\nCREATE INDEX IF NOT EXISTS idx_video_clips_video_id ON video_clips(video_id)","CREATE INDEX IF NOT EXISTS idx_video_clips_user_id ON video_clips(user_id)","CREATE INDEX IF NOT EXISTS idx_video_clips_status ON video_clips(status)","CREATE INDEX IF NOT EXISTS idx_video_clips_ai_suggested ON video_clips(ai_suggested) WHERE ai_suggested = true","CREATE INDEX IF NOT EXISTS idx_video_clips_created_at ON video_clips(created_at DESC)","CREATE INDEX IF NOT EXISTS idx_video_clips_target_platforms ON video_clips USING GIN(target_platforms)","-- Trigger to update updated_at timestamp\nCREATE OR REPLACE FUNCTION update_video_clips_updated_at()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at = NOW();\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql","CREATE TRIGGER video_clips_updated_at_trigger\n    BEFORE UPDATE ON video_clips\n    FOR EACH ROW\n    EXECUTE FUNCTION update_video_clips_updated_at()","-- =====================================================\n-- CLIP POSTS JUNCTION TABLE\n-- =====================================================\n-- Many-to-many relationship between clips and platform posts\n\nCREATE TABLE clip_posts (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    clip_id UUID NOT NULL,\n    post_id UUID NOT NULL,\n    platform VARCHAR(50) NOT NULL,\n    \n    -- Platform-specific overrides\n    platform_config JSONB DEFAULT '{}',  -- platform-specific metadata overrides\n    thumbnail_url VARCHAR(500),  -- platform-specific thumbnail\n    \n    -- Metadata\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    \n    -- Constraints\n    CONSTRAINT fk_clip FOREIGN KEY (clip_id) REFERENCES video_clips(id) ON DELETE CASCADE,\n    CONSTRAINT fk_post FOREIGN KEY (post_id) REFERENCES platform_posts(id) ON DELETE CASCADE,\n    CONSTRAINT unique_clip_post UNIQUE(clip_id, post_id)\n)","-- Indexes\nCREATE INDEX IF NOT EXISTS idx_clip_posts_clip_id ON clip_posts(clip_id)","CREATE INDEX IF NOT EXISTS idx_clip_posts_post_id ON clip_posts(post_id)","CREATE INDEX IF NOT EXISTS idx_clip_posts_platform ON clip_posts(platform)","-- =====================================================\n-- ROW LEVEL SECURITY (RLS) POLICIES\n-- =====================================================\n\n-- Enable RLS on video_clips\nALTER TABLE video_clips ENABLE ROW LEVEL SECURITY","-- Users can view their own clips\nCREATE POLICY video_clips_select_policy ON video_clips\n    FOR SELECT\n    USING (auth.uid() = user_id)","-- Users can insert their own clips\nCREATE POLICY video_clips_insert_policy ON video_clips\n    FOR INSERT\n    WITH CHECK (auth.uid() = user_id)","-- Users can update their own clips\nCREATE POLICY video_clips_update_policy ON video_clips\n    FOR UPDATE\n    USING (auth.uid() = user_id)","-- Users can delete their own clips\nCREATE POLICY video_clips_delete_policy ON video_clips\n    FOR DELETE\n    USING (auth.uid() = user_id)","-- Enable RLS on clip_posts\nALTER TABLE clip_posts ENABLE ROW LEVEL SECURITY","-- Users can view clip_posts for their clips\nCREATE POLICY clip_posts_select_policy ON clip_posts\n    FOR SELECT\n    USING (EXISTS (\n        SELECT 1 FROM video_clips vc\n        WHERE vc.id = clip_posts.clip_id\n        AND vc.user_id = auth.uid()\n    ))","-- Users can insert clip_posts for their clips\nCREATE POLICY clip_posts_insert_policy ON clip_posts\n    FOR INSERT\n    WITH CHECK (EXISTS (\n        SELECT 1 FROM video_clips vc\n        WHERE vc.id = clip_posts.clip_id\n        AND vc.user_id = auth.uid()\n    ))","-- Users can delete clip_posts for their clips\nCREATE POLICY clip_posts_delete_policy ON clip_posts\n    FOR DELETE\n    USING (EXISTS (\n        SELECT 1 FROM video_clips vc\n        WHERE vc.id = clip_posts.clip_id\n        AND vc.user_id = auth.uid()\n    ))","-- =====================================================\n-- HELPER FUNCTIONS\n-- =====================================================\n\n-- Function to get all clips for a video with their post status\nCREATE OR REPLACE FUNCTION get_video_clips_with_status(p_video_id UUID)\nRETURNS TABLE (\n    clip_id UUID,\n    title VARCHAR,\n    start_time FLOAT,\n    end_time FLOAT,\n    duration FLOAT,\n    clip_type VARCHAR,\n    ai_score FLOAT,\n    status VARCHAR,\n    post_count BIGINT,\n    platforms VARCHAR[]\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        vc.id,\n        vc.title,\n        vc.start_time,\n        vc.end_time,\n        vc.duration,\n        vc.clip_type,\n        vc.ai_score,\n        vc.status,\n        COUNT(DISTINCT cp.post_id) as post_count,\n        ARRAY_AGG(DISTINCT cp.platform) FILTER (WHERE cp.platform IS NOT NULL) as platforms\n    FROM video_clips vc\n    LEFT JOIN clip_posts cp ON vc.id = cp.clip_id\n    WHERE vc.video_id = p_video_id\n    GROUP BY vc.id\n    ORDER BY vc.created_at DESC;\nEND;\n$$ LANGUAGE plpgsql","-- Function to get clip performance metrics\nCREATE OR REPLACE FUNCTION get_clip_performance(p_clip_id UUID)\nRETURNS TABLE (\n    total_views BIGINT,\n    total_likes BIGINT,\n    total_shares BIGINT,\n    total_comments BIGINT,\n    avg_engagement_rate FLOAT,\n    platform_breakdown JSONB\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        SUM(pc.total_views)::BIGINT as total_views,\n        SUM(pc.total_likes)::BIGINT as total_likes,\n        SUM(pc.total_shares)::BIGINT as total_shares,\n        SUM(pc.total_comments)::BIGINT as total_comments,\n        AVG(\n            CASE \n                WHEN pc.total_views > 0 \n                THEN ((pc.total_likes + pc.total_shares + pc.total_comments)::FLOAT / pc.total_views)\n                ELSE 0\n            END\n        )::FLOAT as avg_engagement_rate,\n        jsonb_object_agg(\n            cp.platform,\n            jsonb_build_object(\n                'views', pc.total_views,\n                'likes', pc.total_likes,\n                'shares', pc.total_shares,\n                'comments', pc.total_comments\n            )\n        ) as platform_breakdown\n    FROM clip_posts cp\n    INNER JOIN platform_posts pp ON cp.post_id = pp.id\n    LEFT JOIN LATERAL (\n        SELECT \n            MAX(views) as total_views,\n            MAX(likes) as total_likes,\n            MAX(shares) as total_shares,\n            MAX(comments) as total_comments\n        FROM platform_checkbacks\n        WHERE post_id = pp.id\n    ) pc ON true\n    WHERE cp.clip_id = p_clip_id\n    GROUP BY cp.clip_id;\nEND;\n$$ LANGUAGE plpgsql","-- =====================================================\n-- COMMENTS\n-- =====================================================\n\nCOMMENT ON TABLE video_clips IS 'Stores clip configurations extracted from analyzed videos with AI suggestions and platform variants'","COMMENT ON TABLE clip_posts IS 'Junction table linking video clips to platform posts for multi-platform publishing'","COMMENT ON COLUMN video_clips.start_time IS 'Clip start time in seconds from video beginning'","COMMENT ON COLUMN video_clips.end_time IS 'Clip end time in seconds from video beginning'","COMMENT ON COLUMN video_clips.ai_score IS 'AI quality score from 0-1 based on hook quality, engagement, emotion arc, and platform fit'","COMMENT ON COLUMN video_clips.segment_ids IS 'Array of video_segment UUIDs that this clip encompasses'","COMMENT ON COLUMN video_clips.platform_variants IS 'JSONB object containing platform-specific configuration overrides'"}	video_clips
20250121000012	{"-- Analysis Enhancement: Manual Segment Editing\n-- Adds support for manual segment editing, tracking, and validation\n\n-- =====================================================\n-- SEGMENT EDITING ENHANCEMENTS\n-- =====================================================\n\n-- Add columns to track manual edits\nALTER TABLE video_segments \n    ADD COLUMN IF NOT EXISTS is_manual BOOLEAN DEFAULT FALSE,\n    ADD COLUMN IF NOT EXISTS edited_by UUID,\n    ADD COLUMN IF NOT EXISTS edit_reason TEXT,\n    ADD COLUMN IF NOT EXISTS original_segment_id UUID,\n    ADD COLUMN IF NOT EXISTS confidence_score FLOAT CHECK (confidence_score >= 0 AND confidence_score <= 1)","-- Add index for manual segments\nCREATE INDEX IF NOT EXISTS idx_video_segments_is_manual ON video_segments(is_manual) WHERE is_manual = true","-- Add index for edited segments\nCREATE INDEX IF NOT EXISTS idx_video_segments_edited_by ON video_segments(edited_by) WHERE edited_by IS NOT NULL","-- =====================================================\n-- SEGMENT PERFORMANCE TRACKING\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS segment_performance (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    segment_id BIGINT NOT NULL,\n    post_id UUID NOT NULL,\n    \n    -- Metrics at segment timestamps\n    views_at_start INTEGER DEFAULT 0,\n    views_at_end INTEGER DEFAULT 0,\n    retention_rate FLOAT CHECK (retention_rate >= 0 AND retention_rate <= 1),\n    \n    -- Engagement during segment\n    likes_during INTEGER DEFAULT 0,\n    comments_during INTEGER DEFAULT 0,\n    shares_during INTEGER DEFAULT 0,\n    replays_during INTEGER DEFAULT 0,\n    \n    -- Calculated scores\n    engagement_score FLOAT,\n    effectiveness_score FLOAT,\n    \n    -- Metadata\n    measured_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    \n    -- Constraints\n    CONSTRAINT fk_segment FOREIGN KEY (segment_id) REFERENCES video_segments(id) ON DELETE CASCADE,\n    CONSTRAINT fk_post FOREIGN KEY (post_id) REFERENCES platform_posts(id) ON DELETE CASCADE,\n    CONSTRAINT unique_segment_post UNIQUE(segment_id, post_id)\n)","-- Indexes for performance queries\nCREATE INDEX IF NOT EXISTS idx_segment_performance_segment_id ON segment_performance(segment_id)","CREATE INDEX IF NOT EXISTS idx_segment_performance_post_id ON segment_performance(post_id)","CREATE INDEX IF NOT EXISTS idx_segment_performance_engagement_score ON segment_performance(engagement_score DESC NULLS LAST)","CREATE INDEX IF NOT EXISTS idx_segment_performance_effectiveness_score ON segment_performance(effectiveness_score DESC NULLS LAST)","-- =====================================================\n-- SEGMENT EDIT HISTORY\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS segment_edit_history (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    segment_id BIGINT NOT NULL,\n    edited_by UUID NOT NULL,\n    \n    -- What changed\n    edit_type VARCHAR(50) NOT NULL,  -- created, updated, split, merged, deleted\n    field_changes JSONB,  -- Before/after values\n    \n    -- Why it changed\n    edit_reason TEXT,\n    \n    -- When\n    edited_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    \n    -- Constraints\n    CONSTRAINT fk_segment_history FOREIGN KEY (segment_id) REFERENCES video_segments(id) ON DELETE CASCADE,\n    CONSTRAINT valid_edit_type CHECK (edit_type IN ('created', 'updated', 'split', 'merged', 'deleted', 'reclassified'))\n)","CREATE INDEX IF NOT EXISTS idx_segment_edit_history_segment_id ON segment_edit_history(segment_id)","CREATE INDEX IF NOT EXISTS idx_segment_edit_history_edited_by ON segment_edit_history(edited_by)","CREATE INDEX IF NOT EXISTS idx_segment_edit_history_edited_at ON segment_edit_history(edited_at DESC)","-- =====================================================\n-- HELPER FUNCTIONS\n-- =====================================================\n\n-- Function to validate segment timing for a video\nCREATE OR REPLACE FUNCTION validate_video_segments(p_video_id UUID)\nRETURNS TABLE (\n    issue_type VARCHAR,\n    segment_id UUID,\n    details TEXT\n) AS $$\nBEGIN\n    -- Check for overlapping segments\n    RETURN QUERY\n    SELECT \n        'overlap'::VARCHAR as issue_type,\n        s1.id as segment_id,\n        format('Overlaps with segment %s', s2.id) as details\n    FROM video_segments s1\n    INNER JOIN video_segments s2 ON s1.video_id = s2.video_id\n    WHERE s1.video_id = p_video_id\n        AND s1.id < s2.id\n        AND s1.start_time < s2.end_time\n        AND s1.end_time > s2.start_time;\n    \n    -- Check for invalid timing (end before start)\n    RETURN QUERY\n    SELECT \n        'invalid_timing'::VARCHAR,\n        id,\n        'End time is before or equal to start time'\n    FROM video_segments\n    WHERE video_id = p_video_id\n        AND end_time <= start_time;\n    \n    -- Check for segments with zero/negative duration\n    RETURN QUERY\n    SELECT \n        'zero_duration'::VARCHAR,\n        id,\n        format('Duration is %.2f seconds', end_time - start_time)\n    FROM video_segments\n    WHERE video_id = p_video_id\n        AND (end_time - start_time) < 0.1;\nEND;\n$$ LANGUAGE plpgsql","-- Function to find gaps between segments\nCREATE OR REPLACE FUNCTION find_segment_gaps(p_video_id UUID, p_min_gap_seconds FLOAT DEFAULT 1.0)\nRETURNS TABLE (\n    gap_start FLOAT,\n    gap_end FLOAT,\n    gap_duration FLOAT\n) AS $$\nBEGIN\n    RETURN QUERY\n    WITH ordered_segments AS (\n        SELECT \n            start_time,\n            end_time,\n            LEAD(start_time) OVER (ORDER BY start_time) as next_start\n        FROM video_segments\n        WHERE video_id = p_video_id\n        ORDER BY start_time\n    )\n    SELECT \n        end_time as gap_start,\n        next_start as gap_end,\n        next_start - end_time as gap_duration\n    FROM ordered_segments\n    WHERE next_start IS NOT NULL\n        AND (next_start - end_time) >= p_min_gap_seconds;\nEND;\n$$ LANGUAGE plpgsql","-- Function to calculate segment performance score\nCREATE OR REPLACE FUNCTION calculate_segment_performance_score(\n    p_retention_rate FLOAT,\n    p_likes INTEGER,\n    p_comments INTEGER,\n    p_shares INTEGER,\n    p_views INTEGER\n)\nRETURNS FLOAT AS $$\nDECLARE\n    engagement_rate FLOAT;\n    performance_score FLOAT;\nBEGIN\n    -- Calculate engagement rate\n    IF p_views > 0 THEN\n        engagement_rate := (p_likes + p_comments + p_shares)::FLOAT / p_views;\n    ELSE\n        engagement_rate := 0;\n    END IF;\n    \n    -- Weighted score formula\n    -- Retention: 40%, Engagement: 30%, Shares: 20%, Comments: 10%\n    performance_score := \n        (COALESCE(p_retention_rate, 0) * 0.4) +\n        (LEAST(engagement_rate, 0.2) / 0.2 * 0.3) +  -- Cap at 20% engagement\n        (LEAST(p_shares::FLOAT / GREATEST(p_views, 1), 0.05) / 0.05 * 0.2) +  -- Cap at 5% share rate\n        (LEAST(p_comments::FLOAT / GREATEST(p_views, 1), 0.1) / 0.1 * 0.1);  -- Cap at 10% comment rate\n    \n    RETURN LEAST(performance_score, 1.0);  -- Cap at 1.0\nEND;\n$$ LANGUAGE plpgsql","-- Trigger to auto-calculate performance scores\nCREATE OR REPLACE FUNCTION update_segment_performance_scores()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.engagement_score := calculate_segment_performance_score(\n        NEW.retention_rate,\n        NEW.likes_during,\n        NEW.comments_during,\n        NEW.shares_during,\n        NEW.views_at_start\n    );\n    \n    NEW.effectiveness_score := NEW.engagement_score;  -- Can be customized later\n    \n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql","CREATE TRIGGER segment_performance_score_trigger\n    BEFORE INSERT OR UPDATE ON segment_performance\n    FOR EACH ROW\n    EXECUTE FUNCTION update_segment_performance_scores()","-- =====================================================\n-- ROW LEVEL SECURITY\n-- =====================================================\n\n-- Enable RLS on new tables\nALTER TABLE segment_performance ENABLE ROW LEVEL SECURITY","ALTER TABLE segment_edit_history ENABLE ROW LEVEL SECURITY","-- Policies for segment_performance\nCREATE POLICY segment_performance_select_policy ON segment_performance\n    FOR SELECT\n    USING (EXISTS (\n        SELECT 1 FROM video_segments vs\n        INNER JOIN videos v ON vs.video_id = v.id\n        WHERE vs.id = segment_performance.segment_id\n        AND v.user_id = auth.uid()\n    ))","CREATE POLICY segment_performance_insert_policy ON segment_performance\n    FOR INSERT\n    WITH CHECK (EXISTS (\n        SELECT 1 FROM video_segments vs\n        INNER JOIN videos v ON vs.video_id = v.id\n        WHERE vs.id = segment_performance.segment_id\n        AND v.user_id = auth.uid()\n    ))","-- Policies for segment_edit_history\nCREATE POLICY segment_edit_history_select_policy ON segment_edit_history\n    FOR SELECT\n    USING (EXISTS (\n        SELECT 1 FROM video_segments vs\n        INNER JOIN videos v ON vs.video_id = v.id\n        WHERE vs.id = segment_edit_history.segment_id\n        AND v.user_id = auth.uid()\n    ))","CREATE POLICY segment_edit_history_insert_policy ON segment_edit_history\n    FOR INSERT\n    WITH CHECK (edited_by = auth.uid())","-- =====================================================\n-- COMMENTS\n-- =====================================================\n\nCOMMENT ON TABLE segment_performance IS 'Tracks performance metrics for video segments across different platform posts'","COMMENT ON TABLE segment_edit_history IS 'Audit log of all manual edits made to video segments'","COMMENT ON COLUMN video_segments.is_manual IS 'Whether this segment was manually created/edited'","COMMENT ON COLUMN video_segments.edited_by IS 'User ID who made manual edits'","COMMENT ON COLUMN video_segments.confidence_score IS 'AI confidence score for auto-generated segments (0-1)'","COMMENT ON COLUMN segment_performance.retention_rate IS 'Percentage of viewers who watched the entire segment'","COMMENT ON COLUMN segment_performance.effectiveness_score IS 'Overall segment effectiveness score (0-1)'"}	segment_editing
20250121000013	{"-- Publishing Queue System\n-- Supports scheduled multi-platform publishing with priority and retry logic\n\nCREATE TABLE IF NOT EXISTS publishing_queue (\n    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),\n    \n    -- Content references\n    content_item_id UUID,\n    clip_id UUID,\n    \n    -- Scheduling\n    scheduled_for TIMESTAMP WITH TIME ZONE NOT NULL,\n    priority INTEGER DEFAULT 0,  -- Higher = more important\n    \n    -- Status tracking\n    status VARCHAR(50) NOT NULL DEFAULT 'queued',\n    retry_count INTEGER DEFAULT 0,\n    max_retries INTEGER DEFAULT 3,\n    last_error TEXT,\n    \n    -- Platform configuration\n    platform VARCHAR(50) NOT NULL,\n    platform_metadata JSONB DEFAULT '{}',\n    \n    -- Post content\n    caption TEXT,\n    hashtags TEXT[],\n    thumbnail_url VARCHAR(500),\n    video_url VARCHAR(500),\n    \n    -- Publishing results\n    published_at TIMESTAMP WITH TIME ZONE,\n    platform_post_id VARCHAR(255),\n    platform_url VARCHAR(500),\n    \n    -- Timestamps\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    created_by UUID,\n    \n    -- Constraints\n    CONSTRAINT fk_content_item FOREIGN KEY (content_item_id) \n        REFERENCES content_items(id) ON DELETE SET NULL,\n    CONSTRAINT fk_clip FOREIGN KEY (clip_id) \n        REFERENCES video_clips(id) ON DELETE SET NULL,\n    CONSTRAINT valid_status CHECK (status IN ('queued', 'processing', 'published', 'failed', 'cancelled')),\n    CONSTRAINT valid_platform CHECK (platform IN ('tiktok', 'instagram', 'youtube', 'linkedin', 'twitter', 'facebook', 'snapchat', 'threads', 'pinterest'))\n)","-- Indexes for performance\nCREATE INDEX IF NOT EXISTS idx_queue_scheduled_status ON publishing_queue(scheduled_for, status) \n    WHERE status IN ('queued', 'processing')","CREATE INDEX IF NOT EXISTS idx_queue_status ON publishing_queue(status)","CREATE INDEX IF NOT EXISTS idx_queue_priority ON publishing_queue(priority DESC, scheduled_for ASC)\n    WHERE status = 'queued'","CREATE INDEX IF NOT EXISTS idx_queue_platform ON publishing_queue(platform, status)","CREATE INDEX IF NOT EXISTS idx_queue_content_item ON publishing_queue(content_item_id) WHERE content_item_id IS NOT NULL","CREATE INDEX IF NOT EXISTS idx_queue_clip ON publishing_queue(clip_id) WHERE clip_id IS NOT NULL","-- Auto-update timestamp trigger\nCREATE OR REPLACE FUNCTION update_publishing_queue_timestamp()\nRETURNS TRIGGER AS $$\nBEGIN\n    NEW.updated_at = NOW();\n    RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql","CREATE TRIGGER publishing_queue_update_timestamp\n    BEFORE UPDATE ON publishing_queue\n    FOR EACH ROW\n    EXECUTE FUNCTION update_publishing_queue_timestamp()","-- Helper function to get next items from queue\nCREATE OR REPLACE FUNCTION get_next_queue_items(\n    p_limit INTEGER DEFAULT 10,\n    p_platform VARCHAR DEFAULT NULL\n)\nRETURNS TABLE (\n    id UUID,\n    content_item_id UUID,\n    clip_id UUID,\n    platform VARCHAR,\n    scheduled_for TIMESTAMP WITH TIME ZONE,\n    priority INTEGER\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        q.id,\n        q.content_item_id,\n        q.clip_id,\n        q.platform,\n        q.scheduled_for,\n        q.priority\n    FROM publishing_queue q\n    WHERE q.status = 'queued'\n        AND q.scheduled_for <= NOW()\n        AND (p_platform IS NULL OR q.platform = p_platform)\n    ORDER BY q.priority DESC, q.scheduled_for ASC\n    LIMIT p_limit\n    FOR UPDATE SKIP LOCKED;  -- Prevent concurrent processing\nEND;\n$$ LANGUAGE plpgsql","-- Helper function to update queue item status\nCREATE OR REPLACE FUNCTION update_queue_status(\n    p_id UUID,\n    p_status VARCHAR,\n    p_error TEXT DEFAULT NULL,\n    p_platform_post_id VARCHAR DEFAULT NULL,\n    p_platform_url VARCHAR DEFAULT NULL\n)\nRETURNS BOOLEAN AS $$\nBEGIN\n    UPDATE publishing_queue\n    SET status = p_status,\n        last_error = p_error,\n        platform_post_id = p_platform_post_id,\n        platform_url = p_platform_url,\n        published_at = CASE WHEN p_status = 'published' THEN NOW() ELSE published_at END\n    WHERE id = p_id;\n    \n    RETURN FOUND;\nEND;\n$$ LANGUAGE plpgsql","-- Helper function to retry failed items\nCREATE OR REPLACE FUNCTION retry_queue_item(p_id UUID)\nRETURNS BOOLEAN AS $$\nDECLARE\n    current_retry_count INTEGER;\n    max_retry_count INTEGER;\nBEGIN\n    SELECT retry_count, max_retries\n    INTO current_retry_count, max_retry_count\n    FROM publishing_queue\n    WHERE id = p_id;\n    \n    IF current_retry_count < max_retry_count THEN\n        UPDATE publishing_queue\n        SET status = 'queued',\n            retry_count = retry_count + 1,\n            last_error = NULL\n        WHERE id = p_id;\n        RETURN TRUE;\n    ELSE\n        RETURN FALSE;\n    END IF;\nEND;\n$$ LANGUAGE plpgsql","-- Helper function to get queue statistics\nCREATE OR REPLACE FUNCTION get_queue_statistics()\nRETURNS TABLE (\n    status VARCHAR,\n    platform VARCHAR,\n    count BIGINT\n) AS $$\nBEGIN\n    RETURN QUERY\n    SELECT \n        q.status,\n        q.platform,\n        COUNT(*) as count\n    FROM publishing_queue q\n    GROUP BY q.status, q.platform\n    ORDER BY q.status, q.platform;\nEND;\n$$ LANGUAGE plpgsql","-- RLS Policies\nALTER TABLE publishing_queue ENABLE ROW LEVEL SECURITY","CREATE POLICY publishing_queue_select_policy ON publishing_queue\n    FOR SELECT\n    USING (created_by = auth.uid())","CREATE POLICY publishing_queue_insert_policy ON publishing_queue\n    FOR INSERT\n    WITH CHECK (created_by = auth.uid())","CREATE POLICY publishing_queue_update_policy ON publishing_queue\n    FOR UPDATE\n    USING (created_by = auth.uid())","CREATE POLICY publishing_queue_delete_policy ON publishing_queue\n    FOR DELETE\n    USING (created_by = auth.uid())","-- Comments\nCOMMENT ON TABLE publishing_queue IS 'Scheduled publishing queue with priority and retry support'","COMMENT ON COLUMN publishing_queue.priority IS 'Higher values = higher priority (0-100)'","COMMENT ON COLUMN publishing_queue.platform_metadata IS 'Platform-specific configuration (duet settings, visibility, etc.)'","COMMENT ON COLUMN publishing_queue.status IS 'Current status: queued, processing, published, failed, cancelled'"}	publishing_queue
20250122000000	{"-- Fix schema mismatches identified in endpoint testing\n-- Migration: 20250122000000_fix_schema_mismatches\n-- Created: 2025-11-22\n-- Adds missing tables and columns\n\n-- Enable UUID extension if not exists\nCREATE EXTENSION IF NOT EXISTS \\"uuid-ossp\\"","-- =====================================================\n-- 1. Add missing video_metadata column to original_videos\n-- =====================================================\n\n-- Check if column exists and add it if not\nDO $$ \nBEGIN\n    IF NOT EXISTS (\n        SELECT 1 FROM information_schema.columns \n        WHERE table_name = 'original_videos' \n        AND column_name = 'video_metadata'\n    ) THEN\n        ALTER TABLE original_videos \n        ADD COLUMN video_metadata JSONB;\n        \n        RAISE NOTICE 'Added video_metadata column to original_videos';\n    ELSE\n        RAISE NOTICE 'video_metadata column already exists in original_videos';\n    END IF;\nEND $$","-- =====================================================\n-- 2. Create processing_jobs table if not exists\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS processing_jobs (\n    job_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    job_type VARCHAR(100) NOT NULL,\n    \n    entity_id UUID,\n    entity_type VARCHAR(50),\n    \n    status VARCHAR(50) DEFAULT 'queued',\n    progress_percent INTEGER DEFAULT 0,\n    \n    started_at TIMESTAMP WITH TIME ZONE,\n    completed_at TIMESTAMP WITH TIME ZONE,\n    \n    result JSONB,\n    error_message TEXT,\n    \n    retry_count INTEGER DEFAULT 0,\n    max_retries INTEGER DEFAULT 3,\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n)","CREATE INDEX IF NOT EXISTS idx_processing_jobs_status ON processing_jobs(status)","CREATE INDEX IF NOT EXISTS idx_processing_jobs_entity ON processing_jobs(entity_id, entity_type)","CREATE INDEX IF NOT EXISTS idx_processing_jobs_created ON processing_jobs(created_at DESC)","COMMENT ON TABLE processing_jobs IS 'Async processing jobs queue for video analysis and other background tasks'","-- =====================================================\n-- 3. Create scheduled_posts table if not exists\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS scheduled_posts (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    clip_id UUID,\n    content_variant_id UUID,\n    \n    platform VARCHAR(50) NOT NULL,\n    platform_account_id TEXT,\n    \n    scheduled_time TIMESTAMP WITH TIME ZONE NOT NULL,\n    status VARCHAR(50) DEFAULT 'pending',\n    \n    publish_response JSONB,\n    error_message TEXT,\n    platform_post_id TEXT,\n    platform_url TEXT,\n    \n    retry_count INTEGER DEFAULT 0,\n    next_retry_at TIMESTAMP WITH TIME ZONE,\n    last_error TEXT,\n    \n    is_ai_recommended BOOLEAN DEFAULT false,\n    recommendation_score FLOAT,\n    recommendation_reasoning TEXT,\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    published_at TIMESTAMP WITH TIME ZONE\n)","CREATE INDEX IF NOT EXISTS idx_scheduled_posts_status ON scheduled_posts(status)","CREATE INDEX IF NOT EXISTS idx_scheduled_posts_scheduled_time ON scheduled_posts(scheduled_time)","CREATE INDEX IF NOT EXISTS idx_scheduled_posts_platform ON scheduled_posts(platform)","CREATE INDEX IF NOT EXISTS idx_scheduled_posts_clip ON scheduled_posts(clip_id)","COMMENT ON TABLE scheduled_posts IS 'Scheduled posts for content publishing across platforms'","-- =====================================================\n-- 4. Create posting_goals table if not exists\n-- =====================================================\n\nCREATE TABLE IF NOT EXISTS posting_goals (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    user_id UUID NOT NULL,\n    \n    goal_type VARCHAR(100) NOT NULL,\n    goal_name VARCHAR(255) NOT NULL,\n    \n    target_metrics JSONB NOT NULL,\n    \n    priority INTEGER DEFAULT 1,\n    start_date TIMESTAMP WITH TIME ZONE,\n    end_date TIMESTAMP WITH TIME ZONE,\n    \n    status VARCHAR(50) DEFAULT 'active',\n    \n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n)","CREATE INDEX IF NOT EXISTS idx_posting_goals_user ON posting_goals(user_id)","CREATE INDEX IF NOT EXISTS idx_posting_goals_status ON posting_goals(status)","CREATE INDEX IF NOT EXISTS idx_posting_goals_type ON posting_goals(goal_type)","COMMENT ON TABLE posting_goals IS 'Content posting goals and targets for tracking'","-- =====================================================\n-- Success message\n-- =====================================================\n\nDO $$ \nBEGIN\n    RAISE NOTICE 'Schema fixes applied successfully';\n    RAISE NOTICE '- Added video_metadata column to original_videos (if missing)';\n    RAISE NOTICE '- Created processing_jobs table (if not exists)';\n    RAISE NOTICE '- Created scheduled_posts table (if not exists)';\n    RAISE NOTICE '- Created posting_goals table (if not exists)';\nEND $$"}	fix_schema_mismatches
20251123143001	{"-- 01_core_people.sql\n\n-- People: one row per human\ncreate table if not exists people (\n  id uuid primary key default gen_random_uuid(),\n  full_name text,\n  primary_email text,\n  company text,\n  role text,\n  timezone text,\n  created_at timestamptz not null default now()\n)","create index if not exists idx_people_email on people (primary_email)","-- Identities: all known handles/accounts for a person\ncreate table if not exists identities (\n  id bigserial primary key,\n  person_id uuid not null references people(id) on delete cascade,\n  channel text not null check (channel in (\n    'email',\n    'instagram',\n    'facebook',\n    'threads',\n    'twitter',\n    'linkedin',\n    'tiktok',\n    'youtube',\n    'pinterest',\n    'other'\n  )),\n  handle text not null,           -- email, @handle, URL, platform user id\n  extra jsonb,                    -- profile_pic_url, bio, location, etc.\n  is_verified boolean not null default false,\n  created_at timestamptz not null default now()\n)","create unique index if not exists uq_identities_channel_handle\n  on identities (channel, handle)","-- Person events: everything they do with you\ncreate table if not exists person_events (\n  id bigserial primary key,\n  person_id uuid not null references people(id) on delete cascade,\n  channel text not null check (channel in (\n    'email',\n    'instagram',\n    'facebook',\n    'threads',\n    'twitter',\n    'linkedin',\n    'tiktok',\n    'youtube',\n    'website',\n    'other'\n  )),\n  event_type text not null,       -- e.g. opened_email, clicked_link, commented, liked, dm_reply\n  traffic_type text not null check (traffic_type in ('organic','paid')),\n  platform_id text,               -- platform-specific id (post id, email id, message id)\n  content_excerpt text,\n  sentiment numeric,              -- -1..1\n  metadata jsonb,                 -- raw event info or extra fields\n  occurred_at timestamptz not null,\n  created_at timestamptz not null default now()\n)","create index if not exists idx_person_events_person_time\n  on person_events (person_id, occurred_at desc)","create index if not exists idx_person_events_channel_type\n  on person_events (channel, event_type)"}	core_people
20251123143002	{"-- 02_insights_segments.sql\n\n-- Cached per-person lens\ncreate table if not exists person_insights (\n  person_id uuid primary key references people(id) on delete cascade,\n\n  interests jsonb,                -- [\\"AI automation\\",\\"3D printing\\",...]\n  tone_preferences jsonb,         -- [\\"casual\\",\\"practical\\"]\n  channel_preferences jsonb,      -- {\\"email\\":0.9,\\"instagram_dm\\":0.7,\\"linkedin\\":0.4}\n  activity_state text check (activity_state in ('active','warming','cool','dormant')),\n  last_active_at timestamptz,\n  seasonality jsonb,              -- histograms by day/hour/month\n\n  warmth_score numeric,           -- 0..1 or 0..100\n  last_sentiment numeric,         -- -1..1 aggregate\n\n  updated_at timestamptz not null default now()\n)","-- Segments: named buckets of people (dynamic or materialized)\ncreate table if not exists segments (\n  id uuid primary key default gen_random_uuid(),\n  name text not null,\n  description text,\n  definition jsonb,               -- DSL / query definition (optional)\n  is_dynamic boolean not null default false,\n  created_by uuid,                -- user id (if needed)\n  created_at timestamptz not null default now()\n)","-- Segment members: materialized membership\ncreate table if not exists segment_members (\n  segment_id uuid not null references segments(id) on delete cascade,\n  person_id uuid not null references people(id) on delete cascade,\n  added_at timestamptz not null default now(),\n  primary key (segment_id, person_id)\n)","create index if not exists idx_segment_members_person\n  on segment_members (person_id)","-- Segment-level insights, split by organic/paid\ncreate table if not exists segment_insights (\n  segment_id uuid not null references segments(id) on delete cascade,\n  traffic_type text not null check (traffic_type in ('organic','paid')),\n\n  top_topics jsonb,               -- [\\"AI automation\\",\\"copywriting\\",...]\n  top_platforms jsonb,            -- {\\"instagram\\":0.7,\\"twitter\\":0.2,\\"linkedin\\":0.1}\n  top_formats jsonb,              -- {\\"reels\\":0.6,\\"carousels\\":0.3,\\"threads\\":0.1}\n  engagement_style jsonb,         -- {\\"saves\\":0.5,\\"comments\\":0.3,\\"shares\\":0.2}\n  best_times jsonb,               -- {\\"Tue_11_14\\":0.8,...}\n  expected_reach_range int4range,\n  expected_engagement_rate_range numrange,\n\n  updated_at timestamptz not null default now(),\n  primary key (segment_id, traffic_type)\n)","-- Outbound messages (email, DM, etc.)\ncreate table if not exists outbound_messages (\n  id uuid primary key default gen_random_uuid(),\n  person_id uuid not null references people(id) on delete cascade,\n  segment_id uuid references segments(id) on delete set null,\n  channel text not null check (channel in ('email','instagram_dm','facebook_dm','linkedin_dm','twitter_dm','other')),\n  goal_type text,                 -- invite_to_offer / nurture / reactivation / etc.\n  variant text,                   -- A/B variant label\n  subject text,\n  body text not null,\n  metadata jsonb,\n\n  sent_at timestamptz,\n  delivered_at timestamptz,\n  failed_at timestamptz,\n  failure_reason text,\n\n  created_at timestamptz not null default now()\n)","create index if not exists idx_outbound_messages_person\n  on outbound_messages (person_id, sent_at desc)"}	insights_segments
20251123143003	{"-- 03_content_core.sql\n\n-- Canonical content item (global content ID)\ncreate table if not exists content_items (\n  id uuid primary key default gen_random_uuid(),\n  slug text unique,\n  type text not null check (type in ('video','article','audio','image','carousel','other')),\n  source_url text,                -- your local/private URL or storage path\n  title text,\n  description text,\n  created_by uuid,                -- user id\n  created_at timestamptz not null default now()\n)","-- Platform-specific variants\ncreate table if not exists content_variants (\n  id uuid primary key default gen_random_uuid(),\n  content_id uuid not null references content_items(id) on delete cascade,\n\n  platform text not null check (platform in (\n    'instagram',\n    'facebook',\n    'threads',\n    'tiktok',\n    'youtube',\n    'twitter',\n    'linkedin',\n    'pinterest',\n    'other'\n  )),\n\n  platform_post_id text,          -- platform or Blotato post id\n  platform_post_url text,         -- live URL to the post\n  title text,\n  description text,\n  thumbnail_url text,\n\n  is_paid boolean not null default false,    -- ad vs organic\n  experiment_id uuid,                        -- references content_experiments (defined later)\n  variant_label text,                        -- e.g. \\"Title A / Thumb 1\\"\n\n  scheduled_at timestamptz,\n  published_at timestamptz,\n\n  created_at timestamptz not null default now()\n)","create index if not exists idx_content_variants_content_platform\n  on content_variants (content_id, platform)","create index if not exists idx_content_variants_platform_post\n  on content_variants (platform, platform_post_id)"}	content_core
20251123143004	{"-- 04_content_metrics_experiments.sql\n\n-- Metrics snapshots per variant\ncreate table if not exists content_metrics (\n  id bigserial primary key,\n  variant_id uuid not null references content_variants(id) on delete cascade,\n  snapshot_at timestamptz not null,\n\n  traffic_type text not null check (traffic_type in ('organic','paid')),\n\n  views bigint,\n  impressions bigint,\n  reach bigint,\n  likes bigint,\n  comments bigint,\n  shares bigint,\n  saves bigint,\n  clicks bigint,\n  watch_time_seconds bigint,\n\n  sentiment_score numeric,        -- -1..1 avg sentiment at this snapshot\n  metadata jsonb,\n\n  created_at timestamptz not null default now()\n)","create index if not exists idx_content_metrics_variant_time\n  on content_metrics (variant_id, snapshot_at desc)","-- Rollups per canonical content item (aggregated periodically)\ncreate table if not exists content_rollups (\n  content_id uuid primary key references content_items(id) on delete cascade,\n\n  total_views_organic bigint,\n  total_views_paid bigint,\n  total_impressions_organic bigint,\n  total_impressions_paid bigint,\n  total_likes_organic bigint,\n  total_likes_paid bigint,\n  total_comments_organic bigint,\n  total_comments_paid bigint,\n  total_shares_organic bigint,\n  total_shares_paid bigint,\n  total_saves_organic bigint,\n  total_saves_paid bigint,\n  total_clicks_organic bigint,\n  total_clicks_paid bigint,\n\n  avg_watch_time_seconds_organic numeric,\n  avg_watch_time_seconds_paid numeric,\n\n  global_sentiment numeric,       -- overall weighted sentiment\n  best_platform text,             -- computed from your scoring logic\n\n  last_updated_at timestamptz not null default now()\n)","-- Cross-platform experiments (A/B / APINK)\ncreate table if not exists content_experiments (\n  id uuid primary key default gen_random_uuid(),\n  content_id uuid not null references content_items(id) on delete cascade,\n  name text not null,\n  hypothesis text,\n  primary_metric text,            -- \\"click_through_rate\\", \\"watch_time\\", etc.\n  created_by uuid,\n  created_at timestamptz not null default now()\n)","create index if not exists idx_content_experiments_content\n  on content_experiments (content_id)"}	content_metrics
20251123160000	{"-- Update content_cross_platform_summary view to include total_views\n\nDROP VIEW IF EXISTS content_cross_platform_summary","CREATE OR REPLACE VIEW content_cross_platform_summary AS\nSELECT\n    ci.id AS content_id,\n    ci.title,\n    ci.description,\n    ci.slug,\n    ci.created_at,\n    ci.updated_at,\n    -- Aggregates from rollups\n    COALESCE(cr.total_views, 0) AS total_views,\n    COALESCE(cr.total_likes, 0) AS total_likes,\n    COALESCE(cr.total_comments, 0) AS total_comments,\n    COALESCE(cr.total_shares, 0) AS total_shares,\n    COALESCE(cr.total_saves, 0) AS total_saves,\n    cr.best_platform,\n    -- Platform count and list\n    (SELECT COUNT(DISTINCT platform) FROM content_variants cv WHERE cv.content_id = ci.id) AS platform_count,\n    (SELECT ARRAY_AGG(DISTINCT platform) FROM content_variants cv WHERE cv.content_id = ci.id) AS platforms\nFROM content_items ci\nLEFT JOIN content_rollups cr ON ci.id = cr.content_id"}	update_content_summary_view
20251123170000	{"-- Add is_dynamic column to segments table if it doesn't exist\n\nDO $$\nBEGIN\n    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'segments' AND column_name = 'is_dynamic') THEN\n        ALTER TABLE segments ADD COLUMN is_dynamic boolean NOT NULL DEFAULT false;\n    END IF;\nEND $$"}	add_is_dynamic_to_segments
20251125000000	{"-- 20251125000000_workspace_architecture.sql\n\n-- 1. Create workspaces table\nCREATE TABLE IF NOT EXISTS workspaces (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  name TEXT NOT NULL,\n  slug TEXT UNIQUE NOT NULL,\n  description TEXT,\n  settings JSONB DEFAULT '{}'::jsonb,\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  updated_at TIMESTAMPTZ DEFAULT NOW(),\n  deleted_at TIMESTAMPTZ\n)","CREATE INDEX IF NOT EXISTS idx_workspaces_slug ON workspaces(slug)","CREATE INDEX IF NOT EXISTS idx_workspaces_deleted ON workspaces(deleted_at) WHERE deleted_at IS NULL","-- 2. Create workspace_members table\nCREATE TABLE IF NOT EXISTS workspace_members (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL,  -- References auth.users\n  role TEXT NOT NULL CHECK (role IN ('owner', 'admin', 'member', 'viewer')),\n  invited_by UUID,\n  joined_at TIMESTAMPTZ DEFAULT NOW(),\n  created_at TIMESTAMPTZ DEFAULT NOW(),\n  UNIQUE(workspace_id, user_id)\n)","CREATE INDEX IF NOT EXISTS idx_workspace_members_user ON workspace_members(user_id)","CREATE INDEX IF NOT EXISTS idx_workspace_members_workspace ON workspace_members(workspace_id)","-- 3. Create Default Workspace for migration\nINSERT INTO workspaces (id, name, slug, description)\nVALUES (\n  '00000000-0000-0000-0000-000000000001',\n  'Default Workspace',\n  'default',\n  'Auto-created workspace for existing data'\n) ON CONFLICT (id) DO NOTHING","-- 4. Add workspace_id to core tables (Nullable first, then backfill, then NOT NULL)\n\n-- Helper macro-like function to add workspace_id safely\nDO $$\nDECLARE\n    default_workspace_id UUID := '00000000-0000-0000-0000-000000000001';\n    tables TEXT[] := ARRAY[\n        'people', \n        'segments', \n        'content_items', \n        'analyzed_videos', \n        'original_videos', \n        'ig_connections', \n        'connector_configs'\n    ];\n    t TEXT;\nBEGIN\n    FOREACH t IN ARRAY tables LOOP\n        -- Add column if not exists\n        IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = t AND column_name = 'workspace_id') THEN\n            EXECUTE format('ALTER TABLE %I ADD COLUMN workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE', t);\n            \n            -- Backfill existing data\n            EXECUTE format('UPDATE %I SET workspace_id = %L WHERE workspace_id IS NULL', t, default_workspace_id);\n            \n            -- Make NOT NULL\n            EXECUTE format('ALTER TABLE %I ALTER COLUMN workspace_id SET NOT NULL', t);\n            \n            -- Add Index\n            EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%I_workspace ON %I(workspace_id)', t, t);\n        END IF;\n    END LOOP;\nEND $$","-- 5. Enable RLS on new tables\nALTER TABLE workspaces ENABLE ROW LEVEL SECURITY","ALTER TABLE workspace_members ENABLE ROW LEVEL SECURITY","-- 6. Helper Functions for RLS\n\n-- Get current user's ID (safe wrapper)\nCREATE OR REPLACE FUNCTION public.safe_user_id()\nRETURNS UUID AS $$\n  SELECT NULLIF(current_setting('request.jwt.claims', true)::json->>'sub', '')::uuid;\n$$ LANGUAGE SQL STABLE","-- Get user's workspaces\nCREATE OR REPLACE FUNCTION user_workspaces()\nRETURNS SETOF UUID AS $$\n  SELECT workspace_id FROM workspace_members\n  WHERE user_id = public.safe_user_id();\n$$ LANGUAGE SQL STABLE SECURITY DEFINER","-- 7. RLS Policies\n\n-- Workspaces\nDROP POLICY IF EXISTS \\"Users can view their workspaces\\" ON workspaces","CREATE POLICY \\"Users can view their workspaces\\"\n  ON workspaces FOR SELECT\n  TO authenticated\n  USING (id IN (SELECT user_workspaces()))","DROP POLICY IF EXISTS \\"Users can create workspaces\\" ON workspaces","CREATE POLICY \\"Users can create workspaces\\"\n  ON workspaces FOR INSERT\n  TO authenticated\n  WITH CHECK (true)","-- Workspace Members\nDROP POLICY IF EXISTS \\"Users can view workspace members in their workspaces\\" ON workspace_members","CREATE POLICY \\"Users can view workspace members in their workspaces\\"\n  ON workspace_members FOR SELECT\n  TO authenticated\n  USING (workspace_id IN (SELECT user_workspaces()))","-- Update Core Table Policies (Example: People)\n-- Note: We need to drop the old \\"allow all\\" policies first\nDROP POLICY IF EXISTS \\"Allow all access for authenticated users\\" ON people","CREATE POLICY \\"Users can view people in their workspaces\\"\n  ON people FOR SELECT\n  TO authenticated\n  USING (workspace_id IN (SELECT user_workspaces()))","CREATE POLICY \\"Users can insert people in their workspaces\\"\n  ON people FOR INSERT\n  TO authenticated\n  WITH CHECK (workspace_id IN (SELECT user_workspaces()))","CREATE POLICY \\"Users can update people in their workspaces\\"\n  ON people FOR UPDATE\n  TO authenticated\n  USING (workspace_id IN (SELECT user_workspaces()))\n  WITH CHECK (workspace_id IN (SELECT user_workspaces()))","CREATE POLICY \\"Users can delete people in their workspaces\\"\n  ON people FOR DELETE\n  TO authenticated\n  USING (workspace_id IN (SELECT user_workspaces()))","-- Repeat for other tables (simplified for this migration script, ideally done per table)\n-- For now, we'll apply the same pattern to content_items as a critical example\nDROP POLICY IF EXISTS \\"Allow all access for authenticated users\\" ON content_items","CREATE POLICY \\"Users can view content_items in their workspaces\\"\n  ON content_items FOR SELECT\n  TO authenticated\n  USING (workspace_id IN (SELECT user_workspaces()))","CREATE POLICY \\"Users can insert content_items in their workspaces\\"\n  ON content_items FOR INSERT\n  TO authenticated\n  WITH CHECK (workspace_id IN (SELECT user_workspaces()))","CREATE POLICY \\"Users can update content_items in their workspaces\\"\n  ON content_items FOR UPDATE\n  TO authenticated\n  USING (workspace_id IN (SELECT user_workspaces()))\n  WITH CHECK (workspace_id IN (SELECT user_workspaces()))","CREATE POLICY \\"Users can delete content_items in their workspaces\\"\n  ON content_items FOR DELETE\n  TO authenticated\n  USING (workspace_id IN (SELECT user_workspaces()))"}	workspace_architecture
20251125100000	{"-- Social Accounts Table\n-- Core table for tracking connected social media accounts\n\nCREATE TABLE IF NOT EXISTS social_accounts (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    \n    -- Account Info\n    platform VARCHAR(50) NOT NULL CHECK (platform IN (\n        'tiktok', 'instagram', 'youtube', 'twitter', 'facebook',\n        'pinterest', 'bluesky', 'threads', 'linkedin'\n    )),\n    handle VARCHAR(255) NOT NULL,\n    display_name VARCHAR(255),\n    profile_url TEXT,\n    avatar_url TEXT,\n    \n    -- Account Status\n    status VARCHAR(50) DEFAULT 'active' CHECK (status IN (\n        'active', 'inactive', 'pending', 'error', 'disconnected'\n    )),\n    \n    -- OAuth/Connection Info\n    access_token TEXT,\n    refresh_token TEXT,\n    token_expires_at TIMESTAMPTZ,\n    external_id VARCHAR(255),\n    \n    -- Ownership\n    user_id UUID,\n    workspace_id UUID REFERENCES workspaces(id) ON DELETE CASCADE,\n    \n    -- Timestamps\n    connected_at TIMESTAMPTZ DEFAULT NOW(),\n    last_synced_at TIMESTAMPTZ,\n    created_at TIMESTAMPTZ DEFAULT NOW(),\n    updated_at TIMESTAMPTZ DEFAULT NOW(),\n    \n    UNIQUE(platform, handle)\n)","CREATE INDEX IF NOT EXISTS idx_social_accounts_platform ON social_accounts(platform)","CREATE INDEX IF NOT EXISTS idx_social_accounts_user ON social_accounts(user_id)","CREATE INDEX IF NOT EXISTS idx_social_accounts_workspace ON social_accounts(workspace_id)","CREATE INDEX IF NOT EXISTS idx_social_accounts_status ON social_accounts(status)","-- Enable RLS\nALTER TABLE social_accounts ENABLE ROW LEVEL SECURITY","COMMENT ON TABLE social_accounts IS 'Connected social media accounts for analytics and publishing'"}	social_accounts
20251126000000	{"-- ============================================================================\n-- SOCIAL MEDIA ANALYTICS EXTENSION\n-- Extends existing social_accounts table with comprehensive analytics tracking\n-- For all 9 platforms: TikTok, Instagram, YouTube, Twitter, Facebook,\n-- Pinterest, Bluesky, Threads, LinkedIn\n-- ============================================================================\n\n-- ============================================================================\n-- ANALYTICS MONITORING CONFIG\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS social_analytics_config (\n    id SERIAL PRIMARY KEY,\n    social_account_id UUID NOT NULL REFERENCES social_accounts(id) ON DELETE CASCADE,\n    \n    -- Monitoring Settings\n    monitoring_enabled BOOLEAN DEFAULT TRUE,\n    fetch_frequency INTERVAL DEFAULT '24 hours',\n    last_fetched_at TIMESTAMP,\n    next_fetch_at TIMESTAMP,\n    \n    -- What to Track\n    track_posts BOOLEAN DEFAULT TRUE,\n    track_comments BOOLEAN DEFAULT FALSE,\n    track_demographics BOOLEAN DEFAULT FALSE,\n    posts_per_fetch INTEGER DEFAULT 50,\n    \n    -- API Provider\n    provider_name VARCHAR(100), -- 'rapidapi_tiktok', 'graph_api', etc.\n    provider_config JSONB,\n    \n    created_at TIMESTAMP DEFAULT NOW(),\n    updated_at TIMESTAMP DEFAULT NOW(),\n    \n    UNIQUE(social_account_id)\n)","COMMENT ON TABLE social_analytics_config IS 'Configuration for analytics monitoring per social account'","-- ============================================================================\n-- DAILY ANALYTICS SNAPSHOTS\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS social_analytics_snapshots (\n    id SERIAL PRIMARY KEY,\n    social_account_id UUID NOT NULL REFERENCES social_accounts(id) ON DELETE CASCADE,\n    snapshot_date DATE NOT NULL,\n    \n    -- Core Metrics (Universal)\n    followers_count INTEGER DEFAULT 0,\n    following_count INTEGER DEFAULT 0,\n    posts_count INTEGER DEFAULT 0,\n    \n    -- Engagement Totals\n    total_likes BIGINT DEFAULT 0,\n    total_comments BIGINT DEFAULT 0,\n    total_views BIGINT DEFAULT 0,\n    total_shares BIGINT DEFAULT 0,\n    total_saves BIGINT DEFAULT 0,\n    total_impressions BIGINT DEFAULT 0,\n    \n    -- Platform-Specific Metrics  \n    subscribers_count INTEGER DEFAULT 0, -- YouTube\n    pins_count INTEGER DEFAULT 0, -- Pinterest\n    boards_count INTEGER DEFAULT 0, -- Pinterest\n    retweets_count BIGINT DEFAULT 0, -- Twitter/X\n    reactions_count BIGINT DEFAULT 0, -- Facebook\n    watch_time_minutes BIGINT DEFAULT 0, -- YouTube\n    \n    -- Calculated Metrics\n    engagement_rate DECIMAL(5,2) DEFAULT 0,\n    avg_likes_per_post DECIMAL(10,2) DEFAULT 0,\n    avg_comments_per_post DECIMAL(10,2) DEFAULT 0,\n    avg_views_per_post DECIMAL(10,2) DEFAULT 0,\n    \n    -- Growth (vs previous day)\n    follower_growth INTEGER DEFAULT 0,\n    engagement_growth DECIMAL(10,2) DEFAULT 0,\n    \n    -- Reach\n    reach INTEGER DEFAULT 0,\n    profile_visits INTEGER DEFAULT 0,\n    \n    -- Metadata\n    data_source VARCHAR(50),\n    raw_response JSONB,\n    created_at TIMESTAMP DEFAULT NOW(),\n    \n    UNIQUE(social_account_id, snapshot_date)\n)","CREATE INDEX idx_analytics_snapshots_account ON social_analytics_snapshots(social_account_id)","CREATE INDEX idx_analytics_snapshots_date ON social_analytics_snapshots(snapshot_date DESC)","COMMENT ON TABLE social_analytics_snapshots IS 'Daily snapshots of account-level metrics across all platforms'","-- ============================================================================\n-- SOCIAL POSTS (Extended from platform_posts)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS social_posts_analytics (\n    id SERIAL PRIMARY KEY,\n    social_account_id UUID NOT NULL REFERENCES social_accounts(id) ON DELETE CASCADE,\n    \n    -- Post Identifiers\n    external_post_id VARCHAR(255) NOT NULL,\n    platform VARCHAR(50) NOT NULL,\n    post_url TEXT NOT NULL,\n    short_code VARCHAR(100),\n    \n    -- Content\n    caption TEXT,\n    title VARCHAR(500),\n    description TEXT,\n    \n    -- Media\n    media_type VARCHAR(50), -- 'video','image','carousel','story','reel','short'\n    media_count INTEGER DEFAULT 1,\n    thumbnail_url TEXT,\n    media_url TEXT,\n    media_urls JSONB,\n    \n    -- Video Details\n    duration INTEGER,\n    is_short_form BOOLEAN DEFAULT FALSE,\n    has_audio BOOLEAN DEFAULT TRUE,\n    \n    -- Status\n    is_pinned BOOLEAN DEFAULT FALSE,\n    is_ad BOOLEAN DEFAULT FALSE,\n    visibility VARCHAR(50) DEFAULT 'public',\n    \n    -- Location\n    location_name VARCHAR(255),\n    \n    -- Timestamps\n    posted_at TIMESTAMP,\n    created_at TIMESTAMP DEFAULT NOW(),\n    updated_at TIMESTAMP DEFAULT NOW(),\n    deleted_at TIMESTAMP,\n    \n    -- Link to Internal Content\n    video_id UUID, -- Link to videos table\n    clip_id UUID, -- Link to clips table\n    \n    -- Full API Response\n    raw_data JSONB,\n    \n    UNIQUE(platform, external_post_id)\n)","CREATE INDEX idx_social_posts_account ON social_posts_analytics(social_account_id)","CREATE INDEX idx_social_posts_url ON social_posts_analytics(post_url)","CREATE INDEX idx_social_posts_posted_at ON social_posts_analytics(posted_at DESC)","CREATE INDEX idx_social_posts_video ON social_posts_analytics(video_id) WHERE video_id IS NOT NULL","CREATE INDEX idx_social_posts_clip ON social_posts_analytics(clip_id) WHERE clip_id IS NOT NULL","COMMENT ON TABLE social_posts_analytics IS 'Social media posts tracked for analytics (separate from publishing queue)'","-- ============================================================================\n-- POST PERFORMANCE METRICS (Historical Tracking)\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS social_post_metrics (\n    id SERIAL PRIMARY KEY,\n    post_id INTEGER NOT NULL REFERENCES social_posts_analytics(id) ON DELETE CASCADE,\n    snapshot_date DATE NOT NULL,\n    snapshot_hour INTEGER, -- For intraday tracking\n    \n    -- Core Engagement\n    likes_count BIGINT DEFAULT 0,\n    comments_count BIGINT DEFAULT 0,\n    views_count BIGINT DEFAULT 0,\n    shares_count BIGINT DEFAULT 0,\n    saves_count BIGINT DEFAULT 0,\n    \n    -- Platform-Specific\n    retweets_count BIGINT DEFAULT 0,\n    quote_tweets_count BIGINT DEFAULT 0,\n    reactions_count BIGINT DEFAULT 0,\n    repins_count BIGINT DEFAULT 0,\n    \n    -- Reach & Impressions\n    impressions BIGINT DEFAULT 0,\n    reach BIGINT DEFAULT 0,\n    unique_viewers BIGINT DEFAULT 0,\n    \n    -- Video Metrics\n    watch_time_seconds BIGINT DEFAULT 0,\n    avg_watch_percentage DECIMAL(5,2) DEFAULT 0,\n    completion_rate DECIMAL(5,2) DEFAULT 0,\n    \n    -- Audience Actions\n    profile_visits BIGINT DEFAULT 0,\n    follows_from_post BIGINT DEFAULT 0,\n    link_clicks BIGINT DEFAULT 0,\n    \n    -- Calculated\n    engagement_rate DECIMAL(5,2) DEFAULT 0,\n    viral_score DECIMAL(10,2) DEFAULT 0,\n    \n    created_at TIMESTAMP DEFAULT NOW(),\n    \n    UNIQUE(post_id, snapshot_date, snapshot_hour)\n)","CREATE INDEX idx_post_metrics_post ON social_post_metrics(post_id)","CREATE INDEX idx_post_metrics_date ON social_post_metrics(snapshot_date DESC)","CREATE INDEX idx_post_metrics_views ON social_post_metrics(views_count DESC)","COMMENT ON TABLE social_post_metrics IS 'Historical performance data for social posts with hourly granularity'","-- ============================================================================\n-- HASHTAGS\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS social_hashtags (\n    id SERIAL PRIMARY KEY,\n    hashtag VARCHAR(255) NOT NULL UNIQUE,\n    total_uses BIGINT DEFAULT 0,\n    total_views BIGINT DEFAULT 0,\n    avg_engagement_rate DECIMAL(5,2) DEFAULT 0,\n    created_at TIMESTAMP DEFAULT NOW(),\n    updated_at TIMESTAMP DEFAULT NOW()\n)","CREATE TABLE IF NOT EXISTS social_post_hashtags (\n    post_id INTEGER NOT NULL REFERENCES social_posts_analytics(id) ON DELETE CASCADE,\n    hashtag_id INTEGER NOT NULL REFERENCES social_hashtags(id) ON DELETE CASCADE,\n    position INTEGER,\n    PRIMARY KEY (post_id, hashtag_id)\n)","-- ============================================================================\n-- COMMENTS\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS social_comments (\n    id SERIAL PRIMARY KEY,\n    post_id INTEGER NOT NULL REFERENCES social_posts_analytics(id) ON DELETE CASCADE,\n    platform VARCHAR(50) NOT NULL,\n    external_comment_id VARCHAR(255) NOT NULL,\n    \n    comment_text TEXT,\n    author_username VARCHAR(255),\n    author_id VARCHAR(255),\n    \n    parent_comment_id INTEGER REFERENCES social_comments(id),\n    is_reply BOOLEAN DEFAULT FALSE,\n    \n    likes_count INTEGER DEFAULT 0,\n    is_creator_reply BOOLEAN DEFAULT FALSE,\n    \n    sentiment VARCHAR(20),\n    sentiment_score DECIMAL(3,2),\n    \n    commented_at TIMESTAMP,\n    created_at TIMESTAMP DEFAULT NOW(),\n    \n    UNIQUE(platform, external_comment_id)\n)","CREATE INDEX idx_social_comments_post ON social_comments(post_id)","CREATE INDEX idx_social_comments_creator ON social_comments(is_creator_reply) WHERE is_creator_reply = TRUE","-- ============================================================================\n-- AUDIENCE DEMOGRAPHICS\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS social_audience_demographics (\n    id SERIAL PRIMARY KEY,\n    social_account_id UUID NOT NULL REFERENCES social_accounts(id) ON DELETE CASCADE,\n    snapshot_date DATE NOT NULL,\n    \n    -- Age Groups (percentages)\n    age_13_17 DECIMAL(5,2) DEFAULT 0,\n    age_18_24 DECIMAL(5,2) DEFAULT 0,\n    age_25_34 DECIMAL(5,2) DEFAULT 0,\n    age_35_44 DECIMAL(5,2) DEFAULT 0,\n    age_45_plus DECIMAL(5,2) DEFAULT 0,\n    \n    -- Gender (percentages)\n    gender_male DECIMAL(5,2) DEFAULT 0,\n    gender_female DECIMAL(5,2) DEFAULT 0,\n    gender_other DECIMAL(5,2) DEFAULT 0,\n    \n    -- Top Locations\n    top_countries JSONB,\n    top_cities JSONB,\n    top_languages JSONB,\n    \n    -- Activity Patterns\n    peak_hours JSONB,\n    peak_days JSONB,\n    \n    created_at TIMESTAMP DEFAULT NOW(),\n    \n    UNIQUE(social_account_id, snapshot_date)\n)","-- ============================================================================\n-- API USAGE TRACKING\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS social_api_usage (\n    id SERIAL PRIMARY KEY,\n    provider_name VARCHAR(100) NOT NULL,\n    platform VARCHAR(50) NOT NULL,\n    endpoint VARCHAR(255) NOT NULL,\n    \n    request_count INTEGER DEFAULT 1,\n    success BOOLEAN DEFAULT TRUE,\n    latency_ms INTEGER,\n    error_message TEXT,\n    \n    date DATE DEFAULT CURRENT_DATE,\n    requested_at TIMESTAMP DEFAULT NOW()\n)","CREATE INDEX idx_social_api_usage_date ON social_api_usage(date, provider_name)","-- ============================================================================\n-- FETCH JOBS\n-- ============================================================================\n\nCREATE TABLE IF NOT EXISTS social_fetch_jobs (\n    id SERIAL PRIMARY KEY,\n    social_account_id UUID NOT NULL REFERENCES social_accounts(id) ON DELETE CASCADE,\n    \n    job_type VARCHAR(50) NOT NULL,\n    status VARCHAR(50) DEFAULT 'pending',\n    \n    started_at TIMESTAMP,\n    completed_at TIMESTAMP,\n    \n    posts_fetched INTEGER DEFAULT 0,\n    comments_fetched INTEGER DEFAULT 0,\n    error_message TEXT,\n    \n    created_at TIMESTAMP DEFAULT NOW()\n)","CREATE INDEX idx_social_fetch_jobs_account ON social_fetch_jobs(social_account_id)","CREATE INDEX idx_social_fetch_jobs_status ON social_fetch_jobs(status)","-- ============================================================================\n-- VIEWS\n-- ============================================================================\n\nCREATE OR REPLACE VIEW social_analytics_latest AS\nSELECT \n    sa.id,\n    sa.handle AS username,\n    sa.platform,\n    sa.display_name,\n    sa.status AS account_status,\n    sas.snapshot_date AS last_snapshot_date,\n    sas.followers_count,\n    sas.following_count,\n    sas.posts_count,\n    sas.total_views,\n    sas.total_likes,\n    sas.total_comments,\n    sas.engagement_rate,\n    sas.follower_growth,\n    sac.monitoring_enabled,\n    sac.last_fetched_at\nFROM social_accounts sa\nLEFT JOIN social_analytics_config sac ON sa.id = sac.social_account_id\nLEFT JOIN LATERAL (\n    SELECT * FROM social_analytics_snapshots\n    WHERE social_account_id = sa.id\n    ORDER BY snapshot_date DESC\n    LIMIT 1\n) sas ON TRUE","CREATE OR REPLACE VIEW social_post_performance AS\nSELECT \n    p.id,\n    p.platform,\n    p.post_url,\n    p.caption,\n    p.media_type,\n    p.posted_at,\n    m.views_count AS current_views,\n    m.likes_count AS current_likes,\n    m.comments_count AS current_comments,\n    m.engagement_rate,\n    m.snapshot_date AS last_updated,\n    sa.handle AS account_username\nFROM social_posts_analytics p\nJOIN social_accounts sa ON p.social_account_id = sa.id\nLEFT JOIN LATERAL (\n    SELECT * FROM social_post_metrics\n    WHERE post_id = p.id\n    ORDER BY snapshot_date DESC, snapshot_hour DESC NULLS LAST\n    LIMIT 1\n) m ON TRUE\nWHERE p.deleted_at IS NULL","-- ============================================================================\n-- SUCCESS MESSAGE\n-- ============================================================================\n\nDO $$ \nBEGIN\n    RAISE NOTICE '✅ Social Media Analytics Extension Created!';\n    RAISE NOTICE '📊 Tables: 12 analytics tables created';\n    RAISE NOTICE '🔗 Integrated with existing social_accounts table';\n    RAISE NOTICE '🎯 Ready for all 9 platforms';\nEND $$"}	social_analytics_extension
20251224173425	{"-- Add source column to scheduled_posts to track where post was created from -- Values: 'manual', 'narrative_builder', 'automation', 'experiments'  -- Add source column if it doesn't exist ALTER TABLE scheduled_posts ADD COLUMN IF NOT EXISTS source TEXT DEFAULT 'manual';  -- Add index for filtering by source CREATE INDEX IF NOT EXISTS idx_scheduled_posts_source ON scheduled_posts(source);  -- Add comment for documentation COMMENT ON COLUMN scheduled_posts.source IS 'Source of the scheduled post: manual, narrative_builder, automation, experiments';"}	add_source_to_scheduled_posts
20251224175148	{"-- Add missing file_size column to videos table ALTER TABLE videos ADD COLUMN IF NOT EXISTS file_size BIGINT; COMMENT ON COLUMN videos.file_size IS 'File size in bytes';"}	add_videos_file_size
20251224175151	{"-- Posted Content Tracking Table CREATE TABLE IF NOT EXISTS posted_content (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     platform TEXT NOT NULL,     platform_post_id TEXT,     platform_url TEXT,     account_id TEXT,     account_username TEXT,     media_id UUID,     caption TEXT,     hashtags TEXT[],     views INTEGER DEFAULT 0,     likes INTEGER DEFAULT 0,     comments INTEGER DEFAULT 0,     shares INTEGER DEFAULT 0,     saves INTEGER DEFAULT 0,     engagement_rate FLOAT DEFAULT 0.0,     status TEXT DEFAULT 'published',     error_message TEXT,     posted_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),     analytics_updated_at TIMESTAMP WITH TIME ZONE,     created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),     updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_posted_content_platform ON posted_content(platform); CREATE INDEX IF NOT EXISTS idx_posted_content_media_id ON posted_content(media_id); CREATE INDEX IF NOT EXISTS idx_posted_content_platform_post_id ON posted_content(platform_post_id); CREATE INDEX IF NOT EXISTS idx_posted_content_posted_at ON posted_content(posted_at);  COMMENT ON TABLE posted_content IS 'Tracks content published to social media with analytics';"}	create_posted_content_table
