20251224183149	{"-- Event History Table for Pub/Sub System -- Stores all events for debugging, replay, and analytics  CREATE TABLE IF NOT EXISTS event_history (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     event_id VARCHAR(255) NOT NULL,  -- Original event ID from EventBus     topic VARCHAR(255) NOT NULL,     source VARCHAR(100) NOT NULL,     correlation_id VARCHAR(255),     payload JSONB NOT NULL DEFAULT '{}',     metadata JSONB DEFAULT '{}',     timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),     created_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );  -- Indexes for efficient querying CREATE INDEX IF NOT EXISTS idx_event_history_topic ON event_history(topic); CREATE INDEX IF NOT EXISTS idx_event_history_timestamp ON event_history(timestamp DESC); CREATE INDEX IF NOT EXISTS idx_event_history_correlation_id ON event_history(correlation_id); CREATE INDEX IF NOT EXISTS idx_event_history_source ON event_history(source); CREATE INDEX IF NOT EXISTS idx_event_history_topic_timestamp ON event_history(topic, timestamp DESC); CREATE INDEX IF NOT EXISTS idx_event_history_event_id ON event_history(event_id);  -- Composite index for common queries CREATE INDEX IF NOT EXISTS idx_event_history_correlation_timestamp ON event_history(correlation_id, timestamp DESC);  -- Function to clean up old events (keep last 30 days by default) CREATE OR REPLACE FUNCTION cleanup_old_event_history(days_to_keep INTEGER DEFAULT 30) RETURNS INTEGER AS $$ DECLARE     deleted_count INTEGER; BEGIN     DELETE FROM event_history      WHERE timestamp < NOW() - (days_to_keep || ' days')::INTERVAL;          GET DIAGNOSTICS deleted_count = ROW_COUNT;     RETURN deleted_count; END; $$ LANGUAGE plpgsql;  -- View for recent events by topic CREATE OR REPLACE VIEW v_recent_events_by_topic AS SELECT      topic,     COUNT(*) as event_count,     MAX(timestamp) as last_event_at,     MIN(timestamp) as first_event_at FROM event_history WHERE timestamp >= NOW() - INTERVAL '24 hours' GROUP BY topic ORDER BY event_count DESC;  -- View for event statistics CREATE OR REPLACE VIEW v_event_statistics AS SELECT      DATE_TRUNC('hour', timestamp) as hour,     topic,     COUNT(*) as event_count,     COUNT(DISTINCT correlation_id) as unique_workflows,     COUNT(DISTINCT source) as unique_sources FROM event_history WHERE timestamp >= NOW() - INTERVAL '7 days' GROUP BY DATE_TRUNC('hour', timestamp), topic ORDER BY hour DESC, event_count DESC;"}	event_history_table
20251224191018	{"-- Event History Table for Pub/Sub System CREATE TABLE IF NOT EXISTS event_history (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     event_id VARCHAR(255) NOT NULL,     topic VARCHAR(255) NOT NULL,     source VARCHAR(100) NOT NULL,     correlation_id VARCHAR(255),     payload JSONB NOT NULL DEFAULT '{}',     metadata JSONB DEFAULT '{}',     timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(),     created_at TIMESTAMPTZ NOT NULL DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_event_history_topic ON event_history(topic); CREATE INDEX IF NOT EXISTS idx_event_history_timestamp ON event_history(timestamp DESC); CREATE INDEX IF NOT EXISTS idx_event_history_correlation_id ON event_history(correlation_id); CREATE INDEX IF NOT EXISTS idx_event_history_source ON event_history(source); CREATE INDEX IF NOT EXISTS idx_event_history_topic_timestamp ON event_history(topic, timestamp DESC); CREATE INDEX IF NOT EXISTS idx_event_history_event_id ON event_history(event_id); CREATE INDEX IF NOT EXISTS idx_event_history_correlation_timestamp ON event_history(correlation_id, timestamp DESC);  CREATE OR REPLACE FUNCTION cleanup_old_event_history(days_to_keep INTEGER DEFAULT 30) RETURNS INTEGER AS $$ DECLARE     deleted_count INTEGER; BEGIN     DELETE FROM event_history      WHERE timestamp < NOW() - (days_to_keep || ' days')::INTERVAL;     GET DIAGNOSTICS deleted_count = ROW_COUNT;     RETURN deleted_count; END; $$ LANGUAGE plpgsql;  CREATE OR REPLACE VIEW v_recent_events_by_topic AS SELECT      topic,     COUNT(*) as event_count,     MAX(timestamp) as last_event_at,     MIN(timestamp) as first_event_at FROM event_history WHERE timestamp >= NOW() - INTERVAL '24 hours' GROUP BY topic ORDER BY event_count DESC;  CREATE OR REPLACE VIEW v_event_statistics AS SELECT      DATE_TRUNC('hour', timestamp) as hour,     topic,     COUNT(*) as event_count,     COUNT(DISTINCT correlation_id) as unique_workflows,     COUNT(DISTINCT source) as unique_sources FROM event_history WHERE timestamp >= NOW() - INTERVAL '7 days' GROUP BY DATE_TRUNC('hour', timestamp), topic ORDER BY hour DESC, event_count DESC;"}	event_history_table_persist
20251224191020	{"-- Posted Content Tracking Table CREATE TABLE IF NOT EXISTS posted_content (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     platform TEXT NOT NULL,     platform_post_id TEXT,     platform_url TEXT,     account_id TEXT,     account_username TEXT,     media_id UUID,     caption TEXT,     hashtags TEXT[],     views INTEGER DEFAULT 0,     likes INTEGER DEFAULT 0,     comments INTEGER DEFAULT 0,     shares INTEGER DEFAULT 0,     saves INTEGER DEFAULT 0,     engagement_rate FLOAT DEFAULT 0.0,     status TEXT DEFAULT 'published',     error_message TEXT,     posted_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),     analytics_updated_at TIMESTAMP WITH TIME ZONE,     created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),     updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_posted_content_platform ON posted_content(platform); CREATE INDEX IF NOT EXISTS idx_posted_content_media_id ON posted_content(media_id); CREATE INDEX IF NOT EXISTS idx_posted_content_platform_post_id ON posted_content(platform_post_id); CREATE INDEX IF NOT EXISTS idx_posted_content_posted_at ON posted_content(posted_at);"}	posted_content_tracking
20251224191023	{"-- Add source column to scheduled_posts for tracking origin ALTER TABLE scheduled_posts  ADD COLUMN IF NOT EXISTS source VARCHAR(50);  -- Update source based on existing columns if they exist DO $$ BEGIN     -- Check if origin column exists and update source     IF EXISTS (SELECT 1 FROM information_schema.columns                  WHERE table_name = 'scheduled_posts' AND column_name = 'origin') THEN         UPDATE scheduled_posts          SET source = COALESCE(origin, 'manual')         WHERE source IS NULL;     END IF;          -- Check if origin_type column exists and update source     IF EXISTS (SELECT 1 FROM information_schema.columns                  WHERE table_name = 'scheduled_posts' AND column_name = 'origin_type') THEN         UPDATE scheduled_posts          SET source = CASE              WHEN origin_type = 'experiment' THEN 'experiment'             WHEN origin_type = 'narrative' THEN 'narrative'             WHEN origin_type = 'user' THEN 'manual'             ELSE COALESCE(source, 'manual')         END         WHERE source IS NULL;     END IF;          -- Check if experiment_id column exists and update source     IF EXISTS (SELECT 1 FROM information_schema.columns                  WHERE table_name = 'scheduled_posts' AND column_name = 'experiment_id') THEN         UPDATE scheduled_posts          SET source = 'experiment'         WHERE experiment_id IS NOT NULL AND source IS NULL;     END IF;          -- Default to 'manual' for any remaining NULLs     UPDATE scheduled_posts      SET source = 'manual'     WHERE source IS NULL; END $$;  CREATE INDEX IF NOT EXISTS idx_scheduled_posts_source ON scheduled_posts(source);"}	add_source_column_scheduled_posts
20251224191026	{"-- Add deep analysis columns to video_analysis table ALTER TABLE video_analysis  ADD COLUMN IF NOT EXISTS visual_analysis JSONB, ADD COLUMN IF NOT EXISTS deep_analysis JSONB, ADD COLUMN IF NOT EXISTS frame_analyses JSONB, ADD COLUMN IF NOT EXISTS platform_content JSONB, ADD COLUMN IF NOT EXISTS detected_hook TEXT, ADD COLUMN IF NOT EXISTS music_suggestion TEXT, ADD COLUMN IF NOT EXISTS pillar_tags TEXT[], ADD COLUMN IF NOT EXISTS format_tags TEXT[];  COMMENT ON COLUMN video_analysis.visual_analysis IS 'Detailed visual scene analysis'; COMMENT ON COLUMN video_analysis.deep_analysis IS 'AI-powered deep content analysis'; COMMENT ON COLUMN video_analysis.frame_analyses IS 'Per-frame analysis results'; COMMENT ON COLUMN video_analysis.platform_content IS 'Platform-specific content recommendations'; COMMENT ON COLUMN video_analysis.detected_hook IS 'Detected hook moment in video'; COMMENT ON COLUMN video_analysis.music_suggestion IS 'Suggested music/track'; COMMENT ON COLUMN video_analysis.pillar_tags IS 'Narrative pillar tags'; COMMENT ON COLUMN video_analysis.format_tags IS 'Content format tags';"}	deep_analysis_video_columns
20251224191028	{"-- Ensure account_id in posted_content is TEXT type DO $$ BEGIN     -- Check current type and alter if needed     IF EXISTS (         SELECT 1 FROM information_schema.columns          WHERE table_name = 'posted_content'          AND column_name = 'account_id'         AND data_type != 'text'     ) THEN         ALTER TABLE posted_content          ALTER COLUMN account_id TYPE TEXT USING account_id::TEXT;     END IF; END $$;"}	fix_posted_content_account_id_type
20251224191149	{"-- Agent Queue Table CREATE TABLE IF NOT EXISTS agent_queue (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     workspace_id UUID,     agent_type VARCHAR(50) NOT NULL,     topic VARCHAR(100) NOT NULL,     payload JSONB NOT NULL DEFAULT '{}',     priority INTEGER DEFAULT 5,     status VARCHAR(20) DEFAULT 'queued',     claimed_by VARCHAR(255),     claimed_at TIMESTAMPTZ,     started_at TIMESTAMPTZ,     completed_at TIMESTAMPTZ,     error_message TEXT,     retry_count INTEGER DEFAULT 0,     max_retries INTEGER DEFAULT 3,     created_at TIMESTAMPTZ DEFAULT NOW(),     updated_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_agent_queue_status ON agent_queue(status, priority DESC, created_at); CREATE INDEX IF NOT EXISTS idx_agent_queue_agent_type ON agent_queue(agent_type); CREATE INDEX IF NOT EXISTS idx_agent_queue_claimed ON agent_queue(claimed_by) WHERE status = 'running';  -- Function to claim a job CREATE OR REPLACE FUNCTION claim_queue_job(     p_agent_type VARCHAR(50),     p_worker_id VARCHAR(255) ) RETURNS UUID AS $$ DECLARE     job_id UUID; BEGIN     UPDATE agent_queue     SET status = 'running',         claimed_by = p_worker_id,         claimed_at = NOW(),         started_at = NOW()     WHERE id = (         SELECT id FROM agent_queue         WHERE agent_type = p_agent_type         AND status = 'queued'         ORDER BY priority DESC, created_at ASC         LIMIT 1         FOR UPDATE SKIP LOCKED     )     RETURNING id INTO job_id;          RETURN job_id; END; $$ LANGUAGE plpgsql;  -- Function to complete a job CREATE OR REPLACE FUNCTION complete_queue_job(     p_job_id UUID,     p_success BOOLEAN DEFAULT TRUE,     p_error_message TEXT DEFAULT NULL ) RETURNS VOID AS $$ BEGIN     UPDATE agent_queue     SET status = CASE WHEN p_success THEN 'completed' ELSE 'failed' END,         completed_at = NOW(),         error_message = p_error_message,         updated_at = NOW()     WHERE id = p_job_id; END; $$ LANGUAGE plpgsql;  -- Function to retry failed jobs CREATE OR REPLACE FUNCTION retry_failed_jobs(     p_max_retries INTEGER DEFAULT 3 ) RETURNS INTEGER AS $$ DECLARE     retried_count INTEGER; BEGIN     UPDATE agent_queue     SET status = 'queued',         claimed_by = NULL,         claimed_at = NULL,         started_at = NULL,         retry_count = retry_count + 1,         updated_at = NOW()     WHERE status = 'failed'     AND retry_count < p_max_retries;          GET DIAGNOSTICS retried_count = ROW_COUNT;     RETURN retried_count; END; $$ LANGUAGE plpgsql;"}	agent_queue_table
20251224191100	{"-- TRENDS & ANALYTICS SYSTEM -- Social Media Trends CREATE TABLE IF NOT EXISTS trend_hashtags (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     platform TEXT NOT NULL,     hashtag TEXT NOT NULL,     rank INTEGER,     post_count BIGINT,     view_count BIGINT,     growth_rate DECIMAL(10, 4),     category TEXT,     region TEXT DEFAULT 'global',     is_sponsored BOOLEAN DEFAULT false,     snapshot_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),     metadata JSONB DEFAULT '{}',     created_at TIMESTAMPTZ DEFAULT NOW(),     UNIQUE(platform, hashtag, snapshot_at) );  CREATE TABLE IF NOT EXISTS trend_sounds (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     platform TEXT NOT NULL,     sound_id TEXT,     sound_name TEXT NOT NULL,     artist_name TEXT,     rank INTEGER,     usage_count BIGINT,     growth_rate DECIMAL(10, 4),     duration_seconds INTEGER,     is_original BOOLEAN DEFAULT false,     region TEXT DEFAULT 'global',     snapshot_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),     metadata JSONB DEFAULT '{}',     created_at TIMESTAMPTZ DEFAULT NOW(),     UNIQUE(platform, sound_id, snapshot_at) );  CREATE TABLE IF NOT EXISTS trend_topics (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     platform TEXT NOT NULL,     topic TEXT NOT NULL,     rank INTEGER,     mention_count BIGINT,     sentiment_score DECIMAL(5, 4),     growth_rate DECIMAL(10, 4),     related_hashtags TEXT[],     category TEXT,     region TEXT DEFAULT 'global',     snapshot_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),     metadata JSONB DEFAULT '{}',     created_at TIMESTAMPTZ DEFAULT NOW(),     UNIQUE(platform, topic, snapshot_at) );  CREATE TABLE IF NOT EXISTS trend_creators (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     platform TEXT NOT NULL,     username TEXT NOT NULL,     display_name TEXT,     follower_count BIGINT,     follower_growth BIGINT,     engagement_rate DECIMAL(10, 4),     avg_views BIGINT,     content_category TEXT,     verified BOOLEAN DEFAULT false,     rank INTEGER,     region TEXT DEFAULT 'global',     snapshot_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),     profile_url TEXT,     avatar_url TEXT,     metadata JSONB DEFAULT '{}',     created_at TIMESTAMPTZ DEFAULT NOW(),     UNIQUE(platform, username, snapshot_at) );  CREATE TABLE IF NOT EXISTS trend_formats (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     platform TEXT NOT NULL,     format_name TEXT NOT NULL,     description TEXT,     example_count BIGINT,     avg_engagement_rate DECIMAL(10, 4),     growth_rate DECIMAL(10, 4),     typical_duration_seconds INTEGER,     best_posting_times JSONB,     rank INTEGER,     snapshot_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),     metadata JSONB DEFAULT '{}',     created_at TIMESTAMPTZ DEFAULT NOW(),     UNIQUE(platform, format_name, snapshot_at) );  -- App Store Analytics CREATE TABLE IF NOT EXISTS appstore_rankings (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     store TEXT NOT NULL,     app_id TEXT NOT NULL,     app_name TEXT NOT NULL,     developer TEXT,     category TEXT NOT NULL,     chart_type TEXT NOT NULL,     rank INTEGER NOT NULL,     previous_rank INTEGER,     rank_change INTEGER,     rating DECIMAL(3, 2),     rating_count BIGINT,     price DECIMAL(10, 2),     region TEXT DEFAULT 'US',     snapshot_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),     icon_url TEXT,     metadata JSONB DEFAULT '{}',     created_at TIMESTAMPTZ DEFAULT NOW(),     UNIQUE(store, app_id, chart_type, region, snapshot_at) );  CREATE TABLE IF NOT EXISTS appstore_metrics (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     store TEXT NOT NULL,     app_id TEXT NOT NULL,     app_name TEXT NOT NULL,     daily_downloads_estimate BIGINT,     monthly_downloads_estimate BIGINT,     daily_revenue_estimate DECIMAL(12, 2),     monthly_revenue_estimate DECIMAL(12, 2),     rating DECIMAL(3, 2),     rating_count BIGINT,     review_count BIGINT,     update_frequency_days INTEGER,     last_update_at TIMESTAMPTZ,     version TEXT,     size_mb DECIMAL(10, 2),     region TEXT DEFAULT 'US',     snapshot_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),     metadata JSONB DEFAULT '{}',     created_at TIMESTAMPTZ DEFAULT NOW(),     UNIQUE(store, app_id, region, snapshot_at) );  CREATE TABLE IF NOT EXISTS appstore_reviews (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     store TEXT NOT NULL,     app_id TEXT NOT NULL,     review_id TEXT,     rating INTEGER,     title TEXT,     content TEXT,     author TEXT,     sentiment_score DECIMAL(5, 4),     key_topics TEXT[],     is_featured BOOLEAN DEFAULT false,     helpful_count INTEGER,     review_date TIMESTAMPTZ,     version_reviewed TEXT,     region TEXT DEFAULT 'US',     created_at TIMESTAMPTZ DEFAULT NOW(),     UNIQUE(store, review_id) );  -- Industry Benchmarks CREATE TABLE IF NOT EXISTS industry_benchmarks (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     platform TEXT NOT NULL,     category TEXT NOT NULL,     metric_name TEXT NOT NULL,     metric_value DECIMAL(15, 6),     percentile_25 DECIMAL(15, 6),     percentile_50 DECIMAL(15, 6),     percentile_75 DECIMAL(15, 6),     percentile_90 DECIMAL(15, 6),     sample_size INTEGER,     time_period TEXT,     snapshot_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),     metadata JSONB DEFAULT '{}',     created_at TIMESTAMPTZ DEFAULT NOW(),     UNIQUE(platform, category, metric_name, time_period, snapshot_at) );  -- Trend Alerts & Notifications CREATE TABLE IF NOT EXISTS trend_alerts (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     alert_type TEXT NOT NULL,     platform TEXT,     title TEXT NOT NULL,     description TEXT,     importance TEXT DEFAULT 'medium',     trend_data JSONB,     is_read BOOLEAN DEFAULT false,     is_dismissed BOOLEAN DEFAULT false,     expires_at TIMESTAMPTZ,     created_at TIMESTAMPTZ DEFAULT NOW() );  CREATE TABLE IF NOT EXISTS saved_trends (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     trend_type TEXT NOT NULL,     trend_id UUID NOT NULL,     platform TEXT,     notes TEXT,     tags TEXT[],     notify_on_change BOOLEAN DEFAULT false,     created_at TIMESTAMPTZ DEFAULT NOW() );  -- Competitor Tracking CREATE TABLE IF NOT EXISTS tracked_competitors (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     platform TEXT NOT NULL,     username TEXT NOT NULL,     display_name TEXT,     notes TEXT,     is_active BOOLEAN DEFAULT true,     created_at TIMESTAMPTZ DEFAULT NOW(),     UNIQUE(platform, username) );  CREATE TABLE IF NOT EXISTS competitor_snapshots (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     competitor_id UUID REFERENCES tracked_competitors(id) ON DELETE CASCADE,     follower_count BIGINT,     following_count BIGINT,     post_count BIGINT,     avg_likes BIGINT,     avg_comments BIGINT,     avg_views BIGINT,     engagement_rate DECIMAL(10, 4),     top_hashtags TEXT[],     posting_frequency DECIMAL(5, 2),     snapshot_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),     metadata JSONB DEFAULT '{}',     created_at TIMESTAMPTZ DEFAULT NOW() );  -- Indexes CREATE INDEX IF NOT EXISTS idx_trend_hashtags_platform_time ON trend_hashtags(platform, snapshot_at DESC); CREATE INDEX IF NOT EXISTS idx_trend_sounds_platform_time ON trend_sounds(platform, snapshot_at DESC); CREATE INDEX IF NOT EXISTS idx_trend_topics_platform_time ON trend_topics(platform, snapshot_at DESC); CREATE INDEX IF NOT EXISTS idx_trend_creators_platform_time ON trend_creators(platform, snapshot_at DESC); CREATE INDEX IF NOT EXISTS idx_appstore_rankings_store_time ON appstore_rankings(store, snapshot_at DESC); CREATE INDEX IF NOT EXISTS idx_trend_alerts_unread ON trend_alerts(is_read, created_at DESC) WHERE NOT is_read; CREATE INDEX IF NOT EXISTS idx_competitor_snapshots_time ON competitor_snapshots(competitor_id, snapshot_at DESC);"}	trends_analytics_system_tables
20251224191102	{"-- AI VIDEO GENERATIONS CREATE TABLE IF NOT EXISTS ai_video_generations (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     provider TEXT NOT NULL,     prompt TEXT NOT NULL,     settings JSONB DEFAULT '{}',     status TEXT NOT NULL DEFAULT 'pending',     output_url TEXT,     thumbnail_url TEXT,     duration_seconds DECIMAL(10, 2),     resolution TEXT,     aspect_ratio TEXT,     file_size_bytes BIGINT,     error_message TEXT,     retry_count INTEGER DEFAULT 0,     created_at TIMESTAMPTZ DEFAULT NOW(),     started_at TIMESTAMPTZ,     completed_at TIMESTAMPTZ,     media_id UUID,     metadata JSONB DEFAULT '{}' );  CREATE INDEX IF NOT EXISTS idx_ai_video_generations_status ON ai_video_generations(status); CREATE INDEX IF NOT EXISTS idx_ai_video_generations_provider ON ai_video_generations(provider); CREATE INDEX IF NOT EXISTS idx_ai_video_generations_created ON ai_video_generations(created_at DESC);"}	ai_video_generations_table
20251224191123	{"-- AI MEDIA GENERATIONS - ENHANCED SCHEMA DO $$  BEGIN     IF NOT EXISTS (SELECT 1 FROM information_schema.columns                     WHERE table_name = 'ai_video_generations' AND column_name = 'ai_title') THEN         ALTER TABLE ai_video_generations ADD COLUMN ai_title TEXT;     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.columns                     WHERE table_name = 'ai_video_generations' AND column_name = 'ai_description') THEN         ALTER TABLE ai_video_generations ADD COLUMN ai_description TEXT;     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.columns                     WHERE table_name = 'ai_video_generations' AND column_name = 'style_preset') THEN         ALTER TABLE ai_video_generations ADD COLUMN style_preset TEXT;     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.columns                     WHERE table_name = 'ai_video_generations' AND column_name = 'camera_motion') THEN         ALTER TABLE ai_video_generations ADD COLUMN camera_motion TEXT;     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.columns                     WHERE table_name = 'ai_video_generations' AND column_name = 'character_ids') THEN         ALTER TABLE ai_video_generations ADD COLUMN character_ids UUID[];     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.columns                     WHERE table_name = 'ai_video_generations' AND column_name = 'enhanced_prompt') THEN         ALTER TABLE ai_video_generations ADD COLUMN enhanced_prompt TEXT;     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.columns                     WHERE table_name = 'ai_video_generations' AND column_name = 'video_id') THEN         ALTER TABLE ai_video_generations ADD COLUMN video_id UUID REFERENCES videos(id) ON DELETE SET NULL;     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.columns                     WHERE table_name = 'ai_video_generations' AND column_name = 'credits_used') THEN         ALTER TABLE ai_video_generations ADD COLUMN credits_used DECIMAL(10, 2);     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.columns                     WHERE table_name = 'ai_video_generations' AND column_name = 'user_id') THEN         ALTER TABLE ai_video_generations ADD COLUMN user_id UUID;     END IF; END $$;  -- AI CHARACTERS TABLE CREATE TABLE IF NOT EXISTS ai_characters (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     user_id UUID,     name TEXT NOT NULL,     description TEXT NOT NULL,     avatar_emoji TEXT DEFAULT '👤',     reference_image_url TEXT,     attributes JSONB DEFAULT '{}',     usage_count INTEGER DEFAULT 0,     last_used_at TIMESTAMPTZ,     created_at TIMESTAMPTZ DEFAULT NOW(),     updated_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_ai_characters_user ON ai_characters(user_id);  -- AI STYLE PRESETS TABLE CREATE TABLE IF NOT EXISTS ai_style_presets (     id TEXT PRIMARY KEY,     user_id UUID,     name TEXT NOT NULL,     description TEXT,     icon TEXT,     keywords TEXT NOT NULL,     color_gradient TEXT,     category TEXT DEFAULT 'general',     is_system BOOLEAN DEFAULT FALSE,     usage_count INTEGER DEFAULT 0,     created_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_ai_style_presets_user ON ai_style_presets(user_id);  -- Insert system style presets INSERT INTO ai_style_presets (id, name, description, icon, keywords, color_gradient, category, is_system) VALUES     ('cinematic', 'Cinematic', 'Film-like visuals with dramatic lighting', '🎬', '35mm film, shallow depth of field, cinematic lighting, movie quality', 'from-amber-500 to-orange-600', 'cinematic', TRUE),     ('photorealistic', 'Photorealistic', 'Ultra-realistic, lifelike footage', '📷', '8K, photorealistic, natural lighting, hyper-detailed', 'from-gray-500 to-slate-600', 'general', TRUE),     ('anime', 'Anime', 'Japanese animation style', '🎨', 'anime style, hand-drawn, vibrant colors, cel-shaded', 'from-pink-500 to-rose-600', 'animated', TRUE),     ('cyberpunk', 'Cyberpunk', 'Futuristic neon aesthetics', '🌃', 'cyberpunk, neon lights, rain, dystopian, holographic', 'from-cyan-500 to-blue-600', 'artistic', TRUE),     ('film_noir', 'Film Noir', 'Classic black-and-white dramatic style', '🎩', 'black and white, high contrast, dramatic shadows, noir', 'from-zinc-600 to-zinc-800', 'cinematic', TRUE),     ('dreamy', 'Dreamy', 'Soft, ethereal visuals', '☁️', 'soft focus, pastel colors, ethereal glow, dreamy atmosphere', 'from-purple-400 to-pink-400', 'artistic', TRUE),     ('stop_motion', 'Stop Motion', 'Frame-by-frame animation look', '🎭', 'stop motion, claymation, handcrafted, tactile textures', 'from-yellow-500 to-amber-600', 'animated', TRUE),     ('vintage', 'Vintage', 'Retro film aesthetics', '📼', 'VHS, film grain, 70s aesthetic, faded colors, retro', 'from-orange-400 to-red-500', 'artistic', TRUE),     ('surreal', 'Surreal', 'Abstract, dreamlike imagery', '🌀', 'surreal, Salvador Dali, impossible geometry, dreamscape', 'from-violet-500 to-purple-600', 'artistic', TRUE),     ('documentary', 'Documentary', 'Raw, authentic footage style', '📹', 'documentary style, handheld, natural, unscripted feel', 'from-emerald-500 to-green-600', 'cinematic', TRUE) ON CONFLICT (id) DO NOTHING;  -- AI CAMERA MOTIONS TABLE CREATE TABLE IF NOT EXISTS ai_camera_motions (     id TEXT PRIMARY KEY,     name TEXT NOT NULL,     description TEXT,     icon TEXT,     keywords TEXT NOT NULL,     is_system BOOLEAN DEFAULT TRUE,     created_at TIMESTAMPTZ DEFAULT NOW() );  INSERT INTO ai_camera_motions (id, name, description, icon, keywords, is_system) VALUES     ('static', 'Static', 'Camera remains stationary', '⏸️', 'static shot, locked off camera', TRUE),     ('slow_pan', 'Slow Pan', 'Gradual horizontal movement', '↔️', 'slow pan, smooth horizontal movement', TRUE),     ('tilt', 'Tilt', 'Gradual vertical movement', '↕️', 'slow tilt, vertical camera movement', TRUE),     ('dolly_in', 'Dolly In', 'Camera moves toward subject', '🎯', 'dolly in, push in, moving closer', TRUE),     ('dolly_out', 'Dolly Out', 'Camera moves away from subject', '🔙', 'dolly out, pull back, reveal shot', TRUE),     ('orbit', 'Orbit', 'Camera circles around subject', '🔄', 'orbit shot, 360 rotation, circling camera', TRUE),     ('tracking', 'Tracking', 'Camera follows moving subject', '🏃', 'tracking shot, follow shot, moving with subject', TRUE),     ('crane', 'Crane', 'Vertical movement, high to low', '🏗️', 'crane shot, jib shot, ascending descending', TRUE),     ('zoom', 'Zoom', 'Lens zoom effect', '🔍', 'zoom in, zoom out, lens zoom', TRUE),     ('handheld', 'Handheld', 'Slight shake for documentary feel', '✋', 'handheld camera, slight shake, organic movement', TRUE),     ('drone', 'Drone', 'Aerial sweeping movements', '🚁', 'drone shot, aerial view, sweeping aerial movement', TRUE),     ('first_person', 'First Person', 'POV perspective', '👁️', 'first person POV, point of view shot', TRUE) ON CONFLICT (id) DO NOTHING;  -- AI GENERATION JOBS TABLE CREATE TABLE IF NOT EXISTS ai_generation_jobs (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     generation_id UUID REFERENCES ai_video_generations(id) ON DELETE CASCADE,     provider TEXT NOT NULL,     external_job_id TEXT,     status TEXT NOT NULL DEFAULT 'queued',     progress INTEGER DEFAULT 0,     queue_position INTEGER,     estimated_completion TIMESTAMPTZ,     events JSONB DEFAULT '[]',     created_at TIMESTAMPTZ DEFAULT NOW(),     updated_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_ai_generation_jobs_status ON ai_generation_jobs(status); CREATE INDEX IF NOT EXISTS idx_ai_generation_jobs_generation ON ai_generation_jobs(generation_id);  -- FUNCTION: Link AI generation to videos table CREATE OR REPLACE FUNCTION link_ai_generation_to_videos() RETURNS TRIGGER AS $$ BEGIN     IF NEW.status = 'completed' AND NEW.output_url IS NOT NULL AND NEW.video_id IS NULL THEN         INSERT INTO videos (user_id, source_type, source_uri, file_name, duration_sec, resolution, aspect_ratio)         VALUES (             COALESCE(NEW.user_id, '00000000-0000-0000-0000-000000000000'::UUID),             'ai_generated',             NEW.output_url,             COALESCE(NEW.ai_title, 'AI Generated Video'),             NEW.duration_seconds::INTEGER,             NEW.resolution,             NEW.aspect_ratio         )         RETURNING id INTO NEW.video_id;     END IF;          RETURN NEW; END; $$ LANGUAGE plpgsql;  DROP TRIGGER IF EXISTS trg_link_ai_generation ON ai_video_generations; CREATE TRIGGER trg_link_ai_generation     BEFORE UPDATE ON ai_video_generations     FOR EACH ROW     EXECUTE FUNCTION link_ai_generation_to_videos();  -- VIEW: Unified media library CREATE OR REPLACE VIEW unified_media_library AS SELECT      v.id,     v.file_name as title,     v.source_type,     v.source_uri as url,     v.duration_sec,     v.resolution,     v.aspect_ratio,     v.created_at,     'ugc' as origin,     NULL::TEXT as ai_provider,     NULL::TEXT as ai_prompt,     NULL::TEXT as style_preset,     va.pre_social_score as score,     va.topics,     va.tone FROM videos v LEFT JOIN video_analysis va ON v.id = va.video_id WHERE v.source_type != 'ai_generated'  UNION ALL  SELECT      COALESCE(aig.video_id, aig.id) as id,     COALESCE(aig.ai_title, 'AI Video') as title,     'ai_generated' as source_type,     aig.output_url as url,     aig.duration_seconds::INTEGER as duration_sec,     aig.resolution,     aig.aspect_ratio,     aig.created_at,     'ai' as origin,     aig.provider as ai_provider,     aig.prompt as ai_prompt,     aig.style_preset,     NULL::NUMERIC as score,     NULL::TEXT[] as topics,     NULL::TEXT as tone FROM ai_video_generations aig WHERE aig.status = 'completed';"}	ai_media_generations_enhanced
20251224191133	{"-- ACCOUNT ROLES & KNOWLEDGE BASE -- Add account_role to social_accounts ALTER TABLE social_accounts  ADD COLUMN IF NOT EXISTS account_role VARCHAR(20) DEFAULT 'MAINLINE';  DO $$  BEGIN   IF NOT EXISTS (     SELECT 1 FROM pg_constraint WHERE conname = 'social_accounts_role_check'   ) THEN     ALTER TABLE social_accounts      ADD CONSTRAINT social_accounts_role_check      CHECK (account_role IN ('MAINLINE', 'EXPERIMENT_ARM', 'ARCHIVE', 'SEED'));   END IF; END $$;  CREATE INDEX IF NOT EXISTS idx_social_accounts_role ON social_accounts(account_role);  -- KNOWLEDGE BASE - RULES CREATE TABLE IF NOT EXISTS kb_rules (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   workspace_id UUID,   rule_type VARCHAR(50) NOT NULL,   name VARCHAR(255),   description TEXT,   conditions JSONB NOT NULL DEFAULT '{}'::jsonb,   action JSONB NOT NULL DEFAULT '{}'::jsonb,   confidence_score DECIMAL(5, 4) DEFAULT 0.5,   source_experiment_id UUID,   source_hypothesis_id UUID,   is_active BOOLEAN DEFAULT TRUE,   created_at TIMESTAMPTZ DEFAULT NOW(),   updated_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_kb_rules_type ON kb_rules(rule_type); CREATE INDEX IF NOT EXISTS idx_kb_rules_active ON kb_rules(is_active);  -- KNOWLEDGE BASE - TEMPLATES CREATE TABLE IF NOT EXISTS kb_templates (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   workspace_id UUID,   template_type VARCHAR(50) NOT NULL,   name VARCHAR(255) NOT NULL,   content TEXT NOT NULL,   variables JSONB DEFAULT '{}'::jsonb,   usage_count INTEGER DEFAULT 0,   success_rate DECIMAL(5, 4),   is_active BOOLEAN DEFAULT TRUE,   created_at TIMESTAMPTZ DEFAULT NOW(),   updated_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_kb_templates_type ON kb_templates(template_type);  -- KNOWLEDGE BASE - CONSTRAINTS CREATE TABLE IF NOT EXISTS kb_constraints (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   workspace_id UUID,   constraint_type VARCHAR(50) NOT NULL,   name VARCHAR(255) NOT NULL,   description TEXT,   rule_expression JSONB NOT NULL,   is_active BOOLEAN DEFAULT TRUE,   created_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_kb_constraints_type ON kb_constraints(constraint_type);  -- KNOWLEDGE BASE - PLAYBOOKS CREATE TABLE IF NOT EXISTS kb_playbooks (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   workspace_id UUID,   name VARCHAR(255) NOT NULL,   description TEXT,   steps JSONB NOT NULL DEFAULT '[]'::jsonb,   trigger_conditions JSONB DEFAULT '{}'::jsonb,   is_active BOOLEAN DEFAULT TRUE,   created_at TIMESTAMPTZ DEFAULT NOW(),   updated_at TIMESTAMPTZ DEFAULT NOW() );  -- NARRATIVE GOALS (if not exists) CREATE TABLE IF NOT EXISTS narrative_goals (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   workspace_id UUID,   goal_statement TEXT NOT NULL,   primary_cta TEXT NOT NULL DEFAULT 'follow',   target_audience TEXT,   time_horizon TEXT DEFAULT 'next_7_days',   start_date DATE,   end_date DATE,   target_followers INTEGER,   target_engagement_rate FLOAT,   target_conversions INTEGER,   status TEXT DEFAULT 'active',   created_at TIMESTAMPTZ DEFAULT NOW(),   updated_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_narrative_goals_status ON narrative_goals(status);  -- Add origin tracking to scheduled_posts ALTER TABLE scheduled_posts  ADD COLUMN IF NOT EXISTS origin_type VARCHAR(20) DEFAULT 'user', ADD COLUMN IF NOT EXISTS experiment_id UUID, ADD COLUMN IF NOT EXISTS hypothesis_id UUID, ADD COLUMN IF NOT EXISTS variant VARCHAR(20);  CREATE INDEX IF NOT EXISTS idx_scheduled_posts_origin ON scheduled_posts(origin_type); CREATE INDEX IF NOT EXISTS idx_scheduled_posts_experiment ON scheduled_posts(experiment_id);  -- ENHANCE EXPERIMENTS TABLE DO $$ BEGIN     IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'experiments') THEN         CREATE TABLE experiments (             id UUID PRIMARY KEY DEFAULT gen_random_uuid(),             name VARCHAR(255) NOT NULL,             description TEXT,             goal TEXT NOT NULL,             status VARCHAR(20) DEFAULT 'draft',             start_date TIMESTAMP WITH TIME ZONE,             end_date TIMESTAMP WITH TIME ZONE,             success_criteria JSONB DEFAULT '{}',             target_accounts TEXT[],             resource_types TEXT[],             results JSONB DEFAULT '{}',             learnings TEXT,             winner_video_ids UUID[],             created_by VARCHAR(50) DEFAULT 'system',             created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),             updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()         );     END IF; END $$;  -- HYDRATION SNAPSHOTS CREATE TABLE IF NOT EXISTS hydration_snapshots (   id UUID PRIMARY KEY DEFAULT gen_random_uuid(),   workspace_id UUID,   snapshot_type VARCHAR(50) NOT NULL,   snapshot_data JSONB NOT NULL,   created_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_hydration_snapshots_type ON hydration_snapshots(snapshot_type);  -- Update trigger function CREATE OR REPLACE FUNCTION update_updated_at_column() RETURNS TRIGGER AS $$ BEGIN     NEW.updated_at = NOW();     RETURN NEW; END; $$ LANGUAGE plpgsql;"}	account_roles_knowledge_base
20251224191136	{"-- Agent Events Table for Pub/Sub Framework CREATE TABLE IF NOT EXISTS agent_events (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     agent_type VARCHAR(50) NOT NULL,     event_type VARCHAR(50) NOT NULL,     title VARCHAR(255) NOT NULL,     description TEXT,     event_data JSONB DEFAULT '{}',     created_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_agent_events_agent_type ON agent_events(agent_type); CREATE INDEX IF NOT EXISTS idx_agent_events_event_type ON agent_events(event_type); CREATE INDEX IF NOT EXISTS idx_agent_events_created_at ON agent_events(created_at DESC); CREATE INDEX IF NOT EXISTS idx_agent_events_agent_created ON agent_events(agent_type, created_at DESC);  CREATE OR REPLACE FUNCTION cleanup_old_agent_events() RETURNS void AS $$ BEGIN     DELETE FROM agent_events WHERE created_at < NOW() - INTERVAL '7 days'; END; $$ LANGUAGE plpgsql;"}	agent_events_table
20251224191145	{"-- Automation Center Schema -- AGENT SCHEDULES CREATE TABLE IF NOT EXISTS agent_schedules (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     workspace_id UUID,     agent_type VARCHAR(50) NOT NULL,     topic VARCHAR(100) NOT NULL,     schedule_name VARCHAR(100) NOT NULL,     cron_expr VARCHAR(50),     interval_seconds INTEGER,     enabled BOOLEAN DEFAULT TRUE,     next_run_at TIMESTAMPTZ,     last_run_at TIMESTAMPTZ,     config_json JSONB DEFAULT '{}',     created_at TIMESTAMPTZ DEFAULT NOW(),     updated_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_agent_schedules_agent_type ON agent_schedules(agent_type); CREATE INDEX IF NOT EXISTS idx_agent_schedules_enabled ON agent_schedules(enabled, next_run_at);  -- AGENT RUNS CREATE TABLE IF NOT EXISTS agent_runs (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     workspace_id UUID,     agent_type VARCHAR(50) NOT NULL,     schedule_id UUID REFERENCES agent_schedules(id),     status VARCHAR(20) DEFAULT 'queued',     progress_current INTEGER DEFAULT 0,     progress_total INTEGER DEFAULT 0,     started_at TIMESTAMPTZ,     finished_at TIMESTAMPTZ,     last_heartbeat_at TIMESTAMPTZ,     root_context_json JSONB DEFAULT '{}',     error_message TEXT,     created_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_agent_runs_agent_type ON agent_runs(agent_type); CREATE INDEX IF NOT EXISTS idx_agent_runs_status ON agent_runs(status); CREATE INDEX IF NOT EXISTS idx_agent_runs_schedule ON agent_runs(schedule_id);  -- AGENT STEPS CREATE TABLE IF NOT EXISTS agent_steps (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     run_id UUID NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,     step_key VARCHAR(50) NOT NULL,     step_name VARCHAR(100) NOT NULL,     step_order INTEGER DEFAULT 0,     status VARCHAR(20) DEFAULT 'pending',     started_at TIMESTAMPTZ,     finished_at TIMESTAMPTZ,     duration_ms INTEGER,     summary TEXT,     input_refs JSONB DEFAULT '[]',     output_refs JSONB DEFAULT '[]',     error_message TEXT,     created_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_agent_steps_run ON agent_steps(run_id); CREATE INDEX IF NOT EXISTS idx_agent_steps_status ON agent_steps(status);  -- Enhance agent_events table ALTER TABLE agent_events ADD COLUMN IF NOT EXISTS run_id UUID REFERENCES agent_runs(id) ON DELETE CASCADE; ALTER TABLE agent_events ADD COLUMN IF NOT EXISTS step_id UUID REFERENCES agent_steps(id); ALTER TABLE agent_events ADD COLUMN IF NOT EXISTS ts TIMESTAMPTZ DEFAULT NOW(); ALTER TABLE agent_events ADD COLUMN IF NOT EXISTS topic VARCHAR(100); ALTER TABLE agent_events ADD COLUMN IF NOT EXISTS severity VARCHAR(20) DEFAULT 'info'; ALTER TABLE agent_events ADD COLUMN IF NOT EXISTS source_service VARCHAR(50); ALTER TABLE agent_events ADD COLUMN IF NOT EXISTS message TEXT; ALTER TABLE agent_events ADD COLUMN IF NOT EXISTS payload_json JSONB DEFAULT '{}';  CREATE INDEX IF NOT EXISTS idx_agent_events_run ON agent_events(run_id); CREATE INDEX IF NOT EXISTS idx_agent_events_step ON agent_events(step_id); CREATE INDEX IF NOT EXISTS idx_agent_events_topic ON agent_events(topic); CREATE INDEX IF NOT EXISTS idx_agent_events_ts ON agent_events(ts DESC);  -- AGENT ARTIFACTS CREATE TABLE IF NOT EXISTS agent_artifacts (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     run_id UUID NOT NULL REFERENCES agent_runs(id) ON DELETE CASCADE,     artifact_type VARCHAR(50) NOT NULL,     artifact_key VARCHAR(100) NOT NULL,     content_json JSONB NOT NULL,     created_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_agent_artifacts_run ON agent_artifacts(run_id); CREATE INDEX IF NOT EXISTS idx_agent_artifacts_type ON agent_artifacts(artifact_type);  -- VIEWS CREATE OR REPLACE VIEW v_recent_runs AS SELECT      r.id,     r.agent_type,     r.status,     r.progress_current,     r.progress_total,     r.started_at,     r.finished_at,     s.schedule_name,     COUNT(DISTINCT st.id) as step_count,     COUNT(DISTINCT CASE WHEN st.status = 'completed' THEN st.id END) as completed_steps FROM agent_runs r LEFT JOIN agent_schedules s ON r.schedule_id = s.id LEFT JOIN agent_steps st ON st.run_id = r.id WHERE r.created_at >= NOW() - INTERVAL '7 days' GROUP BY r.id, r.agent_type, r.status, r.progress_current, r.progress_total, r.started_at, r.finished_at, s.schedule_name ORDER BY r.created_at DESC;  CREATE OR REPLACE VIEW v_run_timeline AS SELECT      e.run_id,     e.ts,     e.agent_type,     e.event_type,     e.title,     e.message,     e.severity,     e.topic,     e.step_id,     st.step_name,     st.step_key FROM agent_events e LEFT JOIN agent_steps st ON e.step_id = st.id WHERE e.run_id IS NOT NULL ORDER BY e.ts ASC;"}	automation_center_schema
20251224191609	{"-- Fix automation features to use social_accounts instead of social_media_accounts -- This migration ensures all FK references use the correct table name  -- Check if social_media_conversations exists and fix FK if needed DO $$ BEGIN     -- If table exists but has wrong FK, we need to drop and recreate     IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'social_media_conversations') THEN         -- Check if FK exists and points to wrong table         IF EXISTS (             SELECT 1 FROM information_schema.table_constraints tc             JOIN information_schema.key_column_usage kcu ON tc.constraint_name = kcu.constraint_name             WHERE tc.table_name = 'social_media_conversations'             AND tc.constraint_type = 'FOREIGN KEY'             AND kcu.referenced_table_name = 'social_media_accounts'         ) THEN             -- Drop the constraint             ALTER TABLE social_media_conversations              DROP CONSTRAINT IF EXISTS social_media_conversations_account_id_fkey;                          -- Recreate with correct table             ALTER TABLE social_media_conversations             ADD CONSTRAINT social_media_conversations_account_id_fkey             FOREIGN KEY (account_id) REFERENCES social_accounts(id) ON DELETE CASCADE;         END IF;     END IF; END $$;  -- Same for automation_actions DO $$ BEGIN     IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'automation_actions') THEN         IF EXISTS (             SELECT 1 FROM information_schema.table_constraints tc             JOIN information_schema.key_column_usage kcu ON tc.constraint_name = kcu.constraint_name             WHERE tc.table_name = 'automation_actions'             AND tc.constraint_type = 'FOREIGN KEY'             AND kcu.referenced_table_name = 'social_media_accounts'         ) THEN             ALTER TABLE automation_actions              DROP CONSTRAINT IF EXISTS automation_actions_account_id_fkey;                          ALTER TABLE automation_actions             ADD CONSTRAINT automation_actions_account_id_fkey             FOREIGN KEY (account_id) REFERENCES social_accounts(id) ON DELETE SET NULL;         END IF;     END IF; END $$;  -- Same for message_templates DO $$ BEGIN     IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'message_templates') THEN         IF EXISTS (             SELECT 1 FROM information_schema.table_constraints tc             JOIN information_schema.key_column_usage kcu ON tc.constraint_name = kcu.constraint_name             WHERE tc.table_name = 'message_templates'             AND tc.constraint_type = 'FOREIGN KEY'             AND kcu.referenced_table_name = 'social_media_accounts'         ) THEN             ALTER TABLE message_templates              DROP CONSTRAINT IF EXISTS message_templates_account_id_fkey;                          ALTER TABLE message_templates             ADD CONSTRAINT message_templates_account_id_fkey             FOREIGN KEY (account_id) REFERENCES social_accounts(id) ON DELETE SET NULL;         END IF;     END IF; END $$;"}	fix_automation_features_table_refs
20251224191624	{"-- Add media_project_id column to scheduled_posts ALTER TABLE scheduled_posts  ADD COLUMN IF NOT EXISTS media_project_id UUID;  CREATE INDEX IF NOT EXISTS idx_scheduled_posts_media_project ON scheduled_posts(media_project_id) WHERE media_project_id IS NOT NULL;  COMMENT ON COLUMN scheduled_posts.media_project_id IS 'Reference to media project/collection this post belongs to';"}	add_media_project_id_column
20251224191638	{"-- Create a view to bridge social_accounts and social_media_accounts -- This allows code using social_media_accounts to work with social_accounts  -- First, create social_media_accounts table if it doesn't exist (for backward compatibility) CREATE TABLE IF NOT EXISTS social_media_accounts (     id SERIAL PRIMARY KEY,     platform VARCHAR(50) NOT NULL,     username VARCHAR(255) NOT NULL,     display_name VARCHAR(255),     bio TEXT,     profile_pic_url TEXT,     external_id VARCHAR(255),     is_verified BOOLEAN DEFAULT FALSE,     is_business BOOLEAN DEFAULT FALSE,     is_creator BOOLEAN DEFAULT FALSE,     account_type VARCHAR(50),     email VARCHAR(255),     website_url TEXT,     location VARCHAR(255),     is_active BOOLEAN DEFAULT TRUE,     is_private BOOLEAN DEFAULT FALSE,     monitoring_enabled BOOLEAN DEFAULT TRUE,     blotato_account_id INTEGER,     followers_count INTEGER DEFAULT 0,     following_count INTEGER DEFAULT 0,     posts_count INTEGER DEFAULT 0,     total_views BIGINT DEFAULT 0,     connection_status VARCHAR(50),     connected_via VARCHAR(50),     created_at TIMESTAMP DEFAULT NOW(),     updated_at TIMESTAMP DEFAULT NOW(),     last_fetched_at TIMESTAMP,     last_synced_at TIMESTAMP,     account_created_at TIMESTAMP,     UNIQUE(platform, username) );  CREATE INDEX IF NOT EXISTS idx_social_media_accounts_platform ON social_media_accounts(platform); CREATE INDEX IF NOT EXISTS idx_social_media_accounts_active ON social_media_accounts(is_active);  -- Create a function to sync data from social_accounts to social_media_accounts CREATE OR REPLACE FUNCTION sync_social_accounts_to_legacy() RETURNS TRIGGER AS $$ BEGIN     -- Insert or update in social_media_accounts when social_accounts changes     INSERT INTO social_media_accounts (         platform, username, display_name, profile_pic_url,         external_id, is_active, last_fetched_at, last_synced_at,         updated_at     )     VALUES (         NEW.platform, NEW.handle, NEW.display_name, NEW.avatar_url,         NEW.external_id,          CASE WHEN NEW.status = 'connected' THEN TRUE ELSE FALSE END,         NEW.last_synced_at, NEW.last_synced_at, NOW()     )     ON CONFLICT (platform, username)     DO UPDATE SET         display_name = EXCLUDED.display_name,         profile_pic_url = EXCLUDED.avatar_url,         external_id = EXCLUDED.external_id,         is_active = EXCLUDED.is_active,         last_fetched_at = EXCLUDED.last_fetched_at,         last_synced_at = EXCLUDED.last_synced_at,         updated_at = NOW();          RETURN NEW; END; $$ LANGUAGE plpgsql;  -- Create trigger to auto-sync (optional - can be disabled if causing issues) -- DROP TRIGGER IF EXISTS trg_sync_social_accounts ON social_accounts; -- CREATE TRIGGER trg_sync_social_accounts --     AFTER INSERT OR UPDATE ON social_accounts --     FOR EACH ROW --     EXECUTE FUNCTION sync_social_accounts_to_legacy();"}	create_social_media_accounts_view
20251224191653	{"-- Comprehensive migration test -- Verify all critical tables, columns, and relationships exist  DO $$ DECLARE     test_results TEXT[] := ARRAY[]::TEXT[];     missing_count INTEGER := 0; BEGIN     -- Test 1: Critical tables     IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'event_history') THEN         test_results := array_append(test_results, '❌ Missing: event_history table');         missing_count := missing_count + 1;     ELSE         test_results := array_append(test_results, '✅ event_history table exists');     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'posted_content') THEN         test_results := array_append(test_results, '❌ Missing: posted_content table');         missing_count := missing_count + 1;     ELSE         test_results := array_append(test_results, '✅ posted_content table exists');     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'social_media_conversations') THEN         test_results := array_append(test_results, '❌ Missing: social_media_conversations table');         missing_count := missing_count + 1;     ELSE         test_results := array_append(test_results, '✅ social_media_conversations table exists');     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'automation_actions') THEN         test_results := array_append(test_results, '❌ Missing: automation_actions table');         missing_count := missing_count + 1;     ELSE         test_results := array_append(test_results, '✅ automation_actions table exists');     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'trend_hashtags') THEN         test_results := array_append(test_results, '❌ Missing: trend_hashtags table');         missing_count := missing_count + 1;     ELSE         test_results := array_append(test_results, '✅ trend_hashtags table exists');     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'ai_video_generations') THEN         test_results := array_append(test_results, '❌ Missing: ai_video_generations table');         missing_count := missing_count + 1;     ELSE         test_results := array_append(test_results, '✅ ai_video_generations table exists');     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'agent_events') THEN         test_results := array_append(test_results, '❌ Missing: agent_events table');         missing_count := missing_count + 1;     ELSE         test_results := array_append(test_results, '✅ agent_events table exists');     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'experiments') THEN         test_results := array_append(test_results, '❌ Missing: experiments table');         missing_count := missing_count + 1;     ELSE         test_results := array_append(test_results, '✅ experiments table exists');     END IF;          IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'narrative_goals') THEN         test_results := array_append(test_results, '❌ Missing: narrative_goals table');         missing_count := missing_count + 1;     ELSE         test_results := array_append(test_results, '✅ narrative_goals table exists');     END IF;          -- Test 2: Critical columns     IF NOT EXISTS (         SELECT 1 FROM information_schema.columns          WHERE table_name = 'scheduled_posts' AND column_name = 'source'     ) THEN         test_results := array_append(test_results, '❌ Missing: scheduled_posts.source column');         missing_count := missing_count + 1;     ELSE         test_results := array_append(test_results, '✅ scheduled_posts.source column exists');     END IF;          IF NOT EXISTS (         SELECT 1 FROM information_schema.columns          WHERE table_name = 'scheduled_posts' AND column_name = 'media_project_id'     ) THEN         test_results := array_append(test_results, '❌ Missing: scheduled_posts.media_project_id column');         missing_count := missing_count + 1;     ELSE         test_results := array_append(test_results, '✅ scheduled_posts.media_project_id column exists');     END IF;          IF NOT EXISTS (         SELECT 1 FROM information_schema.columns          WHERE table_name = 'video_analysis' AND column_name = 'deep_analysis'     ) THEN         test_results := array_append(test_results, '❌ Missing: video_analysis.deep_analysis column');         missing_count := missing_count + 1;     ELSE         test_results := array_append(test_results, '✅ video_analysis.deep_analysis column exists');     END IF;          IF NOT EXISTS (         SELECT 1 FROM information_schema.columns          WHERE table_name = 'social_accounts' AND column_name = 'account_role'     ) THEN         test_results := array_append(test_results, '❌ Missing: social_accounts.account_role column');         missing_count := missing_count + 1;     ELSE         test_results := array_append(test_results, '✅ social_accounts.account_role column exists');     END IF;          -- Test 3: Check both account tables exist     IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'social_accounts') THEN         test_results := array_append(test_results, '✅ social_accounts table exists');     END IF;          IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'social_media_accounts') THEN         test_results := array_append(test_results, '✅ social_media_accounts table exists (legacy)');     END IF;          -- Report results     RAISE NOTICE '';     RAISE NOTICE '========================================';     RAISE NOTICE 'MIGRATION TEST RESULTS';     RAISE NOTICE '========================================';     RAISE NOTICE '';          FOR i IN 1..array_length(test_results, 1) LOOP         RAISE NOTICE '%', test_results[i];     END LOOP;          RAISE NOTICE '';     RAISE NOTICE '========================================';     IF missing_count = 0 THEN         RAISE NOTICE '✅ ALL TESTS PASSED - All migrations applied successfully!';     ELSE         RAISE NOTICE '⚠️  % missing items found', missing_count;     END IF;     RAISE NOTICE '========================================'; END $$;"}	test_all_migrations_comprehensive
20251224191938	{"-- Create automation tables with correct FK types -- automation_actions (account_id references UUID, not INTEGER) CREATE TABLE IF NOT EXISTS automation_actions (     id SERIAL PRIMARY KEY,     account_id UUID REFERENCES social_accounts(id) ON DELETE SET NULL,     platform VARCHAR(50) NOT NULL DEFAULT 'tiktok',     action_type VARCHAR(50) NOT NULL,     target_type VARCHAR(50),     target_id VARCHAR(255),     target_url TEXT,     target_username VARCHAR(255),     content_text TEXT,     success BOOLEAN DEFAULT TRUE,     error_message TEXT,     error_code VARCHAR(50),     session_id VARCHAR(255),     triggered_by VARCHAR(50),     action_date DATE DEFAULT CURRENT_DATE,     action_hour INTEGER DEFAULT EXTRACT(HOUR FROM NOW()),     execution_time_ms INTEGER,     created_at TIMESTAMP DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_actions_account_date ON automation_actions(account_id, action_date); CREATE INDEX IF NOT EXISTS idx_actions_type ON automation_actions(action_type); CREATE INDEX IF NOT EXISTS idx_actions_target ON automation_actions(target_type, target_id); CREATE INDEX IF NOT EXISTS idx_actions_success ON automation_actions(success); CREATE INDEX IF NOT EXISTS idx_actions_date_hour ON automation_actions(action_date, action_hour);  -- social_media_conversations (account_id references UUID) CREATE TABLE IF NOT EXISTS social_media_conversations (     id SERIAL PRIMARY KEY,     account_id UUID NOT NULL REFERENCES social_accounts(id) ON DELETE CASCADE,     platform VARCHAR(50) NOT NULL DEFAULT 'tiktok',     participant_username VARCHAR(255) NOT NULL,     participant_id VARCHAR(255),     participant_display_name VARCHAR(255),     participant_avatar_url TEXT,     participant_verified BOOLEAN DEFAULT FALSE,     last_message_at TIMESTAMP,     last_message_preview TEXT,     last_message_is_outgoing BOOLEAN,     unread_count INTEGER DEFAULT 0,     is_muted BOOLEAN DEFAULT FALSE,     is_archived BOOLEAN DEFAULT FALSE,     is_blocked BOOLEAN DEFAULT FALSE,     is_spam BOOLEAN DEFAULT FALSE,     auto_reply_enabled BOOLEAN DEFAULT FALSE,     follow_up_scheduled_at TIMESTAMP,     conversation_started_at TIMESTAMP,     created_at TIMESTAMP DEFAULT NOW(),     updated_at TIMESTAMP DEFAULT NOW(),     UNIQUE(account_id, platform, participant_username) );  CREATE INDEX IF NOT EXISTS idx_conversations_account ON social_media_conversations(account_id); CREATE INDEX IF NOT EXISTS idx_conversations_platform ON social_media_conversations(platform); CREATE INDEX IF NOT EXISTS idx_conversations_last_msg ON social_media_conversations(last_message_at DESC); CREATE INDEX IF NOT EXISTS idx_conversations_unread ON social_media_conversations(unread_count) WHERE unread_count > 0;  -- social_media_messages CREATE TABLE IF NOT EXISTS social_media_messages (     id SERIAL PRIMARY KEY,     conversation_id INTEGER NOT NULL REFERENCES social_media_conversations(id) ON DELETE CASCADE,     external_message_id VARCHAR(255),     message_text TEXT,     message_type VARCHAR(50) DEFAULT 'text',     media_url TEXT,     media_thumbnail_url TEXT,     is_outgoing BOOLEAN NOT NULL,     sender_username VARCHAR(255),     status VARCHAR(50) DEFAULT 'sent',     is_read BOOLEAN DEFAULT FALSE,     sent_at TIMESTAMP NOT NULL,     delivered_at TIMESTAMP,     read_at TIMESTAMP,     reply_to_message_id INTEGER REFERENCES social_media_messages(id),     metadata JSONB,     is_automated BOOLEAN DEFAULT FALSE,     template_used VARCHAR(255),     created_at TIMESTAMP DEFAULT NOW(),     UNIQUE(conversation_id, external_message_id) );  CREATE INDEX IF NOT EXISTS idx_messages_conversation ON social_media_messages(conversation_id); CREATE INDEX IF NOT EXISTS idx_messages_sent_at ON social_media_messages(sent_at DESC); CREATE INDEX IF NOT EXISTS idx_messages_outgoing ON social_media_messages(is_outgoing); CREATE INDEX IF NOT EXISTS idx_messages_status ON social_media_messages(status);"}	create_automation_tables_fixed_types
20251224234207	{"-- Add missing columns to scheduled_posts for API compatibility -- These columns are expected by the schedule API endpoint  ALTER TABLE scheduled_posts  ADD COLUMN IF NOT EXISTS content_id TEXT, ADD COLUMN IF NOT EXISTS title TEXT, ADD COLUMN IF NOT EXISTS caption TEXT, ADD COLUMN IF NOT EXISTS hashtags JSONB DEFAULT '[]'::jsonb, ADD COLUMN IF NOT EXISTS thumbnail_url TEXT, ADD COLUMN IF NOT EXISTS account_id TEXT, ADD COLUMN IF NOT EXISTS account_username TEXT, ADD COLUMN IF NOT EXISTS account_avatar TEXT, ADD COLUMN IF NOT EXISTS scheduled_at TIMESTAMP WITH TIME ZONE, ADD COLUMN IF NOT EXISTS post_type TEXT DEFAULT 'reel';  -- Create index on content_id for lookups CREATE INDEX IF NOT EXISTS idx_scheduled_posts_content_id ON scheduled_posts(content_id);  -- Update scheduled_at from scheduled_time if needed UPDATE scheduled_posts  SET scheduled_at = scheduled_time  WHERE scheduled_at IS NULL AND scheduled_time IS NOT NULL;  COMMENT ON COLUMN scheduled_posts.content_id IS 'Media/content ID (alternative to clip_id/content_variant_id)'; COMMENT ON COLUMN scheduled_posts.title IS 'Post title'; COMMENT ON COLUMN scheduled_posts.caption IS 'Post caption/description'; COMMENT ON COLUMN scheduled_posts.hashtags IS 'Array of hashtags for the post'; COMMENT ON COLUMN scheduled_posts.account_id IS 'Account ID (alternative to platform_account_id)'; COMMENT ON COLUMN scheduled_posts.account_username IS 'Account username';"}	add_schedule_api_columns
20251225002706	{"-- Schedule Slots (individual posts in a plan) CREATE TABLE IF NOT EXISTS schedule_slots (     id UUID PRIMARY KEY DEFAULT gen_random_uuid(),     schedule_id UUID REFERENCES weekly_schedules(id) ON DELETE CASCADE,          video_id UUID,     video_title TEXT,     platform TEXT NOT NULL,     scheduled_date DATE NOT NULL,     scheduled_time TEXT NOT NULL,     pillar TEXT,     selection_reason TEXT,     expected_engagement FLOAT,          actual_post_id UUID,     actual_engagement FLOAT,          created_at TIMESTAMPTZ DEFAULT NOW() );  CREATE INDEX IF NOT EXISTS idx_schedule_slots_schedule ON schedule_slots(schedule_id); CREATE INDEX IF NOT EXISTS idx_schedule_slots_date ON schedule_slots(scheduled_date);"}	create_schedule_slots_table
