--
-- Name: v_recent_runs _RETURN; Type: RULE; Schema: public; Owner: -
--

CREATE OR REPLACE VIEW public.v_recent_runs AS
 SELECT r.id,
    r.agent_type,
    r.status,
    r.progress_current,
    r.progress_total,
    r.started_at,
    r.finished_at,
    s.schedule_name,
    count(DISTINCT st.id) AS step_count,
    count(DISTINCT
        CASE
            WHEN ((st.status)::text = 'completed'::text) THEN st.id
            ELSE NULL::uuid
        END) AS completed_steps
   FROM ((public.agent_runs r
     LEFT JOIN public.agent_schedules s ON ((r.schedule_id = s.id)))
     LEFT JOIN public.agent_steps st ON ((st.run_id = r.id)))
  WHERE (r.created_at >= (now() - '7 days'::interval))
  GROUP BY r.id, r.agent_type, r.status, r.progress_current, r.progress_total, r.started_at, r.finished_at, s.schedule_name
  ORDER BY r.created_at DESC;


